// Content for Respect at Home (node g56, ages 22+, Chapter 7): NEW v2 build to GDD 56 (mechanic-embodying), the
// CHAPTER'S HIGHEST-SAFEGUARDING node: it carries the consent thread into marriage and committed partnership, the
// place consent is most often assumed away. Marriage doesn't cancel consent, and love is never control. 84
// researched, India-grounded scenarios across respect-daily → consent-inside → spot-abuse-control →
// safety-and-help → never-your-fault → tools-and-help, each encoded as one of the shared v2 play actions
// (strike-rewrite / branch / role-play / sort / reflect / spot / match): no binary "tap the right card". Lead:
// strike-rewrite (bust the myth), branch (your move), role-play (say it). Five modes: respect daily (mutual
// respect & an equal voice), consent inside (married is NOT standing consent; UN&RE), spot abuse & control (the
// forms of domestic abuse (emotional, financial, sexual, physical) and coercive control; it's never love),
// safety & help (recognising danger, safety-planning basics, where to get help, NO blame), tools/help. HIGH-STAKES
// & survivor-centred throughout: NEVER victim-blaming (abuse is always the perpetrator's responsibility), urgent
// disclosure routing (181, 1091, 112), even-handed across genders (men and others can be victims and are
// especially silenced), strictly non-graphic. Protections framed around India's Protection of Women from Domestic
// Violence Act 2005 (covering physical, emotional, sexual & economic abuse: protection orders & maintenance); the
// marital-consent CRIMINAL-law landscape is contested and evolving, so this is educational, not legal advice.
// Safety-planning handled with care: risk can RISE at leaving. Builds on Mutual (g31) and Consent, For Real (g44);
// the protective backbone of Chapter 7 (g55 routes coercive control here). gameId "respect-at-home".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"rh-001","cat":"respect-daily","type":"sort","persona":"any","source":"respect markers","relearn":"Both opinions counting and disagreeing safely is respect; one person deciding and eggshells is its absence.","hook":"Sort: mutual respect at home, or its absence?","items":[{"id":"a","text":"Both partners' opinions count"},{"id":"b","text":"One person decides everything"},{"id":"c","text":"You can disagree safely"},{"id":"d","text":"You walk on eggshells"},{"id":"e","text":"Each of you is heard out"},{"id":"f","text":"Your views are brushed aside"}],"bins":[{"id":"respect","label":"Respect","valence":"pos"},{"id":"absence","label":"Its absence","valence":"neg"}],"key":{"a":"respect","b":"absence","c":"respect","d":"absence","e":"respect","f":"absence"}},
  {"id":"rh-002","cat":"respect-daily","type":"reflect","hook":"Lensy: respect, an equal voice and safety belong inside the home as much as anywhere. Agree?","prompt":"What do you think?","options":["Yes","At home too","An equal voice"],"affirm":"Respect, an equal voice and safety don't stop at your front door; they belong inside the home.","relearn":"Respect, an equal voice and safety belong inside the home as much as anywhere.","persona":"any","source":"home too"},
  {"id":"rh-003","cat":"respect-daily","type":"branch","hook":"Your partner expects all the household decisions to be theirs alone.","options":[{"text":"Establish that big decisions are made together","consequence":"You claim your equal voice.","outcome":"equal-voice","best":true},{"text":"Defer on everything to keep the peace","consequence":"Establishing that big decisions are joint is your equal voice; deferring on everything erodes it."}],"debrief":"An equal voice in decisions, money and plans is part of a respectful partnership.","relearn":"Big decisions should be made together; you have an equal voice.","persona":"any","source":"equal voice"},
  {"id":"rh-004","cat":"respect-daily","type":"strike-rewrite","hook":"\"Once you're married, you give up your own rights and autonomy.\"","myth":{"un":"Once married, you give up your own rights and autonomy.","re":"You keep your rights, autonomy and dignity inside a marriage; partnership doesn't erase them.","why":"A wedding ring isn't a surrender of self."},"relearn":"You keep your rights, autonomy and dignity inside a marriage.","persona":"Reshma","source":"keep your autonomy"},
  {"id":"rh-005","cat":"respect-daily","type":"sort","persona":"any","source":"respect vs warning","relearn":"Feeling safe and having your needs taken seriously is respectful; fear and money control are warnings.","hook":"Sort: a sign of a respectful home, or a warning?","items":[{"id":"a","text":"You feel safe to be yourself"},{"id":"b","text":"You fear your partner's reactions"},{"id":"c","text":"Your needs are taken seriously"},{"id":"d","text":"Your money is controlled for you"},{"id":"e","text":"You can speak your mind freely"},{"id":"f","text":"You hide things to avoid a row"}],"bins":[{"id":"respect","label":"Respectful","valence":"pos"},{"id":"warning","label":"Warning","valence":"neg"}],"key":{"a":"respect","b":"warning","c":"respect","d":"warning","e":"respect","f":"warning"}},
  {"id":"rh-006","cat":"respect-daily","type":"branch","hook":"You want to build a home where both of you feel genuinely respected.","options":[{"text":"Make space for both voices, needs and choices","consequence":"You set a respectful foundation.","outcome":"respectful","best":true},{"text":"Let one person's word always rule","consequence":"Making space for both voices and choices builds respect; one person always ruling doesn't."}],"debrief":"A respectful home actively makes room for both partners' voices, needs and choices.","relearn":"Make space for both voices, needs and choices to build a respectful home.","persona":"any","source":"building respect"},
  {"id":"rh-007","cat":"respect-daily","type":"reflect","hook":"Lensy: in a healthy partnership, your partner is glad you have your own mind, money and friends. Recognise that?","prompt":"What do you think?","options":["Yes","Glad I'm me","Healthy"],"affirm":"A good partner welcomes your independence, your mind, money and friendships; that's real respect.","relearn":"A healthy partner is glad you keep your own mind, money and friends.","persona":"any","source":"welcomes independence"},
  {"id":"rh-008","cat":"consent-inside","type":"strike-rewrite","hook":"\"Marriage means standing, automatic consent.\"","myth":{"un":"Marriage means standing, automatic consent.","re":"Consent is ongoing inside marriage; you can say no any time, and your body is yours.","why":"A relationship is not blanket permission."},"relearn":"Consent is ongoing inside marriage; you can say no any time, and your body is yours.","persona":"any","source":"not standing consent"},
  {"id":"rh-009","cat":"consent-inside","type":"strike-rewrite","hook":"\"Forcing sex within marriage isn't really a violation.\"","myth":{"un":"Forcing sex within marriage isn't really a violation.","re":"Coercing sex is a violation of consent and dignity, regardless of marital status or the law's current state.","why":"Your body remains your own inside a marriage."},"relearn":"Coercing sex within marriage is a violation of consent and dignity; your body remains yours.","persona":"Reshma","source":"marital consent"},
  {"id":"rh-010","cat":"consent-inside","type":"branch","hook":"Your partner insists you 'owe' them sex because you're married.","options":[{"text":"Hold that consent is yours to give, always","consequence":"You keep your bodily autonomy.","outcome":"autonomy","best":true},{"text":"Give in because you feel obligated","consequence":"Consent is always yours to give; marriage never makes it an obligation you owe."}],"debrief":"No one is 'owed' sex by marriage; consent is freely given, every time, inside a relationship too.","relearn":"You never 'owe' sex; consent is yours to give, always, marriage or not.","persona":"any","source":"never owed"},
  {"id":"rh-011","cat":"consent-inside","type":"reflect","hook":"Lensy: consent doesn't expire at the wedding, it stays yours for life. Land clearly?","prompt":"What do you think?","options":["Yes","Stays mine","Doesn't expire"],"affirm":"Your consent is yours for life; it never expires or transfers because of a marriage.","relearn":"Consent doesn't expire at the wedding; it stays yours for life.","persona":"any","source":"never expires"},
  {"id":"rh-012","cat":"consent-inside","type":"role-play","hook":"You want to say no to your partner without it becoming a fight.","setup":"Be clear and calm. Say:","yourLine":[{"text":"\"Not tonight, I'm not feeling it, and that's okay.\"","best":true},{"text":"Go along with it to avoid conflict"}],"relearn":"You can calmly say no to your partner; a respectful partner accepts it.","persona":"any","source":"saying no"},
  {"id":"rh-013","cat":"consent-inside","type":"sort","hook":"Sort each: respects consent inside a relationship, or ignores it?","items":[{"id":"a","text":"Checking in and accepting a no"},{"id":"b","text":"Pressuring after a no"},{"id":"c","text":"Stopping when asked"},{"id":"d","text":"Treating marriage as permission"},{"id":"e","text":"Waiting for a real, willing yes"},{"id":"f","text":"Guilt-tripping until they give in"}],"bins":[{"id":"respects","label":"Respects consent","valence":"pos"},{"id":"ignores","label":"Ignores it","valence":"neg"}],"key":{"a":"respects","b":"ignores","c":"respects","d":"ignores","e":"respects","f":"ignores"},"relearn":"Checking in, stopping when asked, and waiting for a willing yes respect consent; pressuring, treating marriage as permission, or guilt-tripping ignore it.","persona":"any","source":"consent inside"},
  {"id":"rh-014","cat":"consent-inside","type":"branch","hook":"You feel unsure whether you're even allowed to say no to your spouse.","options":[{"text":"Know that you always can; your consent is yours","consequence":"You reclaim your right to say no.","outcome":"clear","best":true},{"text":"Assume marriage took that right away","consequence":"You always can say no; marriage never takes away your right to your own consent."}],"debrief":"You are always allowed to say no inside a marriage; that right is never given up.","relearn":"You can always say no to your spouse; that right is never given up.","persona":"Reshma","source":"you can say no"},
  {"id":"rh-015","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"It's only abuse if it's physical.\"","myth":{"un":"It's only abuse if it's physical.","re":"Emotional, sexual, economic and coercive-control abuse are all real domestic abuse, recognised by law.","why":"Harm comes in many forms, not only bruises."},"relearn":"Emotional, sexual, economic and coercive-control abuse are all real domestic abuse.","persona":"any","source":"all forms"},
  {"id":"rh-016","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"Controlling the money is just practical, or the man's role.\"","myth":{"un":"Controlling all the money is just practical.","re":"Controlling money and denying independence is economic abuse, a recognised form of domestic violence.","why":"Money used to control is a tool of abuse."},"relearn":"Controlling money and denying independence is economic abuse, a form of domestic violence.","persona":"Reshma","source":"economic abuse"},
  {"id":"rh-017","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"Love sometimes looks like jealousy, monitoring and control.\"","myth":{"un":"Love sometimes looks like jealousy, monitoring and control.","re":"Coercion, monitoring, isolation and control are abuse, not love.","why":"Real love trusts and frees; control polices."},"relearn":"Coercion, monitoring, isolation and control are abuse, not love.","persona":"any","source":"never love"},
  {"id":"rh-018","cat":"spot-abuse-control","type":"spot","persona":"any","source":"spotting control","relearn":"Tracking your movements and isolating you from people is coercive control; ordinary interest and trust aren't.","hook":"Spot the two red flags of coercive control.","scene":[{"id":"a","text":"Tracking your location and contacts","trick":true},{"id":"b","text":"Asking how your day was","trick":false},{"id":"c","text":"Cutting you off from family and friends","trick":true},{"id":"d","text":"Trusting you out with friends","trick":false},{"id":"e","text":"Being glad you have your own plans","trick":false}],"why":"Tracking your movements and isolating you from people is coercive control; ordinary interest and trust aren't."},
  {"id":"rh-019","cat":"spot-abuse-control","type":"sort","persona":"any","source":"is it abuse","relearn":"Constant humiliation, withholding money and threats are abuse; a fair disagreement, shared decisions and trust aren't.","hook":"Sort: a form of domestic abuse, or not?","items":[{"id":"a","text":"Constant insults and humiliation"},{"id":"b","text":"A fair disagreement"},{"id":"c","text":"Withholding money to control you"},{"id":"d","text":"Sharing decisions openly"},{"id":"e","text":"Threats to keep you in line"},{"id":"f","text":"Trusting each other freely"}],"bins":[{"id":"abuse","label":"Domestic abuse","valence":"neg"},{"id":"not","label":"Not abuse","valence":"pos"}],"key":{"a":"abuse","b":"not","c":"abuse","d":"not","e":"abuse","f":"not"}},
  {"id":"rh-020","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"They only get controlling because they love me so much.\"","myth":{"un":"They only get controlling because they love me.","re":"Control isn't a sign of love; it's a sign of abuse, and it tends to escalate.","why":"Devotion doesn't require surveillance or fear."},"relearn":"Control isn't love; it's abuse, and it tends to escalate.","persona":"any","source":"control isn't love"},
  {"id":"rh-021","cat":"spot-abuse-control","type":"spot","persona":"any","source":"emotional abuse","relearn":"Disguised put-downs and 'worthless without me' are emotional abuse; honest, kind words aren't.","hook":"Spot the two lines that are emotional abuse.","scene":[{"id":"a","text":"Constant put-downs disguised as jokes","trick":true},{"id":"b","text":"Honest, kind feedback","trick":false},{"id":"c","text":"\"You're worthless without me\"","trick":true},{"id":"d","text":"\"I value what you bring\"","trick":false},{"id":"e","text":"\"Take the time you need\"","trick":false}],"why":"Disguised put-downs and 'worthless without me' are emotional abuse; honest, kind words aren't."},
  {"id":"rh-022","cat":"spot-abuse-control","type":"sort","persona":"any","source":"care vs control","relearn":"Trusting your life and welcoming friends is care; monitoring you, dictating choices and tracking you is control.","hook":"Sort: care, or control dressed as care?","items":[{"id":"a","text":"Trusting you with your own life"},{"id":"b","text":"Monitoring your phone and movements"},{"id":"c","text":"Being glad you have friends"},{"id":"d","text":"Deciding what you can wear or do"},{"id":"e","text":"Giving you space and privacy"},{"id":"f","text":"Tracking where you go all day"}],"bins":[{"id":"care","label":"Care","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"care","b":"control","c":"care","d":"control","e":"care","f":"control"}},
  {"id":"rh-023","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"What happens in a marriage is private; outsiders shouldn't be involved.\"","myth":{"un":"What happens in a marriage is private; no one should get involved.","re":"Abuse is not a private family matter; 'private' is not a shield, and help and legal protection exist.","why":"Privacy must never cover for harm."},"relearn":"Abuse isn't a private matter; 'private' is no shield, and help and protection exist.","persona":"Razia","source":"private is no shield"},
  {"id":"rh-024","cat":"spot-abuse-control","type":"branch","hook":"You're noticing early signs of control that you'd been brushing off.","options":[{"text":"Take them seriously and name them honestly","consequence":"You see the pattern early.","outcome":"clear","best":true},{"text":"Keep telling yourself it's normal","consequence":"Naming early control honestly, rather than normalising it, is how you protect yourself early."}],"debrief":"Early signs of control are easy to normalise; naming them honestly is the first protection.","relearn":"Take early signs of control seriously and name them honestly.","persona":"Reshma","source":"early signs"},
  {"id":"rh-025","cat":"safety-and-help","type":"branch","hook":"You may be in an abusive situation and feel frightened.","options":[{"text":"Reach out for help; you're not alone and it's not your fault","consequence":"You connect with real support.","outcome":"supported","best":true},{"text":"Stay silent and try to manage alone","consequence":"Help (181, 1091, 112, a trusted person) is real support; you're not alone, it's not your fault."}],"debrief":"Frightened? Reaching out to a helpline or trusted person is brave; it's never your fault.","relearn":"Frightened? Reach out (181, 1091, 112); you're not alone, and it's not your fault.","persona":"any","source":"reaching for help"},
  {"id":"rh-026","cat":"safety-and-help","type":"reflect","hook":"Lensy: abuse can escalate, especially around leaving, so safety planning matters. Important to know?","prompt":"What do you think?","options":["Yes","Plan for safety","Risk rises at leaving"],"affirm":"Knowing that risk can rise around leaving, and planning for safety, is vital, careful knowledge.","relearn":"Abuse can escalate, especially around leaving; safety planning matters.","persona":"any","source":"risk rises at leaving"},
  {"id":"rh-027","cat":"safety-and-help","type":"sort","hook":"Sort: part of a safety plan, or not?","items":[{"id":"a","text":"A safe place you can go"},{"id":"b","text":"Confronting them alone when angry"},{"id":"c","text":"Key documents and a small bag ready"},{"id":"d","text":"Hoping it just stops"},{"id":"e","text":"A code word with a trusted person"},{"id":"f","text":"Telling no one and managing alone"}],"bins":[{"id":"plan","label":"Safety plan","valence":"pos"},{"id":"not","label":"Not safe","valence":"neg"}],"key":{"a":"plan","b":"not","c":"plan","d":"not","e":"plan","f":"not"},"relearn":"A safe place, key documents and a code word are part of a safety plan; confronting them alone or just hoping isn't.","persona":"any","source":"safety plan"},
  {"id":"rh-028","cat":"safety-and-help","type":"branch","hook":"You want to be ready in case things become dangerous.","options":[{"text":"Quietly prepare: a trusted contact, documents, a code word","consequence":"You build a safety net.","outcome":"prepared","best":true},{"text":"Assume it won't come to that","consequence":"Quietly preparing a trusted contact, documents and a code word builds a safety net, just in case."}],"debrief":"A quiet safety plan, a trusted contact, documents, a code word, a safe place, is wise preparation.","relearn":"Quietly prepare a safety net: a trusted contact, documents, a code word, a safe place.","persona":"any","source":"preparing"},
  {"id":"rh-029","cat":"safety-and-help","type":"role-play","hook":"You need to set up a code word with a trusted friend for emergencies.","setup":"Arrange it quietly. Say:","yourLine":[{"text":"\"If I ever text you this word, please call and check on me or send help.\"","best":true},{"text":"Tell no one in case it gets back to them"}],"relearn":"Set up a code word with a trusted friend so they can act if you're in danger.","persona":"any","source":"code word"},
  {"id":"rh-030","cat":"safety-and-help","type":"branch","hook":"You're keeping a record of incidents but worry it's pointless.","options":[{"text":"Keep a dated record and save evidence safely","consequence":"You strengthen any future case and protection.","outcome":"documented","best":true},{"text":"Don't bother documenting anything","consequence":"A dated record and saved evidence (screenshots, messages) can support protection orders later; it's not pointless."}],"debrief":"A dated record and saved evidence, stored safely, can support protection orders and help under the DV Act.","relearn":"Keep a dated record and save evidence safely; it can support protection later.","persona":"any","source":"documenting safely"},
  {"id":"rh-031","cat":"safety-and-help","type":"match","hook":"Match the need to where help lives (India).","pairs":[{"left":"In danger right now","right":"Emergency 112"},{"left":"Domestic violence support","right":"Women Helpline 181"},{"left":"A woman in distress","right":"1091"},{"left":"Free legal advice you can't pay for","right":"NALSA legal aid 15100"},{"left":"Someone close who knows you","right":"A trusted person"}],"relearn":"112 for immediate danger, 181 for DV support, 1091 in distress, 15100 for free legal aid, plus a trusted person.","persona":"any","source":"help routes"},
  {"id":"rh-032","cat":"safety-and-help","type":"reflect","hook":"Lensy: whether and when to leave is the survivor's own decision, and any choice deserves support. Agree?","prompt":"What do you think?","options":["Yes","Their choice","Support either way"],"affirm":"Whether and when to leave is the survivor's decision; every choice deserves support, never pressure.","relearn":"Whether and when to leave is the survivor's own decision, and deserves support.","persona":"any","source":"their decision"},
  {"id":"rh-033","cat":"safety-and-help","type":"match","hook":"Match the need to its real route (India).","pairs":[{"left":"Know your rights in depth","right":"Free legal aid (NALSA)"},{"left":"Stop the violence","right":"A protection order"},{"left":"Stay in your home","right":"A residence order"},{"left":"Money to live on","right":"A maintenance order"},{"left":"Support at any hour","right":"Women Helpline 181"}],"relearn":"Free legal aid, plus protection, residence and maintenance orders under the DV Act 2005, and 181, are real routes.","persona":"Razia","source":"the DV Act"},
  {"id":"rh-034","cat":"never-your-fault","type":"strike-rewrite","hook":"\"If they hurt me, I must have provoked it.\"","myth":{"un":"If they hurt me, I must have provoked it.","re":"Abuse is never the victim's fault; the responsibility lies only with the abuser.","why":"Nothing you do justifies being abused."},"relearn":"Abuse is never the victim's fault; responsibility lies only with the abuser.","persona":"any","source":"never your fault"},
  {"id":"rh-035","cat":"never-your-fault","type":"strike-rewrite","hook":"\"Men can't be victims of domestic abuse.\"","myth":{"un":"Men can't be victims of domestic abuse.","re":"Anyone of any gender can be a victim, and male and other survivors are especially silenced.","why":"Abuse isn't defined by the victim's gender."},"relearn":"Anyone of any gender can be a victim of domestic abuse and deserves support.","persona":"any","source":"even-handed"},
  {"id":"rh-036","cat":"never-your-fault","type":"role-play","hook":"A friend confides they're being abused and blames themselves.","setup":"Be clear and warm. Say:","yourLine":[{"text":"\"This is not your fault. The only person responsible is the one hurting you. I'm here.\"","best":true},{"text":"\"What did you do to set them off?\""}],"relearn":"Tell a survivor it's not their fault; the responsibility is only the abuser's.","persona":"any","source":"no blame"},
  {"id":"rh-037","cat":"never-your-fault","type":"strike-rewrite","hook":"\"A good wife or husband just endures it for the family.\"","myth":{"un":"A good spouse just endures abuse for the family.","re":"No one should endure abuse; safety and dignity come first, and help exists.","why":"Family is never a reason to suffer harm."},"relearn":"No one should endure abuse for the family; safety and dignity come first.","persona":"Reshma","source":"don't endure it"},
  {"id":"rh-038","cat":"never-your-fault","type":"branch","hook":"You experienced abuse and feel deep shame about it.","options":[{"text":"Remind yourself the shame belongs to the abuser, not you","consequence":"You release misplaced shame.","outcome":"freed","best":true},{"text":"Carry the shame as if it's yours","consequence":"The shame belongs to the person who abused you, never to you; you deserve support, not shame."}],"debrief":"Survivors often carry shame that belongs entirely to the abuser; releasing it is part of healing.","relearn":"The shame of abuse belongs to the abuser, never to you.","persona":"any","source":"misplaced shame"},
  {"id":"rh-039","cat":"never-your-fault","type":"role-play","hook":"A male friend hints he's being abused but fears no one will believe him.","setup":"Believe him fully. Say:","yourLine":[{"text":"\"I believe you, this is real and it's not your fault, and you deserve help.\"","best":true},{"text":"\"Come on, that doesn't happen to men.\""}],"relearn":"Believe male and other survivors fully; abuse is real and never their fault.","persona":"any","source":"believe all survivors"},
  {"id":"rh-040","cat":"never-your-fault","type":"spot","hook":"Spot the two things that wrongly decide fault by blaming the victim.","scene":[{"id":"a","text":"The abuser's choice to abuse","trick":false},{"id":"b","text":"What the victim wore or said","trick":true},{"id":"c","text":"Only the person doing the harm","trick":false},{"id":"d","text":"Whether the victim 'provoked' it","trick":true},{"id":"e","text":"The abuser's decision to control","trick":false}],"why":"'What the victim wore or said' and 'whether they provoked it' never decide fault; only the abuser's choice does.","relearn":"Nothing you wore, said or did makes abuse your fault; only the abuser's choice decides fault.","persona":"any","source":"nothing justifies it"},
  {"id":"rh-041","type":"match","persona":"any","source":"the forms","hook":"Match each form of abuse to its description.","pairs":[{"left":"Economic abuse","right":"Controlling money, denying independence"},{"left":"Emotional abuse","right":"Insults, threats, humiliation"},{"left":"Coercive control","right":"Monitoring, isolation, surveillance"},{"left":"Sexual abuse","right":"Forcing or coercing sex"},{"left":"Physical abuse","right":"Hitting, shoving, restraining"}],"relearn":"Economic, emotional, coercive-control, sexual and physical abuse each have clear, recognisable forms.","cat":"tools-and-help"},
  {"id":"rh-042","type":"sort","persona":"Razia","source":"real help","hook":"Sort each one: a real source of help, or not?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"Just bottling it up"},{"id":"c","text":"A women's-rights or legal-aid worker"},{"id":"d","text":"Hoping the abuser changes"},{"id":"e","text":"Free legal aid on 15100"},{"id":"f","text":"Pretending nothing is wrong"}],"bins":[{"id":"real","label":"Real help","valence":"pos"},{"id":"not","label":"Not help","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"181, a legal-aid worker and 15100 are real help; bottling up, hoping he changes or pretending aren't.","cat":"tools-and-help"},
  {"id":"rh-043","cat":"tools-and-help","type":"reflect","hook":"Lensy: this is education and signposting, not legal advice, and the marital-consent law is still evolving. Clear?","prompt":"What do you think?","options":["Yes","Get real help","Law is evolving"],"affirm":"This points you to real help and the law; for an actual case, qualified or free legal aid is the right step.","relearn":"This is education and signposting, not legal advice; the marital-consent law is still evolving.","persona":"any","source":"not legal advice"},
  {"id":"rh-044","cat":"tools-and-help","type":"branch","hook":"A friend is in an abusive relationship and doesn't know help exists.","options":[{"text":"Gently share the routes: 181, a counsellor, the DV Act","consequence":"You open a door to safety.","outcome":"connected","best":true},{"text":"Stay out of it; it's their marriage","consequence":"Gently sharing the routes (181, a counsellor, the DV Act) can be the lifeline a friend in an abusive marriage needs."}],"debrief":"Knowing help exists, and where, can be exactly what gets a friend toward safety.","relearn":"Gently share the help routes (181, a counsellor, the DV Act) with a friend in an abusive relationship.","persona":"any","source":"sharing routes"},
  {"id":"rh-045","type":"match","persona":"Razia","source":"DV Act remedies","hook":"Match each need to what the DV Act 2005 can offer.","pairs":[{"left":"Stop the violence","right":"A protection order"},{"left":"Financial support","right":"Maintenance"},{"left":"A right to stay safely","right":"A residence order"},{"left":"Cover losses from the abuse","right":"Monetary relief"},{"left":"Settle the children's care","right":"A custody order"}],"relearn":"The DV Act 2005 can offer protection, maintenance, residence, monetary relief and custody orders.","cat":"tools-and-help"},
  {"id":"rh-046","cat":"tools-and-help","type":"reflect","hook":"Lensy: respect, an equal voice, consent and safety, these belong to you at home, always. Believe it?","prompt":"What do you think?","options":["Yes","They're mine","Always"],"affirm":"Respect, an equal voice, consent and safety are yours at home, always; never settle below them.","relearn":"Respect, an equal voice, consent and safety belong to you at home, always.","persona":"any","source":"they're yours"},
  {"id":"rh-047","type":"spot","persona":"any","source":"supportive response","hook":"A survivor just confided in you. Spot the two responses that BLAME her.","scene":[{"id":"a","text":"\"I believe you, it's not your fault\"","trick":false},{"id":"b","text":"\"What did you do to provoke it?\"","trick":true},{"id":"c","text":"\"You deserve safety and support\"","trick":false},{"id":"d","text":"\"You should have just kept him happy\"","trick":true},{"id":"e","text":"\"What do you need from me?\"","trick":false}],"why":"'What did you do' and 'kept him happy' blame her; abuse is never the survivor's fault.","relearn":"Belief and 'you deserve safety' support a survivor; blame questions don't.","cat":"tools-and-help"},
  {"id":"rh-048","type":"match","persona":"any","source":"carry forward","hook":"Match each home truth to what it protects.","pairs":[{"left":"Marriage isn't standing consent","right":"Your bodily autonomy"},{"left":"Control isn't love","right":"Your freedom"},{"left":"Help exists","right":"Your safety"},{"left":"It's never your fault","right":"Your dignity"},{"left":"An equal voice belongs at home","right":"Your say"}],"relearn":"Marriage isn't standing consent, control isn't love, it's never your fault, and help exists.","cat":"tools-and-help"},
  {"id":"rh-049","cat":"respect-daily","type":"sort","persona":"any","source":"your voice counts","relearn":"Your views shaping decisions and both being heard is an equal voice; routine dismissal or being overridden is silencing.","hook":"Sort: an equal voice, or being silenced?","items":[{"id":"a","text":"Your views shape decisions"},{"id":"b","text":"Your opinions routinely dismissed"},{"id":"c","text":"Both of you are heard"},{"id":"d","text":"One voice always overrides"},{"id":"e","text":"You can raise a concern openly"},{"id":"f","text":"You're told to keep quiet"}],"bins":[{"id":"voice","label":"Equal voice","valence":"pos"},{"id":"silenced","label":"Silenced","valence":"neg"}],"key":{"a":"voice","b":"silenced","c":"voice","d":"silenced","e":"voice","f":"silenced"}},
  {"id":"rh-050","cat":"consent-inside","type":"strike-rewrite","hook":"\"Saying no to your spouse is being a bad partner.\"","myth":{"un":"Saying no to your spouse makes you a bad partner.","re":"You can lovingly say no; a respectful partner accepts it, consent stays yours.","why":"A no is not a betrayal of the relationship."},"relearn":"You can lovingly say no to your spouse; a respectful partner accepts it.","persona":"any","source":"no isn't bad"},
  {"id":"rh-051","cat":"spot-abuse-control","type":"branch","hook":"A relative tells you the control in your marriage is 'just how husbands are'.","options":[{"text":"Reject the normalising; control isn't normal or okay","consequence":"You refuse to accept abuse as normal.","outcome":"clear","best":true},{"text":"Accept it as just how it is","consequence":"Rejecting 'that's just how husbands are' refuses to normalise control, which is never normal or okay."}],"debrief":"Normalising control as 'just how they are' keeps people trapped; naming it as wrong is the first step out.","relearn":"Don't accept control as 'just how husbands are'; it's never normal or okay.","persona":"Reshma","source":"refusing to normalise"},
  {"id":"rh-052","cat":"safety-and-help","type":"role-play","hook":"You're ready to reach out to a helpline but are scared.","setup":"You can keep it simple. Say:","yourLine":[{"text":"\"I think I'm being abused at home and I need help and to know my options.\"","best":true},{"text":"Hang up before anyone answers"}],"relearn":"A simple 'I think I'm being abused and I need help' is enough to start.","persona":"any","source":"making the call"},
  {"id":"rh-053","cat":"never-your-fault","type":"sort","hook":"Sort: a supportive thing to tell a survivor, or a harmful one?","items":[{"id":"a","text":"\"It's not your fault\""},{"id":"b","text":"\"Why don't you just leave?\""},{"id":"c","text":"\"I'm here, what do you need?\""},{"id":"d","text":"\"You must have done something\""},{"id":"e","text":"\"I believe you\""},{"id":"f","text":"\"You always make him angry\""}],"bins":[{"id":"supportive","label":"Supportive","valence":"pos"},{"id":"harmful","label":"Harmful","valence":"neg"}],"key":{"a":"supportive","b":"harmful","c":"supportive","d":"harmful","e":"supportive","f":"harmful"},"relearn":"'Not your fault', 'what do you need?' and 'I believe you' support; 'just leave', 'you must have done something', 'you make him angry' harm.","persona":"any","source":"what to say"},
  {"id":"rh-054","cat":"tools-and-help","type":"branch","hook":"You want to support a survivor without taking over their choices.","options":[{"text":"Believe them, ask what they need, respect their pace","consequence":"You give safe, survivor-led support.","outcome":"survivor-led","best":true},{"text":"Decide and act for them","consequence":"Believing them, asking what they need and respecting their pace is survivor-led support; taking over isn't."}],"debrief":"Survivor-centred support believes, asks what's needed, and respects the survivor's own choices and pace.","relearn":"Believe a survivor, ask what they need, and respect their pace; don't take over.","persona":"Saxena","source":"survivor-led"},
  {"id":"rh-055","cat":"spot-abuse-control","type":"spot","persona":"Reshma","source":"financial abuse","relearn":"Taking your earnings and blocking access to work or money is financial abuse; open sharing and your own account aren't.","hook":"Spot the two red flags of financial abuse.","scene":[{"id":"a","text":"Taking all your earnings, giving an 'allowance'","trick":true},{"id":"b","text":"Sharing money decisions openly","trick":false},{"id":"c","text":"Blocking you from working or an account","trick":true},{"id":"d","text":"Planning the budget together","trick":false},{"id":"e","text":"Being glad you have savings","trick":false}],"why":"Taking your earnings and blocking access to work or money is financial abuse; open sharing and your own account aren't."},
  {"id":"rh-056","cat":"consent-inside","type":"reflect","hook":"Lensy: a loving partner never needs to pressure or coerce; they wait for a real yes. Recognise that?","prompt":"What do you think?","options":["Yes","Waits for yes","Never coerces"],"affirm":"Real love waits for a genuine yes and never coerces; that's the standard inside marriage too.","relearn":"A loving partner never pressures or coerces; they wait for a real yes.","persona":"any","source":"waits for yes"},
  {"id":"rh-057","cat":"respect-daily","type":"sort","persona":"any","source":"equal vs one-sided","relearn":"Both deciding money and shaping choices is an equal voice; one controlling finances or always having the final word isn't.","hook":"Sort: an equal voice in the home, or a one-sided power?","items":[{"id":"a","text":"Both decide how money is spent"},{"id":"b","text":"One controls all the finances"},{"id":"c","text":"Both opinions shape big choices"},{"id":"d","text":"One person's word is final, always"},{"id":"e","text":"Plans are agreed by both of you"},{"id":"f","text":"One sets the rules for the other"}],"bins":[{"id":"equal","label":"Equal voice","valence":"pos"},{"id":"onesided","label":"One-sided power","valence":"neg"}],"key":{"a":"equal","b":"onesided","c":"equal","d":"onesided","e":"equal","f":"onesided"}},
  {"id":"rh-058","cat":"never-your-fault","type":"branch","hook":"You worry that reporting abuse will 'break up the family' and it'll be your fault.","options":[{"text":"Know that the abuse, not your reporting, is what harms the family","consequence":"You release a false guilt.","outcome":"clear","best":true},{"text":"Stay silent to 'keep the family together'","consequence":"The abuse, not your reporting it, is what harms the family; your safety isn't a betrayal."}],"debrief":"Seeking safety doesn't break a family; the abuse does. Your wellbeing is never the thing to sacrifice.","relearn":"The abuse, not your reporting it, is what harms a family; your safety isn't a betrayal.","persona":"Reshma","source":"not your fault to report"},
  {"id":"rh-059","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"Nothing can really be done legally about abuse in a marriage.\"","myth":{"un":"Nothing can be done legally about abuse in a marriage.","re":"The Domestic Violence Act 2005 offers real civil protections, protection orders, maintenance and residence rights.","why":"The law provides concrete remedies."},"relearn":"The DV Act 2005 offers real protections: protection orders, maintenance and residence rights.","persona":"Razia","source":"the law can help"},
  {"id":"rh-060","cat":"safety-and-help","type":"branch","hook":"Little money or privacy makes reaching out feel impossible.","options":[{"text":"Use discreet, free routes: 181, a trusted person, legal aid","consequence":"You find a safe path despite the barriers.","outcome":"reached","best":true},{"text":"Conclude help is out of reach","consequence":"Discreet, free routes (181, a trusted person, legal aid) exist for these barriers; help is reachable."}],"debrief":"Even with little money or privacy, discreet free routes can still reach you.","relearn":"Little money or privacy? Discreet free routes (181, a trusted person, legal aid) can help.","persona":"Reshma","source":"reaching the most at-risk"},
  {"id":"rh-061","cat":"respect-daily","type":"reflect","hook":"Lensy: you deserve to feel safe, heard and respected in your own home. Believe that for yourself?","prompt":"What do you think?","options":["Yes","I deserve that","Safe and heard"],"affirm":"You absolutely deserve to feel safe, heard and respected at home; never accept less.","relearn":"You deserve to feel safe, heard and respected in your own home.","persona":"any","source":"you deserve safety"},
  {"id":"rh-062","cat":"consent-inside","type":"branch","hook":"Your partner sulks or punishes you whenever you say no to intimacy.","options":[{"text":"Recognise that punishment for a no is coercion, not love","consequence":"You see the pattern clearly.","outcome":"clear","best":true},{"text":"Give in each time to avoid the punishment","consequence":"Punishment for a no is coercion, not love; giving in to avoid it isn't real consent."}],"debrief":"Being punished for saying no turns 'consent' into coercion; that isn't a free yes.","relearn":"Punishment for saying no is coercion, not love; a coerced yes isn't consent.","persona":"any","source":"coercion not consent"},
  {"id":"rh-063","cat":"spot-abuse-control","type":"sort","persona":"any","source":"control warning signs","relearn":"Approving who you see, checking your phone and demanding permission are coercive control; trust, privacy and freedom are healthy.","hook":"Sort: a warning sign of coercive control, or healthy?","items":[{"id":"a","text":"Needing to approve who you see"},{"id":"b","text":"Trusting your friendships"},{"id":"c","text":"Checking your phone constantly"},{"id":"d","text":"Respecting your privacy"},{"id":"e","text":"Demanding permission to go out"},{"id":"f","text":"Welcoming your own free time"}],"bins":[{"id":"warning","label":"Warning sign","valence":"uhoh"},{"id":"healthy","label":"Healthy","valence":"pos"}],"key":{"a":"warning","b":"healthy","c":"warning","d":"healthy","e":"warning","f":"healthy"}},
  {"id":"rh-064","cat":"never-your-fault","type":"role-play","hook":"A survivor fears you'll judge their choices about staying or leaving.","setup":"Offer compassion, not judgement. Say:","yourLine":[{"text":"\"Whatever you decide, I'm with you, no judgement, just support.\"","best":true},{"text":"\"You have to leave right now.\""}],"relearn":"Whatever a survivor decides, they deserve compassion, never judgement.","persona":"any","source":"compassion not judgement"},
  {"id":"rh-065","type":"sort","persona":"any","source":"the commitment","hook":"Sort each one: this game's commitment, or against it?","items":[{"id":"a","text":"Abuse is never the victim's fault"},{"id":"b","text":"Blaming survivors"},{"id":"c","text":"Routing danger to real help"},{"id":"d","text":"Treating abuse as private"},{"id":"e","text":"Believing survivors of any gender"},{"id":"f","text":"Pushing someone to leave"}],"bins":[{"id":"for","label":"Its commitment","valence":"pos"},{"id":"against","label":"Against it","valence":"neg"}],"key":{"a":"for","b":"against","c":"for","d":"against","e":"for","f":"against"},"relearn":"No-blame, routing danger to help and believing any survivor is the commitment; blaming, 'it's private' or pushing aren't.","cat":"tools-and-help"},
  {"id":"rh-066","cat":"respect-daily","type":"role-play","hook":"You want to set a respectful tone of equal voice with your partner.","setup":"Name it warmly. Say:","yourLine":[{"text":"\"Let's make decisions together as equals, both our voices matter here.\"","best":true},{"text":"Let one of you quietly dominate"}],"relearn":"Name an equal-voice intention early; both partners' voices should matter.","persona":"any","source":"equal-voice tone"},
  {"id":"rh-067","cat":"consent-inside","type":"sort","hook":"Sort: respects bodily autonomy in marriage, or violates it?","items":[{"id":"a","text":"Accepting a no without punishment"},{"id":"b","text":"Coercing or pressuring sex"},{"id":"c","text":"Checking in about what each wants"},{"id":"d","text":"Treating marriage as entitlement"},{"id":"e","text":"Letting a partner set the pace"},{"id":"f","text":"Forcing intimacy when they're asleep"}],"bins":[{"id":"respects","label":"Respects autonomy","valence":"pos"},{"id":"violates","label":"Violates it","valence":"neg"}],"key":{"a":"respects","b":"violates","c":"respects","d":"violates","e":"respects","f":"violates"},"relearn":"Accepting a no, checking in, and letting a partner set the pace respect bodily autonomy; coercion, entitlement, and forcing it on someone asleep violate it.","persona":"any","source":"bodily autonomy"},
  {"id":"rh-068","cat":"spot-abuse-control","type":"spot","persona":"any","source":"it counts","relearn":"'Visible bruises only' and 'a sorry undoes it' are false; control, coercion and humiliation count, and the pattern defines it.","hook":"Spot the two false beliefs about what counts as abuse.","scene":[{"id":"a","text":"It controls, coerces or humiliates you","trick":false},{"id":"b","text":"It must leave visible bruises to count","trick":true},{"id":"c","text":"It harms or frightens you","trick":false},{"id":"d","text":"A sorry afterwards undoes the harm","trick":true},{"id":"e","text":"Fear can be inflicted without a touch","trick":false}],"why":"'Visible bruises only' and 'a sorry undoes it' are false; control, coercion and humiliation count, and the pattern defines it."},
  {"id":"rh-069","cat":"never-your-fault","type":"strike-rewrite","hook":"\"If they were really abusive, you'd have left already.\"","myth":{"un":"If they were really abusive, you'd have left already.","re":"Leaving is complex and dangerous; staying doesn't mean it isn't abuse or that it's your fault.","why":"Many reasons, fear, money, children, make leaving hard."},"relearn":"Staying doesn't mean it isn't abuse; leaving is complex and dangerous, and it's never your fault.","persona":"any","source":"why people stay"},
  {"id":"rh-070","cat":"safety-and-help","type":"reflect","hook":"Lensy: if you're ever in immediate danger, reaching for emergency help (112) is always the right call. Clear?","prompt":"What do you think?","options":["Yes","112 for danger","Always right"],"affirm":"In immediate danger, calling emergency help (112) is always right; your safety comes first.","relearn":"In immediate danger, reaching for emergency help (112) is always the right call.","persona":"any","source":"immediate danger"},
  {"id":"rh-071","cat":"respect-daily","type":"match","persona":"any","source":"equals not hierarchy","relearn":"A respectful marriage is a partnership of equals, not a leader-and-follower hierarchy.","hook":"Match the marriage belief to whether it's equal or a hierarchy.","pairs":[{"left":"Both voices matter","right":"An equal partnership"},{"left":"Decisions made together","right":"Shared power"},{"left":"One leads, one follows","right":"A hierarchy"},{"left":"One's word is always final","right":"One-sided control"},{"left":"Each can disagree safely","right":"Mutual respect"}]},
  {"id":"rh-072","cat":"consent-inside","type":"role-play","hook":"You want to talk openly with your partner about consent within your marriage.","setup":"Open it gently. Say:","yourLine":[{"text":"\"I want us to always check in with each other, a real yes from both of us, every time.\"","best":true},{"text":"Assume it never needs discussing"}],"relearn":"Talk openly about ongoing consent in marriage: a real yes from both, every time.","persona":"any","source":"the consent talk"},
  {"id":"rh-073","cat":"spot-abuse-control","type":"spot","persona":"any","source":"shrinks your world","relearn":"Control that shrinks your world and jealousy dressed as love are abuse; love that expands you, with freedom and trust, isn't.","hook":"Spot the two that are control, not devotion.","scene":[{"id":"a","text":"Control that shrinks your world","trick":true},{"id":"b","text":"Love that expands it","trick":false},{"id":"c","text":"Jealousy dressed up as devotion","trick":true},{"id":"d","text":"Freedom and trust","trick":false},{"id":"e","text":"Support for your own friendships","trick":false}],"why":"Control that shrinks your world and jealousy dressed as love are abuse; love that expands you, with freedom and trust, isn't."},
  {"id":"rh-074","cat":"never-your-fault","type":"role-play","hook":"You're supporting a survivor who keeps minimising what's happening to them.","setup":"Gently reflect the seriousness, without pushing. Say:","yourLine":[{"text":"\"What you're describing sounds serious and not okay, and I'm here whenever you're ready.\"","best":true},{"text":"\"I'm sure it's not that bad.\""}],"relearn":"Gently name that a survivor's experience is serious and not okay, without pushing them.","persona":"Saxena","source":"naming seriousness gently"},
  {"id":"rh-075","type":"match","persona":"any","source":"support steps","hook":"Match each survivor-support step to why it matters.","pairs":[{"left":"\"I believe you\"","right":"Belief is what survivors fear losing"},{"left":"\"It's not your fault\"","right":"Lifts misplaced shame"},{"left":"Signpost help","right":"Connects to real safety"},{"left":"\"What do you need?\"","right":"Keeps the choice theirs"},{"left":"\"I'll go at your pace\"","right":"Respects their timing"}],"relearn":"Belief, removing blame, signposting, asking and pacing are why the survivor-support steps matter.","cat":"tools-and-help"},
  {"id":"rh-076","cat":"safety-and-help","type":"branch","hook":"A friend in danger asks you to keep their abuse secret and do nothing.","options":[{"text":"Stay supportive and help them reach real safety options","consequence":"You honour them while connecting them to help.","outcome":"supported","best":true},{"text":"Promise to do nothing at all","consequence":"Staying supportive while helping them toward safety beats doing nothing about real danger."}],"debrief":"You can respect a survivor's choices while still helping them toward safety and real support.","relearn":"Stay supportive and help a friend in danger reach safety options.","persona":"any","source":"supporting safely"},
  {"id":"rh-077","cat":"never-your-fault","type":"role-play","hook":"A survivor feels the abuse defines who they are.","setup":"Reflect their worth back. Say:","yourLine":[{"text":"\"You are not what was done to you, that reflects the abuser, not your worth.\"","best":true},{"text":"\"Maybe you brought some of it on.\""}],"relearn":"You are not what was done to you; abuse reflects the abuser, not your worth.","persona":"any","source":"your worth intact"},
  {"id":"rh-078","cat":"respect-daily","type":"branch","hook":"You want your home to be a place of safety and respect for both of you.","options":[{"text":"Build mutual respect, an equal voice and consent into daily life","consequence":"You make home genuinely safe.","outcome":"safe-home","best":true},{"text":"Let power and control creep in unchecked","consequence":"Building mutual respect, an equal voice and consent daily makes home safe; unchecked power and control don't."}],"debrief":"A safe, respectful home is built day by day through equal voice, consent and mutual respect.","relearn":"Build mutual respect, an equal voice and consent into daily life for a safe home.","persona":"any","source":"a safe home"},
  {"id":"rh-079","cat":"consent-inside","type":"strike-rewrite","hook":"\"Your partner's needs always come before your own no.\"","myth":{"un":"Your partner's needs always come before your own no.","re":"Your no matters as much as their wants; consent is mutual, not one-sided.","why":"No one's desires override another's consent."},"relearn":"Your no matters as much as their wants; consent is mutual, not one-sided.","persona":"any","source":"your no matters"},
  {"id":"rh-080","cat":"spot-abuse-control","type":"strike-rewrite","hook":"\"A bit of jealousy and checking up is healthy in a marriage.\"","myth":{"un":"A bit of jealousy and checking up is healthy.","re":"Monitoring and possessiveness aren't healthy; trust and freedom are the signs of a good marriage.","why":"Surveillance erodes the trust a marriage needs."},"relearn":"Monitoring and possessiveness aren't healthy; trust and freedom are.","persona":"any","source":"not healthy jealousy"},
  {"id":"rh-081","cat":"safety-and-help","type":"match","hook":"Match the safety-plan piece to its purpose.","pairs":[{"left":"A code word","right":"Signals a trusted person to act"},{"left":"Key documents ready","right":"Lets you leave quickly if needed"},{"left":"A dated record","right":"Supports protection later"},{"left":"A safe place to go","right":"Somewhere to reach in a hurry"},{"left":"A little money set aside","right":"Covers the first steps away"}],"relearn":"A code word, ready documents, a dated record, a safe place and a little money each serve a clear safety purpose.","persona":"any","source":"safety-plan pieces"},
  {"id":"rh-082","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing the forms of abuse and where to get help could protect you, or someone you love. Worth carrying?","prompt":"What do you think?","options":["Yes","Could protect us","Worth carrying"],"affirm":"This knowledge, the forms of abuse and where help lives, is genuinely protective, for you and others.","relearn":"Knowing the forms of abuse and where to get help is genuinely protective.","persona":"any","source":"protective knowledge"},
  {"id":"rh-083","cat":"never-your-fault","type":"branch","hook":"You're starting to heal after leaving an abusive relationship.","options":[{"text":"Be gentle with yourself and lean on support","consequence":"You heal at your own pace.","outcome":"healing","best":true},{"text":"Blame yourself for how long it took","consequence":"Being gentle with yourself and leaning on support helps you heal; self-blame for the time it took doesn't."}],"debrief":"Healing after abuse takes time and self-compassion; you got out, and that's what matters.","relearn":"Be gentle with yourself and lean on support as you heal after abuse.","persona":"any","source":"healing"},
  {"id":"rh-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: marriage doesn't cancel consent, love is never control, and help always exists. Carry which truth home?","prompt":"What will you carry?","options":["Consent is ongoing","Love is never control","Never the victim's fault","Help always exists"],"affirm":"Carry that truth home, and you help make every home, yours or another's, a place of respect and safety.","relearn":"Consent is ongoing, love is never control, it's never your fault, and help always exists.","persona":"any","source":"carry home"},
  {"id":"rh-900","cat":"consent-inside","type":"strike-rewrite","hook":"\"Once you're married, the wedding is a yes to everything.\"","myth":{"un":"The wedding was a yes to everything, forever.","re":"A wedding is not standing consent; each yes is fresh, and you can say no any day.","why":"Consent is given moment to moment, not signed away once."},"relearn":"A wedding is not standing consent; each yes is fresh and you can say no any day.","persona":"any","source":"signature flip"},
  {"id":"rh-901","cat":"consent-inside","type":"strike-rewrite","hook":"\"A wife can't refuse her husband; that's her duty.\"","myth":{"un":"A wife can't refuse her husband; that's her duty.","re":"Refusal is always allowed; intimacy is shared, never a duty one owes the other.","why":"Your body stays yours; duty never overrides a no."},"relearn":"Refusal is always allowed; intimacy is shared, never a duty one partner owes the other.","persona":"Reshma","source":"not a duty"},
  {"id":"rh-902","cat":"consent-inside","type":"strike-rewrite","hook":"\"If you said yes last night, you can't say no tonight.\"","myth":{"un":"Yesterday's yes counts for tonight too.","re":"A past yes is not a permanent yes; consent is fresh each time and can change.","why":"Yesterday never binds today's choice."},"relearn":"A past yes is not a permanent yes; consent is fresh each time and can change.","persona":"any","source":"past yes"},
  {"id":"rh-903","cat":"consent-inside","type":"strike-rewrite","hook":"\"It's our marriage, our private matter; consent doesn't apply.\"","myth":{"un":"It's a private marriage, so consent doesn't apply.","re":"'Private' is no shield; consent applies fully inside a marriage too.","why":"Closed doors never cancel a person's right to choose."},"relearn":"'Private' is no shield; consent applies fully inside a marriage.","persona":"any","source":"private no shield"},
  {"id":"rh-904","cat":"consent-inside","type":"strike-rewrite","hook":"\"He provides for the home, so intimacy is what he's owed.\"","myth":{"un":"He provides, so intimacy is what he's owed.","re":"Providing buys nothing; a body is never owed in exchange for support.","why":"Money and care never purchase someone's consent."},"relearn":"Providing for a home buys nothing; a body is never owed in exchange for support.","persona":"Reshma","source":"never bought"},
  {"id":"rh-905","cat":"consent-inside","type":"strike-rewrite","hook":"\"Men can't be refused or coerced; consent is only a women's issue.\"","myth":{"un":"Consent inside marriage is only a women's issue.","re":"Consent is even-handed; a husband can decline too, and his no counts equally.","why":"Anyone of any gender keeps the right to say no."},"relearn":"Consent is even-handed; a husband can decline too, and his no counts equally.","persona":"any","source":"even-handed"},
  {"id":"rh-906","cat":"consent-inside","type":"strike-rewrite","hook":"\"Begging, sulking till she gives in, that's just how marriage works.\"","myth":{"un":"Wearing someone down till they give in is just normal marriage.","re":"Wearing someone down isn't consent; a yes given to end the pressure isn't free.","why":"A worn-down yes is pressure, not a real choice."},"relearn":"Wearing someone down isn't consent; a yes given to end pressure isn't free.","persona":"any","source":"worn down"},
  {"id":"rh-907","cat":"consent-inside","type":"strike-rewrite","hook":"\"Threatening to find someone else if she says no is fair pressure.\"","myth":{"un":"Threatening to look elsewhere if she refuses is fair.","re":"A threat is coercion, not persuasion; a yes under threat is not consent.","why":"Fear is the opposite of a free yes."},"relearn":"A threat is coercion, not persuasion; a yes given under threat is not consent.","persona":"any","source":"threat coercion"},
  {"id":"rh-908","cat":"consent-inside","type":"strike-rewrite","hook":"\"After a baby she has to be ready whenever he wants.\"","myth":{"un":"After a baby she has to be ready whenever he wants.","re":"Recovery, tiredness or just not wanting to are all complete reasons; her no stands.","why":"No reason is ever required to decline."},"relearn":"Recovery, tiredness or simply not wanting to are complete reasons; a no needs no justification.","persona":"Reshma","source":"no reason needed"},
  {"id":"rh-909","cat":"consent-inside","type":"strike-rewrite","hook":"\"Once you've started, you can't stop or change your mind.\"","myth":{"un":"Once you've started, you can't stop or change your mind.","re":"You can withdraw consent at any point; a respectful partner stops at once.","why":"A yes can be taken back the moment it stops being true."},"relearn":"You can withdraw consent at any point; a respectful partner stops at once.","persona":"any","source":"withdraw anytime"},
  {"id":"rh-910","cat":"consent-inside","type":"strike-rewrite","hook":"\"The law settled long ago that there's no such thing as marital rape.\"","myth":{"un":"The law settled long ago that marital coercion isn't a violation.","re":"India's marital-consent law is contested and evolving; coercion is always wrong regardless.","why":"Right and wrong don't wait on a court date."},"relearn":"India's marital-consent law is contested and evolving (educational, not legal advice); coercion is always wrong regardless.","persona":"Razia","source":"law evolving"},
  {"id":"rh-911","cat":"consent-inside","type":"strike-rewrite","hook":"\"Saying no will break the home, so it's safer to never refuse.\"","myth":{"un":"Saying no will break the home, so never refuse.","re":"A home built on someone's silenced no isn't safe; your no is allowed to be heard.","why":"Peace bought with your silence isn't real peace."},"relearn":"A home built on a silenced no isn't safe; your no is always allowed to be heard.","persona":"Reshma","source":"silence isn't peace"},
  {"id":"rh-912","cat":"consent-inside","type":"strike-rewrite","hook":"\"If she really loved him she'd never say no.\"","myth":{"un":"Real love means never saying no.","re":"Love includes hearing a no without punishing it; refusal isn't a lack of love.","why":"A no and love can live in the same person."},"relearn":"Love includes hearing a no without punishing it; refusal is not a lack of love.","persona":"any","source":"no isn't unloving"},
  {"id":"rh-913","cat":"consent-inside","type":"strike-rewrite","hook":"\"Married couples don't need to ask; asking is awkward.\"","myth":{"un":"Married couples don't need to ask; it's awkward.","re":"Checking in stays kind and normal in marriage; a quick 'is this okay?' honours both.","why":"Asking is care, not awkwardness."},"relearn":"Checking in stays kind and normal in marriage; asking is care, not awkwardness.","persona":"any","source":"asking is care"},
  {"id":"rh-914","cat":"consent-inside","type":"strike-rewrite","hook":"\"A drunk or asleep spouse still counts as a yes since you're married.\"","myth":{"un":"An asleep or very drunk spouse still counts as a yes.","re":"Someone asleep or heavily drunk can't consent; marriage doesn't change that.","why":"A yes needs an awake, willing person."},"relearn":"Someone asleep or heavily drunk cannot consent; marriage doesn't change that.","persona":"any","source":"can't consent"},
  {"id":"rh-915","cat":"consent-inside","type":"strike-rewrite","hook":"\"He apologised after, so forcing it last night doesn't count.\"","myth":{"un":"He apologised after, so forcing it doesn't count.","re":"An apology doesn't erase a violation; forcing intimacy was still a breach of consent.","why":"Sorry afterward can't turn a no into a yes."},"relearn":"An apology doesn't erase a violation; forced intimacy was still a breach of consent.","persona":"any","source":"apology doesn't erase"},
  {"id":"rh-916","cat":"consent-inside","type":"strike-rewrite","hook":"\"Talking about consent is for unmarried people, not us.\"","myth":{"un":"Talking about consent is only for unmarried people.","re":"Ongoing consent matters most where it's assumed away: inside marriage.","why":"The closer the bond, the more a real yes deserves care."},"relearn":"Ongoing consent matters most where it's assumed away, inside marriage.","persona":"Saxena","source":"matters most here"},
  {"id":"rh-920","cat":"consent-inside","type":"branch","hook":"Your spouse says yes to intimacy but seems checked-out and reluctant.","options":[{"text":"Pause and gently check that they truly want to","consequence":"You make space for an honest yes or no.","outcome":"checks in","best":true},{"text":"Take the words as a yes and carry on","consequence":"A reluctant, checked-out 'yes' may not be real consent; checking in protects you both."}],"debrief":"A real yes is willing, not just spoken; pausing to check honours your partner.","relearn":"A real yes is willing, not merely spoken; pausing to check honours both of you.","persona":"any","source":"enthusiastic yes"},
  {"id":"rh-921","cat":"consent-inside","type":"branch","hook":"Your in-laws hint that giving your husband a child soon is your 'wifely duty'.","options":[{"text":"Hold that your body and timing are your choice","consequence":"You keep decisions about your own body.","outcome":"holds line","best":true},{"text":"Accept that the family decides your body's timing","consequence":"Your body and its timing stay yours; relatives' wishes never override your consent."}],"debrief":"Pressure to conceive on someone else's timeline doesn't override your consent over your own body.","relearn":"Pressure from relatives never overrides your consent; your body and its timing stay yours.","persona":"Reshma","source":"family pressure"},
  {"id":"rh-922","cat":"consent-inside","type":"branch","hook":"Your partner wants intimacy; you're exhausted and say not tonight.","options":[{"text":"Trust that your no is enough on its own","consequence":"You honour your own limit without guilt.","outcome":"no is enough","best":true},{"text":"Invent an elaborate excuse so it sounds acceptable","consequence":"Your no needs no excuse; 'not tonight' is a complete answer on its own."}],"debrief":"You don't owe a justification for a no; 'not tonight' is reason enough.","relearn":"You don't owe a justification for a no; 'not tonight' is a complete answer.","persona":"any","source":"no needs no excuse"},
  {"id":"rh-923","cat":"consent-inside","type":"branch","hook":"Your spouse keeps bringing up intimacy you've declined, until you feel cornered.","options":[{"text":"Name the pressure and ask them to stop","consequence":"You make the coercion visible and reclaim space.","outcome":"names it","best":true},{"text":"Give in just to end the nagging","consequence":"A yes given only to stop the pressure isn't free consent; naming the pressure is fairer to you both."}],"debrief":"Repeated pressure after a no is coercion; you can name it and ask for it to stop.","relearn":"Repeated pressure after a no is coercion, not romance; you can name it and ask it to stop.","persona":"any","source":"name the pressure"},
  {"id":"rh-924","cat":"consent-inside","type":"branch","hook":"Mid-intimacy, something doesn't feel right and you want to stop.","options":[{"text":"Say 'stop' and trust it will be respected","consequence":"You exercise the right to withdraw at any point.","outcome":"withdraws","best":true},{"text":"Stay silent and wait for it to be over","consequence":"You can withdraw consent at any moment; saying stop is always allowed and should be respected."}],"debrief":"Consent can be withdrawn any time; 'stop' is a full sentence a partner must respect.","relearn":"Consent can be withdrawn at any moment; 'stop' is a full sentence a partner must respect.","persona":"any","source":"stop anytime"},
  {"id":"rh-925","cat":"consent-inside","type":"branch","hook":"As a husband, you don't feel like intimacy tonight; you worry refusing isn't 'manly'.","options":[{"text":"Decline calmly; your no counts as much as anyone's","consequence":"You see consent is even-handed.","outcome":"his no counts","best":true},{"text":"Force yourself because a man should always be up for it","consequence":"A man's no counts equally; consent isn't a performance you owe to prove masculinity."}],"debrief":"Consent is even-handed; a husband's no is valid and never a failure of manhood.","relearn":"Consent is even-handed; a husband's no is fully valid and never a failure of manhood.","persona":"any","source":"his no counts"},
  {"id":"rh-926","cat":"consent-inside","type":"branch","hook":"Your partner says 'we're married, you can't refuse me' during an argument.","options":[{"text":"State that marriage never removed your right to say no","consequence":"You hold a clear, calm boundary.","outcome":"reclaims right","best":true},{"text":"Believe them and assume you've lost that right","consequence":"Marriage never removes the right to say no; that right stays yours for life."}],"debrief":"No vow ever signed away your right to refuse; that right stays yours inside marriage.","relearn":"No vow ever signed away your right to refuse; that right stays yours for life.","persona":"Reshma","source":"reclaim right"},
  {"id":"rh-927","cat":"consent-inside","type":"branch","hook":"After a fight, your spouse expects 'make-up' intimacy you don't want.","options":[{"text":"Say you'd rather talk and reconnect first","consequence":"You set the pace honestly without owing anything.","outcome":"sets pace","best":true},{"text":"Go along so the fight finally ends","consequence":"Intimacy isn't owed to settle a fight; a yes traded for peace isn't free consent."}],"debrief":"You don't owe intimacy to end a conflict; a yes traded for peace isn't a free yes.","relearn":"You don't owe intimacy to end a conflict; a yes traded for peace isn't free consent.","persona":"any","source":"not owed for peace"},
  {"id":"rh-928","cat":"consent-inside","type":"branch","hook":"You want to ask your partner what they're comfortable with, but fear it sounds cold.","options":[{"text":"Ask warmly: 'tell me what feels right for you'","consequence":"You open honest, ongoing consent together.","outcome":"opens talk","best":true},{"text":"Guess and assume rather than risk an awkward question","consequence":"Asking is warmth, not coldness; checking in builds trust and a real, shared yes."}],"debrief":"Asking what a partner wants is intimacy, not awkwardness; it builds a real shared yes.","relearn":"Asking what a partner wants is intimacy, not awkwardness; it builds a real, shared yes.","persona":"Saxena","source":"asking is warmth"},
  {"id":"rh-929","cat":"consent-inside","type":"branch","hook":"Your spouse threatens to leave if you keep saying no to intimacy.","options":[{"text":"Recognise the threat as coercion, not a fair choice","consequence":"You see the pressure for what it is.","outcome":"sees coercion","best":true},{"text":"Give in to keep them from leaving","consequence":"A yes given under threat of leaving isn't free consent; that pressure is coercion, not love."}],"debrief":"Threatening to leave to extract a yes is coercion; a fearful yes isn't real consent.","relearn":"A yes given under threat of leaving isn't free consent; that pressure is coercion, not love.","persona":"any","source":"threat to leave"},
  {"id":"rh-930","cat":"consent-inside","type":"branch","hook":"You realise a past night where you felt forced still weighs on you.","options":[{"text":"Name it: that wasn't consent, and not your fault","consequence":"You start to see it clearly, without blame.","outcome":"names it","best":true},{"text":"Tell yourself it was fine because you're married","consequence":"Marriage doesn't turn force into consent; naming it is the first step, and it wasn't your fault."}],"debrief":"Force is still a violation inside marriage; naming it isn't disloyalty.","relearn":"Force is still a violation inside marriage; naming it is the first step, and it was never your fault.","persona":"any","source":"naming it"},
  {"id":"rh-931","cat":"consent-inside","type":"branch","hook":"Your partner says other couples don't 'make a fuss' about consent, so why should you.","options":[{"text":"Keep your standard: a real yes matters here","consequence":"You hold a healthy norm regardless of others.","outcome":"holds norm","best":true},{"text":"Drop it because 'everyone' does it that way","consequence":"What others do doesn't set your limits; a willing yes is the standard worth keeping."}],"debrief":"'Everyone does it' doesn't make coercion okay; a willing yes is the standard to keep.","relearn":"What other couples do doesn't set your limits; a real, willing yes is the standard to keep.","persona":"any","source":"set your own norm"},
  {"id":"rh-940","cat":"consent-inside","type":"reflect","hook":"Lensy: your body stays yours after the wedding, never owed to anyone. Sit with that?","prompt":"What lands for you?","options":["Stays mine","Never owed","Yes"],"affirm":"Your body remains your own inside marriage; it is never owed, and a yes is always yours to give or keep.","relearn":"Your body remains your own inside marriage; it is never owed.","persona":"any","source":"body stays yours"},
  {"id":"rh-941","cat":"consent-inside","type":"reflect","hook":"Lensy: a yes can change to a no any time, even mid-moment, and that's okay. Feel that?","prompt":"How does that sit?","options":["That's okay","Can change","Yes"],"affirm":"Consent can change at any time; you're allowed to pause or stop, and a caring partner respects it.","relearn":"Consent can change at any time; you're allowed to pause or stop whenever.","persona":"any","source":"can change"},
  {"id":"rh-942","cat":"consent-inside","type":"reflect","hook":"Lensy: 'not tonight' is a whole answer; it needs no reason. Notice how that feels.","prompt":"What comes up?","options":["No reason needed","Whole answer","Yes"],"affirm":"A no is complete on its own; you never owe an excuse for not wanting intimacy.","relearn":"A no is complete on its own; you never owe an excuse for it.","persona":"any","source":"complete no"},
  {"id":"rh-943","cat":"consent-inside","type":"reflect","hook":"Lensy: asking 'is this okay?' in marriage is care, not coldness. What do you make of that?","prompt":"Your take?","options":["It's care","Not cold","Yes"],"affirm":"Checking in is a warm habit, not an awkward one; a quick 'is this okay?' honours you both.","relearn":"Checking in is a warm habit, not an awkward one; it honours you both.","persona":"any","source":"checking in is warm"},
  {"id":"rh-944","cat":"consent-inside","type":"reflect","hook":"Lensy: a husband's no counts as much as anyone's; consent goes both ways. Recognise that?","prompt":"What do you think?","options":["Both ways","His counts too","Yes"],"affirm":"Consent is even-handed; a partner of any gender can say no, and that no is always respected.","relearn":"Consent is even-handed; a partner of any gender can say no and be respected.","persona":"any","source":"both ways"},
  {"id":"rh-945","cat":"consent-inside","type":"reflect","hook":"Lensy: a yes you gave just to stop the pressure was never really free. Sit with that.","prompt":"What surfaces?","options":["Not free","Pressure isn't yes","Yes"],"affirm":"A yes given only to end pressure isn't free consent, and seeing that clearly isn't disloyal.","relearn":"A yes given only to end pressure isn't free consent.","persona":"any","source":"pressured yes"},
  {"id":"rh-946","cat":"consent-inside","type":"reflect","hook":"Lensy: love hears a no without sulking or punishing it. Does that ring true?","prompt":"How does it land?","options":["Rings true","No punishment","Yes"],"affirm":"In real love a no is heard, not punished; sulking or withdrawal to force a yes isn't love.","relearn":"In real love a no is heard, not punished into a yes.","persona":"any","source":"love hears no"},
  {"id":"rh-947","cat":"consent-inside","type":"reflect","hook":"Lensy: if a past moment felt forced, naming it isn't betrayal, and it wasn't your fault. Breathe into that.","prompt":"What do you feel?","options":["Not my fault","Not betrayal","Okay"],"affirm":"Naming a moment that felt forced isn't disloyalty; it's clarity, and the fault was never yours.","relearn":"Naming a moment that felt forced isn't disloyalty; the fault was never yours.","persona":"any","source":"not your fault"},
  {"id":"rh-950","cat":"consent-inside","type":"role-play","hook":"Your partner reaches for you when you're not in the mood, and you want to be clear.","setup":"Be warm and direct. Say:","yourLine":[{"text":"\"I love you, but I'm not up for it tonight, and that's okay.\"","best":true},{"text":"Freeze and let it happen to avoid a scene"}],"relearn":"You can warmly and clearly say no to your partner; 'not tonight' is enough.","persona":"any","source":"clear no"},
  {"id":"rh-951","cat":"consent-inside","type":"role-play","hook":"You want to gently stop midway because it stopped feeling right.","setup":"Speak up kindly. Say:","yourLine":[{"text":"\"Can we pause? I'm not comfortable, let's stop for now.\"","best":true},{"text":"Stay quiet and wait for it to end"}],"relearn":"You can pause or stop at any point; a caring partner respects 'can we stop'.","persona":"any","source":"pause midway"},
  {"id":"rh-952","cat":"consent-inside","type":"role-play","hook":"Your spouse insists marriage means you can't refuse; you want to answer calmly.","setup":"Hold your ground gently. Say:","yourLine":[{"text":"\"Being married doesn't cancel my yes or my no. I still get to choose.\"","best":true},{"text":"Stay silent and assume they're right"}],"relearn":"Marriage doesn't cancel your yes or no; you still get to choose, every time.","persona":"Reshma","source":"still get to choose"},
  {"id":"rh-953","cat":"consent-inside","type":"role-play","hook":"You want to invite an open conversation about checking in with each other.","setup":"Open it gently. Say:","yourLine":[{"text":"\"Let's always check in, a real yes from both of us, no pressure either way.\"","best":true},{"text":"Assume it's understood and never mention it"}],"relearn":"You can invite ongoing consent: a real yes from both, no pressure either way.","persona":"any","source":"open the talk"},
  {"id":"rh-954","cat":"consent-inside","type":"role-play","hook":"As a husband, you're not in the mood and want to say so without shame.","setup":"Say it plainly. Say:","yourLine":[{"text":"\"I'm just not feeling it tonight, no big deal, let's just rest.\"","best":true},{"text":"Push through it to seem 'manly'"}],"relearn":"A husband can decline too; 'not feeling it tonight' is a fine, valid answer.","persona":"any","source":"his plain no"},
  {"id":"rh-955","cat":"consent-inside","type":"role-play","hook":"Your partner keeps sulking after a no; you want to name it without a fight.","setup":"Be calm and honest. Say:","yourLine":[{"text":"\"When you sulk after I say no, it feels like pressure. A no should be okay.\"","best":true},{"text":"Apologise and give in to stop the sulking"}],"relearn":"You can name sulking-after-a-no as pressure; a no should simply be okay.","persona":"any","source":"name the sulk"},
  {"id":"rh-956","cat":"consent-inside","type":"role-play","hook":"You want to reassure your spouse that a no isn't rejection of them.","setup":"Reassure warmly. Say:","yourLine":[{"text":"\"Me saying no isn't me loving you less, it's just a no for tonight.\"","best":true},{"text":"Say nothing and let them assume you're upset"}],"relearn":"A no for tonight isn't loving someone less; you can say both with warmth.","persona":"any","source":"no isn't rejection"},
  {"id":"rh-957","cat":"consent-inside","type":"role-play","hook":"Your partner says 'everyone's married, no one asks'; you want to hold your standard.","setup":"Answer kindly but firmly. Say:","yourLine":[{"text":"\"In our home, a real yes matters to me, married or not.\"","best":true},{"text":"Drop it because that's just how things are"}],"relearn":"You can hold your standard: a real, willing yes matters in your home, married or not.","persona":"any","source":"hold the standard"},
  {"id":"rh-960","cat":"consent-inside","type":"sort","hook":"Sort each line: a real, free yes, or coercion dressed up as marriage?","items":[{"id":"a","text":"\"Tell me if you'd like to or not.\""},{"id":"b","text":"\"You're my wife, you can't refuse me.\""},{"id":"c","text":"\"We can stop any time you want.\""},{"id":"d","text":"\"If you loved me you'd never say no.\""},{"id":"e","text":"\"No pressure, only if you're up for it.\""},{"id":"f","text":"\"I'll sulk all week if you refuse.\""}],"bins":[{"id":"freeyes","label":"A free yes","valence":"pos"},{"id":"coercion","label":"Coercion","valence":"neg"}],"key":{"a":"freeyes","b":"coercion","c":"freeyes","d":"coercion","e":"freeyes","f":"coercion"},"relearn":"Checking in and 'we can stop' invite a free yes; 'you can't refuse me' and guilt or sulking are coercion.","persona":"any","source":"free yes vs coercion"},
  {"id":"rh-961","cat":"consent-inside","type":"sort","hook":"Sort each: keeps consent ongoing, or treats marriage as a standing yes?","items":[{"id":"a","text":"Asking each time, never assuming"},{"id":"b","text":"Treating the wedding as a permanent yes"},{"id":"c","text":"Accepting a no without punishment"},{"id":"d","text":"Demanding intimacy as a marital right"},{"id":"e","text":"Respecting a 'stop' partway through"},{"id":"f","text":"Saying a past yes settles all future nights"}],"bins":[{"id":"ongoing","label":"Ongoing consent","valence":"pos"},{"id":"standing","label":"Standing-yes myth","valence":"neg"}],"key":{"a":"ongoing","b":"standing","c":"ongoing","d":"standing","e":"ongoing","f":"standing"},"relearn":"Asking each time, accepting a no, and respecting 'stop' keep consent ongoing; treating marriage as a permanent yes is the myth.","persona":"any","source":"ongoing vs standing"},
  {"id":"rh-962","cat":"consent-inside","type":"sort","hook":"Sort each reason for a no: a complete reason on its own, or something you must justify?","items":[{"id":"a","text":"\"I'm tired tonight.\""},{"id":"b","text":"\"I just don't want to.\""},{"id":"c","text":"\"I'm still recovering.\""},{"id":"d","text":"\"I need to earn the right to refuse.\""},{"id":"e","text":"\"No reason, just no.\""},{"id":"f","text":"\"I must prove it's a good enough excuse.\""}],"bins":[{"id":"complete","label":"Complete on its own","valence":"pos"},{"id":"mustjustify","label":"False 'must justify'","valence":"neg"}],"key":{"a":"complete","b":"complete","c":"complete","d":"mustjustify","e":"complete","f":"mustjustify"},"relearn":"'Tired', 'recovering', or just 'no' are complete reasons; you never have to earn the right or prove a good enough excuse.","persona":"any","source":"no needs no justification"},
  {"id":"rh-963","cat":"consent-inside","type":"sort","hook":"Sort each: a sign of real, willing consent, or a sign it isn't truly free?","items":[{"id":"a","text":"Both feel relaxed and want to"},{"id":"b","text":"One agrees only to stop the nagging"},{"id":"c","text":"Either can pause with no fallout"},{"id":"d","text":"A yes given out of fear of a fight"},{"id":"e","text":"Both checked in beforehand"},{"id":"f","text":"A yes to avoid being threatened"}],"bins":[{"id":"willing","label":"Truly willing","valence":"pos"},{"id":"notfree","label":"Not truly free","valence":"neg"}],"key":{"a":"willing","b":"notfree","c":"willing","d":"notfree","e":"willing","f":"notfree"},"relearn":"Both relaxed, free to pause, and checking in signal a willing yes; agreeing out of nagging, fear or threat isn't free.","persona":"any","source":"willing vs unfree"},
  {"id":"rh-964","cat":"consent-inside","type":"sort","hook":"Sort each belief: true about consent in marriage, or a myth to strike?","items":[{"id":"a","text":"Your body stays your own after marriage"},{"id":"b","text":"The wedding was a yes to everything"},{"id":"c","text":"Consent can be withdrawn any time"},{"id":"d","text":"Providing for the home buys intimacy"},{"id":"e","text":"A husband can say no too"},{"id":"f","text":"'Private' means consent doesn't apply"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Your body stays yours, consent is withdrawable, and a husband can say no, all true; the blanket-yes, bought-intimacy and 'private' lines are myths.","persona":"any","source":"true vs myth"},
  {"id":"rh-965","cat":"consent-inside","type":"sort","hook":"Sort each response to a partner's no: respects it, or pressures past it?","items":[{"id":"a","text":"\"Okay, no problem, goodnight.\""},{"id":"b","text":"Keeping on asking until they cave"},{"id":"c","text":"\"Thanks for telling me, let's rest.\""},{"id":"d","text":"Going cold and silent to punish them"},{"id":"e","text":"Holding them warmly and letting it be"},{"id":"f","text":"\"After all I do, this is what I get?\""}],"bins":[{"id":"respects","label":"Respects the no","valence":"pos"},{"id":"pressures","label":"Pressures past it","valence":"neg"}],"key":{"a":"respects","b":"pressures","c":"respects","d":"pressures","e":"respects","f":"pressures"},"relearn":"Saying 'no problem', thanking them, and letting it be respect a no; nagging, cold-shouldering, and guilt-tripping pressure past it.","persona":"any","source":"respect vs pressure"},
  {"id":"rh-966","cat":"consent-inside","type":"sort","hook":"Sort each: honours your partner's pace, or overrides it for your own wants?","items":[{"id":"a","text":"Letting them set the timing for a baby"},{"id":"b","text":"Pushing a child on your timeline"},{"id":"c","text":"Asking what feels right to them"},{"id":"d","text":"Deciding their readiness for them"},{"id":"e","text":"Slowing down when they're unsure"},{"id":"f","text":"Treating their body as your call"}],"bins":[{"id":"honours","label":"Honours their pace","valence":"pos"},{"id":"overrides","label":"Overrides it","valence":"neg"}],"key":{"a":"honours","b":"overrides","c":"honours","d":"overrides","e":"honours","f":"overrides"},"relearn":"Letting them set timing, asking, and slowing down honour a partner's pace; pushing, deciding for them, or claiming their body override it.","persona":"any","source":"pace vs override"},
  {"id":"rh-967","cat":"consent-inside","type":"sort","hook":"Sort each line spoken inside a marriage: respects consent, or assumes it away?","items":[{"id":"a","text":"\"Only if you want to, love.\""},{"id":"b","text":"\"It's your duty, you can't say no.\""},{"id":"c","text":"\"Tell me what you're comfortable with.\""},{"id":"d","text":"\"We're married, so it's always a yes.\""},{"id":"e","text":"\"We can wait till you feel ready.\""},{"id":"f","text":"\"You owe me this; I'm your husband.\""}],"bins":[{"id":"respects","label":"Respects consent","valence":"pos"},{"id":"assumes","label":"Assumes it away","valence":"neg"}],"key":{"a":"respects","b":"assumes","c":"respects","d":"assumes","e":"respects","f":"assumes"},"relearn":"'Only if you want' and 'we can wait' respect consent; 'your duty', 'always a yes', and 'you owe me' assume it away.","persona":"any","source":"respects vs assumes"},
  {"id":"rh-970","cat":"consent-inside","type":"match","hook":"Match each myth about consent in marriage to the truth that strikes it.","pairs":[{"left":"\"The wedding was a yes forever.\"","right":"Each yes is fresh; say no any day."},{"left":"\"A wife can't refuse her husband.\"","right":"Refusal is allowed; intimacy isn't owed."},{"left":"\"A past yes settles all nights.\"","right":"A past yes is never permanent."},{"left":"\"'Private' means consent doesn't apply.\"","right":"'Private' is no shield."},{"left":"\"Once started, you can't stop.\"","right":"You can withdraw at any point."}],"relearn":"Each myth has a truth: a fresh yes, no permanent yes, no 'private' shield, the right to withdraw.","persona":"any","source":"myth to truth"},
  {"id":"rh-971","cat":"consent-inside","type":"match","hook":"Match each pressure line to what it really is underneath.","pairs":[{"left":"\"If you loved me you'd say yes.\"","right":"Guilt-tripping a yes out of someone"},{"left":"\"I'll leave you if you refuse.\"","right":"A threat, which makes any yes unfree"},{"left":"\"I'll sulk all week.\"","right":"Punishing a no into a yes"},{"left":"\"You're asleep but we're married.\"","right":"There's no consent without an awake, willing yes"},{"left":"\"After all I provide, you owe me.\"","right":"Treating a body as bought, which it never is"}],"relearn":"Guilt, threats, sulking and 'you owe me' are all coercion, never free consent.","persona":"any","source":"pressure decoded"},
  {"id":"rh-972","cat":"consent-inside","type":"match","hook":"Match each consent idea to its plain meaning inside a marriage.","pairs":[{"left":"Ongoing consent","right":"A fresh, willing yes each time, not assumed"},{"left":"Withdrawable consent","right":"You can pause or stop at any moment"},{"left":"Bodily autonomy","right":"Your body stays your own after marriage"},{"left":"Even-handed consent","right":"A partner of any gender can say no"},{"left":"Enthusiastic yes","right":"Willing and relaxed, not just spoken words"}],"relearn":"Consent in marriage is ongoing, withdrawable, even-handed, rooted in bodily autonomy, and shown by a willing yes, not mere words.","persona":"any","source":"consent ideas"},
  {"id":"rh-973","cat":"consent-inside","type":"match","hook":"Match each kind, consent-honouring line to the moment it fits.","pairs":[{"left":"When unsure if they want to","right":"\"Only if you'd like to, no pressure.\""},{"left":"When something feels off midway","right":"\"Can we pause? Let's stop for now.\""},{"left":"When you're not in the mood","right":"\"Not tonight, and that's okay.\""},{"left":"When opening the topic","right":"\"Let's check in with each other.\""},{"left":"After a partner says no","right":"\"Thanks for telling me, let's rest.\""}],"relearn":"There's a warm, consent-honouring line for every moment: inviting, pausing, declining, opening up, and accepting a no.","persona":"any","source":"warm lines"},
  {"id":"rh-974","cat":"consent-inside","type":"match","hook":"Match each true statement about marital consent to why it holds.","pairs":[{"left":"You can say no any time in marriage","right":"Marriage never removed that right"},{"left":"Coercion is wrong whatever the law","right":"That law is contested and evolving"},{"left":"Your body is never 'owed'","right":"Support doesn't buy consent"},{"left":"A no needs no reason","right":"'Not tonight' is a full answer"},{"left":"Asking is care, not awkwardness","right":"A check-in honours both"}],"relearn":"Each truth has a why: the right is never lost, coercion is always wrong, a no needs no reason, asking is care.","persona":"any","source":"truth to why"},
  {"id":"rh-975","cat":"consent-inside","type":"match","hook":"Match each person's safe next step to their situation around consent at home.","pairs":[{"left":"Feels forced and unsafe now","right":"Reach a trusted person, 181, 1091 or 112"},{"left":"Wants to set a boundary","right":"\"I still get to say yes or no.\""},{"left":"Unsure if a past night was okay","right":"Naming it isn't betrayal or your fault"},{"left":"Wants to open the talk","right":"\"Let's check in, a real yes from both.\""},{"left":"Curious about rights","right":"The DV Act 2005 is educational, not advice"}],"relearn":"Every situation has a safe step: reach help if unsafe, set a boundary, name harm without blame, or open up.","persona":"any","source":"step to situation"},
  {"id":"rh-976","cat":"consent-inside","type":"match","hook":"Match each partner gesture to whether it builds a free yes or chips at it.","pairs":[{"left":"Checking in before and during","right":"Builds a real, shared yes"},{"left":"Sulking until they give in","right":"Chips at consent with pressure"},{"left":"Saying 'we can stop any time'","right":"Makes a no safe to say"},{"left":"Calling refusal a betrayal","right":"Turns a fair no into guilt"},{"left":"Letting them set the pace","right":"Honours their bodily autonomy"}],"relearn":"Checking in, offering an easy stop, and following their pace build a free yes; sulking and calling a no a betrayal chip at it.","persona":"any","source":"builds vs chips"},
  {"id":"rh-980","cat":"consent-inside","type":"spot","hook":"Spot the 2 lines that assume a yes the partner never freely gave.","scene":[{"id":"a","text":"\"Only if you're up for it tonight.\"","trick":false},{"id":"b","text":"\"You're my wife, you can't refuse me.\"","trick":true},{"id":"c","text":"\"We can stop whenever you like.\"","trick":false},{"id":"d","text":"\"We're married, so it's automatically a yes.\"","trick":true},{"id":"e","text":"\"Tell me what feels right for you.\"","trick":false}],"why":"\"You can't refuse me\" and \"automatically a yes\" both assume consent marriage never grants; the others leave a real yes or no open.","relearn":"Marriage never grants a standing yes; a real yes or no stays open every time.","persona":"any","source":"assumes a yes"},
  {"id":"rh-981","cat":"consent-inside","type":"spot","hook":"Spot the 2 red-flag lines that pressure a partner past their no.","scene":[{"id":"a","text":"\"No problem, let's just rest tonight.\"","trick":false},{"id":"b","text":"\"If you loved me you'd never say no.\"","trick":true},{"id":"c","text":"\"Thanks for telling me how you feel.\"","trick":false},{"id":"d","text":"\"I'll sulk all week until you give in.\"","trick":true},{"id":"e","text":"\"We'll wait till you feel ready.\"","trick":false}],"why":"\"If you loved me\" guilt-trips and \"I'll sulk till you give in\" punishes a no into a yes; the other three accept the no warmly.","relearn":"Guilt-tripping and sulking pressure a no into a yes; a real yes is freely given.","persona":"any","source":"pressure past no"},
  {"id":"rh-982","cat":"consent-inside","type":"spot","hook":"Spot the 2 myths hiding among true statements about consent in marriage.","scene":[{"id":"a","text":"Your body stays your own after marriage.","trick":false},{"id":"b","text":"The wedding was a yes to everything, forever.","trick":true},{"id":"c","text":"Consent can be withdrawn at any time.","trick":false},{"id":"d","text":"Providing for the home means intimacy is owed.","trick":true},{"id":"e","text":"A husband can say no too; consent is even-handed.","trick":false}],"why":"\"The wedding was a yes forever\" and \"providing means intimacy is owed\" are the myths; the other three are true.","relearn":"The standing-yes and 'owed' lines are myths; your body stays yours and consent is withdrawable.","persona":"any","source":"spot the myths"},
  {"id":"rh-983","cat":"consent-inside","type":"spot","hook":"Spot the 2 lines that treat a no as something to override.","scene":[{"id":"a","text":"\"A no is always okay between us.\"","trick":false},{"id":"b","text":"\"You don't get to refuse; it's your duty.\"","trick":true},{"id":"c","text":"\"Let's pause; only when you want to.\"","trick":false},{"id":"d","text":"\"After all I do, you owe me this.\"","trick":true},{"id":"e","text":"\"Your comfort matters more than the moment.\"","trick":false}],"why":"\"It's your duty, you can't refuse\" and \"you owe me\" both override a no; the others keep the no respected.","relearn":"'Duty' and 'you owe me' override a no; a no should always be respected.","persona":"any","source":"override a no"},
  {"id":"rh-984","cat":"consent-inside","type":"spot","hook":"Spot the 2 things that mean a yes wasn't truly free.","scene":[{"id":"a","text":"Both partners feel relaxed and willing.","trick":false},{"id":"b","text":"A yes given only to end the nagging.","trick":true},{"id":"c","text":"Either one can pause with no fallout.","trick":false},{"id":"d","text":"A yes given out of fear of a fight.","trick":true},{"id":"e","text":"Both checked in with each other first.","trick":false}],"why":"A yes 'to end the nagging' and a yes 'out of fear of a fight' aren't free consent; the other three show a willing yes.","relearn":"A yes given to end nagging or out of fear isn't free consent; a real yes is willing.","persona":"any","source":"not truly free"},
  {"id":"rh-985","cat":"consent-inside","type":"spot","hook":"Spot the 2 false beliefs about a partner's right to say no.","scene":[{"id":"a","text":"A no needs no reason or excuse.","trick":false},{"id":"b","text":"You must earn the right to refuse.","trick":true},{"id":"c","text":"A past yes doesn't bind tonight.","trick":false},{"id":"d","text":"Once you start, you can't change your mind.","trick":true},{"id":"e","text":"Consent is even-handed for any gender.","trick":false}],"why":"\"You must earn the right to refuse\" and \"once you start you can't change your mind\" are false; the other three are true.","relearn":"A no needs no reason and consent can change anytime; you never earn the right to refuse.","persona":"any","source":"false beliefs"},
  {"id":"rh-986","cat":"consent-inside","type":"spot","hook":"Spot the 2 lines that wrongly use 'private' or 'the law' to excuse coercion.","scene":[{"id":"a","text":"\"Coercion is wrong whatever the law says.\"","trick":false},{"id":"b","text":"\"It's our private marriage, so nothing applies.\"","trick":true},{"id":"c","text":"\"A real yes still matters between us.\"","trick":false},{"id":"d","text":"\"The law allows it, so it's fine to force.\"","trick":true},{"id":"e","text":"\"Help exists if home ever feels unsafe.\"","trick":false}],"why":"\"It's private, nothing applies\" and \"the law allows it, so force is fine\" both excuse coercion; the others state the truth.","relearn":"'Private' is no shield and coercion is always wrong; help exists if home feels unsafe.","persona":"any","source":"private and law excuses"},
  {"id":"rh-977","cat":"consent-inside","type":"match","hook":"Match each moment in a marriage to the consent question that fits it.","pairs":[{"left":"Reaching for a tired partner","right":"\"Only if you're up for it?\""},{"left":"Trying something new together","right":"\"Want to, or skip it?\""},{"left":"Sensing they've gone quiet","right":"\"Should we pause?\""},{"left":"Reconnecting after a fight","right":"\"Talk first, no rush?\""},{"left":"Unsure what they'd enjoy","right":"\"Tell me what feels right.\""}],"relearn":"Every moment in marriage has a kind consent question; asking keeps the yes real and shared.","persona":"any","source":"moment to question"},
  {"id":"rh-987","cat":"consent-inside","type":"spot","hook":"Spot the 2 lines that treat a body as something owed, not freely shared.","scene":[{"id":"a","text":"\"Your body is yours; only if you want.\"","trick":false},{"id":"b","text":"\"I married you, so this is mine now.\"","trick":true},{"id":"c","text":"\"We share this when we both want to.\"","trick":false},{"id":"d","text":"\"You owe me, that's what wives are for.\"","trick":true},{"id":"e","text":"\"No pressure, your yes is always yours.\"","trick":false}],"why":"\"This is mine now\" and \"you owe me, that's what wives are for\" treat a body as owned; the others keep it freely shared.","relearn":"A body is never owned or owed by marriage; intimacy is freely shared, only with a real yes.","persona":"any","source":"owned vs shared"},
  {"id":"rh-990","cat":"never-your-fault","type":"strike-rewrite","hook":"\"I made him angry, so the slap was partly my fault.\"","myth":{"un":"I made him angry, so it was partly my fault.","re":"Anger is never a licence to harm; the choice to hit is the abuser's alone.","why":"Plenty of angry people never raise a hand."},"relearn":"Anger is no licence to harm; the choice to hit is the abuser's alone, never yours.","persona":"any","source":"anger isn't a licence"},
  {"id":"rh-991","cat":"never-your-fault","type":"strike-rewrite","hook":"\"If the food was late or the house messy, I brought it on myself.\"","myth":{"un":"If the food was late or the house messy, I brought it on myself.","re":"A late meal or a messy room is never a reason for abuse; the abuser chose to react this way.","why":"Daily life is not a provocation."},"relearn":"A late meal or untidy home is never a reason for abuse; the abuser chose how to react.","persona":"Reshma","source":"chores aren't provocation"},
  {"id":"rh-992","cat":"never-your-fault","type":"strike-rewrite","hook":"\"He only drinks and lashes out, so really it's the alcohol's fault, not his.\"","myth":{"un":"It's the alcohol's fault he lashes out, not his.","re":"Alcohol may lower a brake, but the person stays responsible for the harm they do.","why":"Many people drink and never abuse anyone."},"relearn":"Alcohol is no excuse; a person stays fully responsible for any harm they do.","persona":"any","source":"alcohol is no excuse"},
  {"id":"rh-993","cat":"never-your-fault","type":"strike-rewrite","hook":"\"His childhood was hard, so I shouldn't blame him for hurting me.\"","myth":{"un":"His hard past means I can't blame him for hurting me.","re":"A painful past can be understood, but it never makes abuse your fault or excuses it.","why":"Many with hard pasts choose not to harm."},"relearn":"A hard past explains nothing away; abuse is still the abuser's choice, never your fault.","persona":"any","source":"a past is no excuse"},
  {"id":"rh-994","cat":"never-your-fault","type":"strike-rewrite","hook":"\"I stayed all these years, so I can't really complain now.\"","myth":{"un":"I stayed all these years, so I can't complain now.","re":"How long you stayed never makes harm acceptable; you can name it and seek help at any time.","why":"There is no deadline on getting safe."},"relearn":"Staying for years never makes abuse acceptable; you can name it and seek help any time.","persona":"any","source":"no deadline"},
  {"id":"rh-995","cat":"never-your-fault","type":"strike-rewrite","hook":"\"I went back after leaving once, so it must be my fault it continued.\"","myth":{"un":"I went back once, so it's my fault it continued.","re":"Returning is common and never your fault; the abuse continuing is the abuser's choice.","why":"Leaving is rarely one clean step."},"relearn":"Going back is common and never your fault; the abuse continuing is the abuser's doing.","persona":"any","source":"returning isn't fault"},
  {"id":"rh-996","cat":"never-your-fault","type":"strike-rewrite","hook":"\"As his wife I should have kept him satisfied, so this is on me.\"","myth":{"un":"I should have kept him satisfied, so this is on me.","re":"No one earns or owes safety by pleasing a partner; abuse is never a fair consequence.","why":"A partner is owed respect, not appeasement."},"relearn":"You never earn safety by pleasing a partner; abuse is never a fair consequence of any 'failure'.","persona":"Reshma","source":"no duty to appease"},
  {"id":"rh-997","cat":"never-your-fault","type":"strike-rewrite","hook":"\"A real man would have just fought back, so it's his own fault he was hurt.\"","myth":{"un":"A real man would fight back, so it's his own fault.","re":"Not fighting back is wise, not weak; a hurt man is a survivor, never to blame.","why":"Freezing or de-escalating is a normal response."},"relearn":"Not fighting back is wise, not weak; a male survivor is never to blame for being hurt.","persona":"any","source":"male survivors not at fault"},
  {"id":"rh-998","cat":"never-your-fault","type":"strike-rewrite","hook":"\"She earns more than him, so she can't really be the one being abused.\"","myth":{"un":"She earns more, so she can't be the one being abused.","re":"Income, status or strength don't decide who can be abused; the pattern of harm does.","why":"Abuse is about control, not who earns more."},"relearn":"Money, status or strength don't decide who can be a victim; the pattern of harm does.","persona":"any","source":"status isn't immunity"},
  {"id":"rh-999","cat":"never-your-fault","type":"strike-rewrite","hook":"\"The in-laws say I provoke the fights, so the blame must be mine.\"","myth":{"un":"The in-laws say I provoke the fights, so the blame is mine.","re":"Family taking the abuser's side doesn't make harm your fault; the responsibility stays theirs.","why":"A crowd agreeing doesn't change who chose to harm."},"relearn":"Family siding with the abuser doesn't make it your fault; responsibility stays with the one harming you.","persona":"Reshma","source":"crowd doesn't decide fault"},
  {"id":"rh-1000","cat":"never-your-fault","type":"strike-rewrite","hook":"\"I should have seen the red flags while dating, so I have only myself to blame.\"","myth":{"un":"I missed the red flags, so I only have myself to blame.","re":"Abusers often hide it early and turn slowly; not foreseeing it is never your fault.","why":"Charm first, control later is a known pattern."},"relearn":"Not spotting hidden red flags early is never your fault; abusers deliberately hide and turn slowly.","persona":"any","source":"hidden early"},
  {"id":"rh-1001","cat":"never-your-fault","type":"strike-rewrite","hook":"\"My kids saw it, so I've failed them and it's my fault.\"","myth":{"un":"My kids saw it, so I've failed them and it's my fault.","re":"A child witnessing abuse is the abuser's harm, not yours; reaching for help is protecting them.","why":"You did not choose the harm they saw."},"relearn":"A child witnessing abuse is the abuser's harm, not your failure; getting help protects everyone.","persona":"Reshma","source":"not your failure"},
  {"id":"rh-1002","cat":"never-your-fault","type":"strike-rewrite","hook":"\"I argued back that night, so the violence was a two-way fight, not abuse.\"","myth":{"un":"I argued back, so it was a two-way fight, not abuse.","re":"Answering back isn't violence; one person choosing to harm and control is still abuse.","why":"Self-defence or a raised voice isn't the same as abuse."},"relearn":"Arguing back isn't abuse; one person choosing to harm and control still is, and it's not your fault.","persona":"any","source":"not a fair fight"},
  {"id":"rh-1003","cat":"never-your-fault","type":"strike-rewrite","hook":"\"People will say I shamed the family, so it's my fault for speaking up.\"","myth":{"un":"Speaking up shamed the family, so it's my fault.","re":"Shame belongs to the one who abused, not to the person who named it or asked for help.","why":"Naming harm is honesty, not betrayal."},"relearn":"Speaking up never shames you; the shame belongs to the abuser, not the person naming the harm.","persona":"any","source":"shame is the abuser's"},
  {"id":"rh-1004","cat":"never-your-fault","type":"strike-rewrite","hook":"\"I'm too educated and aware for this to be happening, so I must have caused it.\"","myth":{"un":"I'm too aware for this, so I must have caused it.","re":"Abuse happens across every class and education level; being aware never invites it.","why":"Knowing about abuse doesn't make you immune to it."},"relearn":"Abuse happens at every education and income level; being aware never causes it or invites it.","persona":"any","source":"no one is immune"},
  {"id":"rh-1005","cat":"never-your-fault","type":"role-play","hook":"Your sister whispers that her husband hits her, then says she must have deserved it.","setup":"Steady her gently. Say:","yourLine":[{"text":"\"No one deserves to be hit. The only person responsible is him, and I'm here with you.\"","best":true},{"text":"\"Well, what did you do to make him that angry?\""}],"relearn":"No one deserves to be hit; the abuser is the only one responsible, whatever a survivor 'did'.","persona":"any","source":"no one deserves it"},
  {"id":"rh-1006","cat":"never-your-fault","type":"role-play","hook":"A coworker confides her partner controls her, but says she's 'too sensitive' about it.","setup":"Validate, don't minimise. Say:","yourLine":[{"text":"\"You're not too sensitive. What you're describing is control, and it's not your fault.\"","best":true},{"text":"\"Maybe you are reading too much into it.\""}],"relearn":"A survivor isn't 'too sensitive'; control is real, and naming it is not an overreaction.","persona":"Saxena","source":"not too sensitive"},
  {"id":"rh-1007","cat":"never-your-fault","type":"role-play","hook":"A young husband tells you his wife screams and throws things, but says men can't be victims.","setup":"Believe him. Say:","yourLine":[{"text":"\"Anyone can be hurt this way, and it's not your fault. I believe you, and help exists.\"","best":true},{"text":"\"Just toughen up, that's not really abuse.\""}],"relearn":"Anyone of any gender can be a victim; a male survivor is believed and it is never his fault.","persona":"any","source":"believe male survivors"},
  {"id":"rh-1008","cat":"never-your-fault","type":"role-play","hook":"Your friend keeps apologising to you for 'bothering you' with her abuse.","setup":"Remove the guilt. Say:","yourLine":[{"text":"\"You're never a bother. Telling me was brave, and none of this is your fault.\"","best":true},{"text":"\"It's fine, just try not to upset him next time.\""}],"relearn":"A survivor reaching out is never 'a bother'; telling someone is brave, not a fault.","persona":"any","source":"never a bother"},
  {"id":"rh-1009","cat":"never-your-fault","type":"role-play","hook":"A neighbour says she stayed for the children and now blames herself for those years.","setup":"Honour her choice. Say:","yourLine":[{"text":"\"Staying for your children was love, not a fault. What happened was his doing, not yours.\"","best":true},{"text":"\"You should have left long ago, honestly.\""}],"relearn":"Staying for children is never a fault to blame; the harm done was always the abuser's choice.","persona":"Reshma","source":"staying isn't a fault"},
  {"id":"rh-1010","cat":"never-your-fault","type":"role-play","hook":"A survivor says she feels stupid for not realising sooner what was happening.","setup":"Lift the self-blame. Say:","yourLine":[{"text":"\"You're not stupid. Abusers hide it on purpose, and seeing it now is strength, not failure.\"","best":true},{"text":"\"Yeah, the signs were pretty obvious though.\""}],"relearn":"Not realising sooner isn't stupidity; abusers hide it, and recognising it is strength.","persona":"any","source":"not stupid"},
  {"id":"rh-1011","cat":"never-your-fault","type":"role-play","hook":"Your brother admits his wife humiliates and threatens him, then laughs it off as nothing.","setup":"Take it seriously, gently. Say:","yourLine":[{"text":"\"That isn't nothing, and it isn't your fault. You deserve respect and support too.\"","best":true},{"text":"\"Ha, just don't let her boss you around, man.\""}],"relearn":"A man's abuse 'isn't nothing'; he deserves to be taken seriously and it's never his fault.","persona":"any","source":"take him seriously"},
  {"id":"rh-1012","cat":"never-your-fault","type":"role-play","hook":"A survivor says everyone keeps asking why she didn't just leave, and it makes her feel blamed.","setup":"Drop the 'why didn't you' question. Say:","yourLine":[{"text":"\"I'd never ask why you stayed. The right question is what he did, and that's on him.\"","best":true},{"text":"\"So why didn't you just walk out the first time?\""}],"relearn":"Asking 'why didn't you leave?' blames the survivor; the question is what the abuser did.","persona":"Saxena","source":"wrong question"},
  {"id":"rh-1013","cat":"never-your-fault","type":"role-play","hook":"A friend blames herself because she once hit back during an attack.","setup":"Reassure her. Say:","yourLine":[{"text":"\"Protecting yourself doesn't make you the abuser. The pattern of harm was his, not yours.\"","best":true},{"text":"\"Well, then you're as bad as each other.\""}],"relearn":"Defending yourself once doesn't make you the abuser; the pattern of harm defines who's responsible.","persona":"any","source":"self-defence isn't abuse"},
  {"id":"rh-1014","cat":"never-your-fault","type":"role-play","hook":"A survivor fears that because there are no bruises, no one will believe her.","setup":"Believe her fully. Say:","yourLine":[{"text":"\"I believe you. Harm without marks is still real abuse, and none of it is your fault.\"","best":true},{"text":"\"But did he actually leave a mark on you?\""}],"relearn":"Abuse without visible marks is still real; a survivor is believed and it is never her fault.","persona":"any","source":"no marks, still real"},
  {"id":"rh-1015","cat":"never-your-fault","type":"role-play","hook":"Your aunt says the abuse must be karma or fate that she has to accept.","setup":"Gently challenge that. Say:","yourLine":[{"text":"\"This isn't fate you must accept. It's his choice to harm, and you deserve safety and help.\"","best":true},{"text":"\"Maybe it really is just your fate, then.\""}],"relearn":"Abuse isn't fate or karma to accept; it's the abuser's choice, and safety and help exist.","persona":"any","source":"not fate"},
  {"id":"rh-1016","cat":"never-your-fault","type":"role-play","hook":"A survivor says she must be unlovable since this keeps happening to her.","setup":"Reflect her worth. Say:","yourLine":[{"text":"\"You're not unlovable. Some people choose to harm, and that says everything about them, not you.\"","best":true},{"text":"\"Maybe there's something you keep doing wrong.\""}],"relearn":"Being harmed says nothing about your worth; it reflects the abuser's choices, not yours.","persona":"any","source":"your worth is intact"},
  {"id":"rh-1017","cat":"never-your-fault","type":"role-play","hook":"A survivor is terrified to tell you in case you judge how long it took her to speak.","setup":"Make it safe. Say:","yourLine":[{"text":"\"There's no late here. You told me when you could, and I'm only glad you did.\"","best":true},{"text":"\"You really should have said something years ago.\""}],"relearn":"There's no 'too late' to disclose; a survivor speaks when they can, and that's never a fault.","persona":"any","source":"no too-late"},
  {"id":"rh-1018","cat":"never-your-fault","type":"role-play","hook":"A survivor wonders aloud if she imagined or exaggerated the whole thing.","setup":"Steady her trust in herself. Say:","yourLine":[{"text":"\"You're not imagining it. What you felt was real, and doubting yourself is part of what he did.\"","best":true},{"text":"\"Are you sure you're not blowing it out of proportion?\""}],"relearn":"A survivor isn't imagining or exaggerating; self-doubt is often part of the abuse, not a fault.","persona":"Saxena","source":"not imagined"},
  {"id":"rh-1019","cat":"never-your-fault","type":"role-play","hook":"A survivor says she feels she has to forgive him at once or she's a bad person.","setup":"Ease the pressure. Say:","yourLine":[{"text":"\"You don't owe instant forgiveness to feel safe. Your healing comes first, at your pace.\"","best":true},{"text":"\"You should just forgive and forget, really.\""}],"relearn":"A survivor owes no instant forgiveness; healing comes first, at their own pace, with no blame.","persona":"any","source":"no forced forgiveness"},
  {"id":"rh-1020","cat":"never-your-fault","type":"role-play","hook":"A survivor says she let it happen because she didn't scream or run.","setup":"Name the freeze response. Say:","yourLine":[{"text":"\"Freezing is a real, common reaction, not consent. You didn't 'let' anything; he chose to harm.\"","best":true},{"text":"\"Why didn't you just scream or run, then?\""}],"relearn":"Freezing is a normal survival response, not permission; the abuser still chose to harm.","persona":"any","source":"freeze isn't consent"},
  {"id":"rh-1021","cat":"never-your-fault","type":"role-play","hook":"A survivor says the counsellor he saw laughed off male abuse, so now he blames himself.","setup":"Counter that harm. Say:","yourLine":[{"text":"\"That response was wrong, not you. Your abuse is real, it's not your fault, and better help exists.\"","best":true},{"text":"\"Well, maybe they had a point about men.\""}],"relearn":"A dismissive response is the wrong one, not the survivor; male abuse is real and never his fault.","persona":"Saxena","source":"the dismissal was wrong"},
  {"id":"rh-1022","cat":"never-your-fault","type":"role-play","hook":"A survivor says she keeps replaying what she 'should' have done differently that night.","setup":"Redirect the blame. Say:","yourLine":[{"text":"\"There's nothing you should have done. The only 'should' here is that he shouldn't have hurt you.\"","best":true},{"text":"\"Yeah, you probably should have handled it better.\""}],"relearn":"There's no 'should have' that makes it your fault; the only failing was the abuser's choice to harm.","persona":"any","source":"no should-have"},
  {"id":"rh-1023","cat":"never-your-fault","type":"role-play","hook":"A survivor says her own mother told her a good wife endures and stays quiet.","setup":"Offer a different message. Say:","yourLine":[{"text":"\"Enduring harm isn't goodness. You deserve safety, and asking for help is strength, not shame.\"","best":true},{"text":"\"Your mother's generation knew best, just endure it.\""}],"relearn":"Enduring abuse isn't 'being a good wife'; safety matters, and seeking help is strength, not shame.","persona":"Reshma","source":"enduring isn't goodness"},
  {"id":"rh-1024","cat":"never-your-fault","type":"branch","hook":"You catch yourself listing all the ways you could have prevented the abuse.","options":[{"text":"Notice the self-blame; remind yourself only the abuser chose to harm","consequence":"You set responsibility where it belongs.","outcome":"clear","best":true},{"text":"Keep building the case against yourself","consequence":"Only the abuser chose to harm; no list of 'what you could have done' makes it your fault."}],"debrief":"Self-blame feels like control, but the truth is steadier: the responsibility was always the abuser's.","relearn":"No 'what you could have done' makes abuse your fault; only the abuser chose to harm.","persona":"any","source":"drop the self-case"},
  {"id":"rh-1025","cat":"never-your-fault","type":"branch","hook":"Relatives keep hinting that if you were a better partner, none of this would happen.","options":[{"text":"Hold firm that no 'better behaviour' would have stopped his choice to abuse","consequence":"You refuse a false bargain.","outcome":"clear","best":true},{"text":"Try harder to be 'perfect' so it stops","consequence":"No amount of 'being perfect' stops an abuser's choice; the fault was never yours to fix."}],"debrief":"The 'be better and it'll stop' bargain keeps survivors trapped; abuse isn't earned by imperfection.","relearn":"No 'better behaviour' earns safety; an abuser's choice was never yours to prevent or fix.","persona":"Reshma","source":"no perfect-partner bargain"},
  {"id":"rh-1026","cat":"never-your-fault","type":"branch","hook":"You feel guilty for finally telling a friend, as if you betrayed your partner.","options":[{"text":"Recognise that telling the truth about harm is not betrayal","consequence":"You release the false guilt.","outcome":"freed","best":true},{"text":"Swear your friend to silence and pretend it's fine","consequence":"Naming harm to a trusted person is honesty, not betrayal; the secrecy protects the abuser."}],"debrief":"Secrecy serves the abuser; speaking to a trusted person is care for yourself, never a betrayal.","relearn":"Telling a trusted person about harm is honesty, not betrayal; silence only protects the abuser.","persona":"any","source":"truth isn't betrayal"},
  {"id":"rh-1027","cat":"never-your-fault","type":"branch","hook":"A man you support keeps saying he should have been 'man enough' to stop his wife's abuse.","options":[{"text":"Affirm that being harmed isn't a failure of manhood","consequence":"He starts to set down the shame.","outcome":"supported","best":true},{"text":"Agree he just needs to 'man up'","consequence":"Being abused is never a failure of manhood; the fault is the abuser's, whatever the gender."}],"debrief":"'Man up' messaging silences male survivors; abuse is the abuser's doing, never a measure of manhood.","relearn":"Being harmed isn't a failure of manhood; the fault is the abuser's, whatever anyone's gender.","persona":"any","source":"not a manhood failure"},
  {"id":"rh-1028","cat":"never-your-fault","type":"branch","hook":"You keep thinking that if you'd stayed calmer, the violence wouldn't have escalated.","options":[{"text":"Recognise that no tone of yours controls another's violence","consequence":"You stop policing yourself.","outcome":"clear","best":true},{"text":"Resolve to never upset them again","consequence":"No tone or silence of yours controls their violence; the choice to escalate was never yours to manage."}],"debrief":"Walking on eggshells feels protective, but you were never in charge of someone else's violence.","relearn":"No tone or calm of yours controls another's violence; the choice to escalate was never yours.","persona":"any","source":"not yours to manage"},
  {"id":"rh-1029","cat":"never-your-fault","type":"branch","hook":"You're tempted to drop a complaint because people say you 'ruined his life'.","options":[{"text":"Hold that his actions, not your complaint, changed his life","consequence":"You keep responsibility where it belongs.","outcome":"clear","best":true},{"text":"Withdraw it and apologise to keep the peace","consequence":"His choice to abuse, not your complaint, changed his life; seeking safety isn't ruining anyone."}],"debrief":"Abusers often flip blame onto the survivor; the consequences flow from his actions, not yours.","relearn":"His actions, not your complaint, changed his life; seeking safety never 'ruins' the abuser.","persona":"any","source":"consequences flow from his acts"},
  {"id":"rh-1030","cat":"never-your-fault","type":"branch","hook":"You believe the abuse must be a punishment you somehow earned.","options":[{"text":"Reject the idea that anyone earns abuse","consequence":"You loosen the grip of misplaced guilt.","outcome":"freed","best":true},{"text":"Accept it as deserved and keep quiet","consequence":"No one earns or deserves abuse; it's a choice the abuser made, not a punishment you brought on yourself."}],"debrief":"The belief that abuse is 'deserved' is the abuser's lie taking root; nothing you are makes harm just.","relearn":"No one earns or deserves abuse; it's the abuser's choice, never a punishment you brought on yourself.","persona":"any","source":"no one earns it"},
  {"id":"rh-1031","cat":"never-your-fault","type":"branch","hook":"You worry that asking for help will prove you 'couldn't handle' your own marriage.","options":[{"text":"See reaching out as strength, not a personal failure","consequence":"You let support in.","outcome":"supported","best":true},{"text":"Stay silent to look like you're coping","consequence":"Reaching out is strength, not failure; no one is meant to 'handle' abuse alone, and it isn't your fault."}],"debrief":"Abuse isn't a problem you were supposed to solve alone; asking for help is courage, not defeat.","relearn":"Reaching out for help is strength, not failure; no one should face abuse alone, and it isn't your fault.","persona":"Reshma","source":"asking is strength"},
  {"id":"rh-1032","cat":"never-your-fault","type":"branch","hook":"You feel responsible because you introduced your abuser to your family and friends.","options":[{"text":"Remember you couldn't have known; his choices are his own","consequence":"You set down a guilt that isn't yours.","outcome":"freed","best":true},{"text":"Carry the guilt of having 'brought him in'","consequence":"You couldn't have known what he'd choose; introducing him doesn't make his abuse your fault."}],"debrief":"You trusted in good faith; an abuser's later choices are his, not a verdict on your judgement.","relearn":"Trusting someone who later abused isn't your fault; his choices were always his own.","persona":"any","source":"good-faith trust"},
  {"id":"rh-1033","cat":"never-your-fault","type":"branch","hook":"You assume that because you're a man, no one will treat your abuse as real.","options":[{"text":"Choose to reach a helpline or trusted person anyway","consequence":"You find support is for you too.","outcome":"supported","best":true},{"text":"Stay silent, sure you won't be believed","consequence":"Support is for survivors of every gender; reaching 181, 1091 or a trusted person is open to you too."}],"debrief":"Male and other silenced survivors deserve and can get help; the routes belong to you too.","relearn":"Survivors of any gender deserve help; reach a trusted person, 181, 1091 or 112; it's never your fault.","persona":"any","source":"help is for you too"},
  {"id":"rh-1034","cat":"never-your-fault","type":"branch","hook":"You feel you can't grieve the relationship because 'you chose him'.","options":[{"text":"Let yourself grieve without blaming your past choice","consequence":"You make room to heal.","outcome":"healing","best":true},{"text":"Forbid yourself any grief as 'self-inflicted'","consequence":"Choosing to love someone who turned abusive isn't a fault; you're allowed to grieve and to heal."}],"debrief":"Loving someone who later abused you was not a mistake to be punished for; grief and healing are yours.","relearn":"Loving someone who turned abusive isn't a fault; you're allowed to grieve and to heal without blame.","persona":"any","source":"allowed to grieve"},
  {"id":"rh-1035","cat":"never-your-fault","type":"spot","hook":"Spot the two lines that wrongly put the blame on the survivor.","scene":[{"id":"a","text":"\"The only one responsible is the one who hurt you.\"","trick":false},{"id":"b","text":"\"You must have done something to set him off.\"","trick":true},{"id":"c","text":"\"I believe you, and none of this is your fault.\"","trick":false},{"id":"d","text":"\"If you'd kept quiet, it wouldn't have happened.\"","trick":true},{"id":"e","text":"\"What he chose to do is on him, not you.\"","trick":false}],"why":"'You must have done something' and 'if you'd kept quiet' shift blame to the survivor; the others don't.","relearn":"'You must have done something' and 'if you'd kept quiet' are false; the fault is the abuser's.","persona":"any","source":"blame-shift"},
  {"id":"rh-1036","cat":"never-your-fault","type":"spot","hook":"Spot the two myths that excuse the abuser by blaming something else.","scene":[{"id":"a","text":"\"It was the drink talking, not really him.\"","trick":true},{"id":"b","text":"\"He chose to raise his hand; that's on him.\"","trick":false},{"id":"c","text":"\"His temper is his to manage, not yours.\"","trick":false},{"id":"d","text":"\"His rough childhood means you can't blame him.\"","trick":true},{"id":"e","text":"\"Plenty of stressed people never abuse anyone.\"","trick":false}],"why":"'The drink talking' and 'his rough childhood' both excuse the abuser; the rest keep responsibility with him.","relearn":"Alcohol or a hard past may explain context, but never excuse abuse; the choice stays the abuser's.","persona":"any","source":"catch the excuses"},
  {"id":"rh-1037","cat":"never-your-fault","type":"spot","hook":"Spot the two things that wrongly suggest a man can't be a real victim.","scene":[{"id":"a","text":"\"Anyone of any gender can be abused.\"","trick":false},{"id":"b","text":"\"A real man would have just hit back.\"","trick":true},{"id":"c","text":"\"You're believed, and it's not your fault.\"","trick":false},{"id":"d","text":"\"Men can't really be victims of this.\"","trick":true},{"id":"e","text":"\"Male survivors deserve help and support.\"","trick":false}],"why":"'A real man would hit back' and 'men can't be victims' deny male survivors; the others affirm them.","relearn":"Anyone of any gender can be abused; 'real men hit back' and 'men can't be victims' are false and silencing.","persona":"any","source":"catch the man-myths"},
  {"id":"rh-1038","cat":"never-your-fault","type":"spot","hook":"Spot the two lines that blame a survivor for staying.","scene":[{"id":"a","text":"\"Leaving is hard and risky; staying isn't your fault.\"","trick":false},{"id":"b","text":"\"If it were really that bad, you'd have left.\"","trick":true},{"id":"c","text":"\"You stayed for good reasons; none of this is on you.\"","trick":false},{"id":"d","text":"\"You chose to stay, so you can't complain now.\"","trick":true},{"id":"e","text":"\"Whatever you decide, the abuse was still his doing.\"","trick":false}],"why":"'You'd have left' and 'you chose to stay, so you can't complain' blame staying; the others don't.","relearn":"Staying is never a reason for blame; leaving is hard, and the abuse stays the abuser's doing.","persona":"any","source":"staying-blame"},
  {"id":"rh-1039","cat":"never-your-fault","type":"spot","hook":"Spot the two responses that load shame onto the survivor.","scene":[{"id":"a","text":"\"The shame belongs to him, never to you.\"","trick":false},{"id":"b","text":"\"You've brought shame on the whole family.\"","trick":true},{"id":"c","text":"\"Telling me took courage; I'm glad you did.\"","trick":false},{"id":"d","text":"\"Keep it quiet, people will think badly of you.\"","trick":true},{"id":"e","text":"\"None of this reflects on your worth.\"","trick":false}],"why":"'You've brought shame on the family' and 'keep it quiet' load shame onto the survivor; the rest lift it.","relearn":"Shame belongs to the abuser, not the survivor; 'you shamed the family' and 'keep quiet' are wrong.","persona":"any","source":"catch the shaming"},
  {"id":"rh-1040","cat":"never-your-fault","type":"spot","hook":"Spot the two reactions that interrogate a survivor instead of believing them.","scene":[{"id":"a","text":"\"I believe you. What do you need right now?\"","trick":false},{"id":"b","text":"\"Are you sure you're not exaggerating?\"","trick":true},{"id":"c","text":"\"This isn't your fault, and I'm here.\"","trick":false},{"id":"d","text":"\"What did you do to provoke it, exactly?\"","trick":true},{"id":"e","text":"\"Take your time; I'm listening.\"","trick":false}],"why":"'Are you sure you're not exaggerating?' and 'what did you do to provoke it?' interrogate and blame; the rest believe.","relearn":"Believe first; interrogating ('are you sure?', 'what did you do?') doubts and blames a survivor.","persona":"Saxena","source":"catch the interrogation"},
  {"id":"rh-1041","cat":"never-your-fault","type":"spot","hook":"Spot the two beliefs that wrongly tie abuse to who the survivor is.","scene":[{"id":"a","text":"\"Abuse reflects the abuser, not your worth.\"","trick":false},{"id":"b","text":"\"This keeps happening, so it must be you.\"","trick":true},{"id":"c","text":"\"Some people simply choose to harm.\"","trick":false},{"id":"d","text":"\"You attract this because of who you are.\"","trick":true},{"id":"e","text":"\"What was done to you is on them, not you.\"","trick":false}],"why":"'It must be you' and 'you attract this' blame the survivor's character; the rest place fault on the abuser.","relearn":"Abuse reflects the abuser's choices, not your character; 'it must be you' and 'you attract it' are false.","persona":"any","source":"catch the character-blame"},
  {"id":"rh-1042","cat":"never-your-fault","type":"sort","hook":"Sort each line: does it free a survivor of blame, or load blame onto them?","items":[{"id":"a","text":"\"The only one responsible is the one who hurt you.\""},{"id":"b","text":"\"You must have provoked it somehow.\""},{"id":"c","text":"\"It's never your fault, whatever you did.\""},{"id":"d","text":"\"If you'd been a better wife, this wouldn't happen.\""},{"id":"e","text":"\"What he chose is on him, not on you.\""},{"id":"f","text":"\"You stayed, so you brought it on yourself.\""}],"bins":[{"id":"frees","label":"Frees of blame","valence":"pos"},{"id":"blames","label":"Loads blame","valence":"neg"}],"key":{"a":"frees","b":"blames","c":"frees","d":"blames","e":"frees","f":"blames"},"relearn":"Lines placing fault on the abuser free a survivor; 'you provoked it', 'better wife', 'you stayed' blame.","persona":"any","source":"frees or blames"},
  {"id":"rh-1043","cat":"never-your-fault","type":"sort","hook":"Sort: where does responsibility for the abuse truly lie?","items":[{"id":"a","text":"The abuser's choice to harm"},{"id":"b","text":"What the survivor wore that day"},{"id":"c","text":"The abuser's decision to control"},{"id":"d","text":"The survivor saying no to sex"},{"id":"e","text":"The abuser ignoring a clear no"},{"id":"f","text":"The survivor being tired or upset"}],"bins":[{"id":"abuser","label":"The abuser's doing","valence":"neg"},{"id":"notcause","label":"Never a cause","valence":"pos"}],"key":{"a":"abuser","b":"notcause","c":"abuser","d":"notcause","e":"abuser","f":"notcause"},"relearn":"Responsibility lies in the abuser's choices to harm, control or ignore a no; never in what a survivor wore, said or felt.","persona":"any","source":"where fault lies"},
  {"id":"rh-1044","cat":"never-your-fault","type":"sort","hook":"Sort: a supportive response to a survivor, or a blaming one?","items":[{"id":"a","text":"\"I believe you, and it's not your fault.\""},{"id":"b","text":"\"What did you do to set him off?\""},{"id":"c","text":"\"You're safe to tell me, take your time.\""},{"id":"d","text":"\"Couldn't you have just kept quiet?\""},{"id":"e","text":"\"I'm here; what do you need?\""},{"id":"f","text":"\"You always make him angry, though.\""}],"bins":[{"id":"support","label":"Supportive","valence":"pos"},{"id":"blame","label":"Blaming","valence":"neg"}],"key":{"a":"support","b":"blame","c":"support","d":"blame","e":"support","f":"blame"},"relearn":"Belief, safety and 'what do you need?' support a survivor; 'what did you do?' and 'kept quiet?' blame them.","persona":"any","source":"support or blame"},
  {"id":"rh-1045","cat":"never-your-fault","type":"sort","hook":"Sort: a true statement about fault, or a harmful myth?","items":[{"id":"a","text":"Abuse is never the victim's fault"},{"id":"b","text":"Provocation causes abuse"},{"id":"c","text":"Shame belongs to the abuser"},{"id":"d","text":"Real men can't be abused"},{"id":"e","text":"Anyone of any gender can be a victim"},{"id":"f","text":"Staying means it wasn't really abuse"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Harmful myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"It's never the victim's fault and anyone can be a victim; 'provocation causes it', 'men can't', 'staying' are myths.","persona":"any","source":"true or myth"},
  {"id":"rh-1046","cat":"never-your-fault","type":"sort","hook":"Sort: a myth that blames the survivor, or a truth that clears them?","items":[{"id":"a","text":"\"You provoked him\""},{"id":"b","text":"The choice to harm was his alone"},{"id":"c","text":"\"You shamed the family\""},{"id":"d","text":"Shame belongs to the abuser"},{"id":"e","text":"\"You should have left sooner\""},{"id":"f","text":"Leaving is hard and risky, not a fault"}],"bins":[{"id":"myth","label":"Blaming myth","valence":"neg"},{"id":"truth","label":"Clearing truth","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"'You provoked him', 'you shamed us', 'should have left' are blaming myths; the abuser's choice and the survivor's clearing are the truth.","persona":"any","source":"myth or clearing truth"},
  {"id":"rh-1047","cat":"never-your-fault","type":"sort","hook":"Sort: a step that releases self-blame, or a trap that keeps it?","items":[{"id":"a","text":"Naming that only the abuser chose to harm"},{"id":"b","text":"Replaying every 'what if I had…'"},{"id":"c","text":"Letting a trusted person remind you it's not your fault"},{"id":"d","text":"Promising to be 'perfect' so it stops"},{"id":"e","text":"Grieving without punishing yourself"},{"id":"f","text":"Keeping the secret to avoid 'causing trouble'"}],"bins":[{"id":"releases","label":"Releases self-blame","valence":"pos"},{"id":"keeps","label":"Keeps self-blame","valence":"neg"}],"key":{"a":"releases","b":"keeps","c":"releases","d":"keeps","e":"releases","f":"keeps"},"relearn":"Naming the abuser's choice, support and grieving release self-blame; 'what ifs', perfectionism and secrecy keep it.","persona":"any","source":"self-blame"},
  {"id":"rh-1048","cat":"never-your-fault","type":"sort","hook":"Sort: an excuse that shifts blame off the abuser, or the truth that keeps it on them?","items":[{"id":"a","text":"\"He chose to hit; that's on him\""},{"id":"b","text":"\"It was the alcohol, not really him\""},{"id":"c","text":"\"His temper is his to manage\""},{"id":"d","text":"\"His bad day made him do it\""},{"id":"e","text":"\"Stress doesn't force anyone to abuse\""},{"id":"f","text":"\"You pushed his buttons, so it's shared\""}],"bins":[{"id":"truth","label":"Keeps fault on abuser","valence":"pos"},{"id":"excuse","label":"Shifts blame away","valence":"neg"}],"key":{"a":"truth","b":"excuse","c":"truth","d":"excuse","e":"truth","f":"excuse"},"relearn":"His choice and his temper keep fault on the abuser; 'the alcohol', 'a bad day', 'you pushed his buttons' shift it wrongly.","persona":"any","source":"truth or excuse"},
  {"id":"rh-1049","cat":"never-your-fault","type":"match","hook":"Match each blaming myth to the truth that answers it.","pairs":[{"left":"\"You provoked it\"","right":"Provocation is never a cause of abuse"},{"left":"\"You should have left\"","right":"Leaving is hard and dangerous, not a fault"},{"left":"\"Men can't be victims\"","right":"Anyone of any gender can be abused"},{"left":"\"You shamed the family\"","right":"Shame belongs to the abuser alone"},{"left":"\"It must be you\"","right":"Abuse reflects the abuser, not your worth"}],"relearn":"Every blame myth has a true answer that returns responsibility to the abuser and clears the survivor.","persona":"any","source":"myth to truth"},
  {"id":"rh-1050","cat":"never-your-fault","type":"match","hook":"Match each survivor's worry to the reassurance that meets it.","pairs":[{"left":"\"I stayed too long\"","right":"There's no deadline on getting safe"},{"left":"\"I went back to him\"","right":"Returning is common and never your fault"},{"left":"\"I didn't fight back\"","right":"Freezing is survival, not consent"},{"left":"\"No one will believe a man\"","right":"You're believed, and help is yours too"},{"left":"\"I should have known\"","right":"Abusers hide it; not seeing it isn't your fault"}],"relearn":"Each common self-blame, staying, returning, freezing, being male, not knowing, meets a truth that clears the survivor.","persona":"any","source":"worry to reassurance"},
  {"id":"rh-1051","cat":"never-your-fault","type":"match","hook":"Match each false excuse for an abuser to why it doesn't hold.","pairs":[{"left":"\"It was the drink\"","right":"Many drink and never harm anyone"},{"left":"\"He had a hard past\"","right":"A hard past explains, but never excuses"},{"left":"\"She made him angry\"","right":"Anger is no licence to harm"},{"left":"\"He was stressed\"","right":"Stress doesn't force anyone to abuse"},{"left":"\"It's just his nature\"","right":"Harm is a choice, not a fixed fate"}],"relearn":"Drink, a hard past, anger, stress and 'his nature' explain context but never excuse the abuser's choice.","persona":"any","source":"excuse to rebuttal"},
  {"id":"rh-1052","cat":"never-your-fault","type":"match","hook":"Match each survivor's feeling to the steadying truth.","pairs":[{"left":"Shame","right":"It belongs to the abuser, not to you"},{"left":"Guilt for 'causing' it","right":"Only the abuser chose to harm"},{"left":"Feeling unlovable","right":"Harm reflects them, not your worth"},{"left":"Self-doubt","right":"What you felt was real"},{"left":"Loneliness","right":"You're not alone; help exists"}],"relearn":"Shame, guilt, feeling unlovable, self-doubt and loneliness each meet a truth that places fault away from the survivor.","persona":"any","source":"feeling to truth"},
  {"id":"rh-1053","cat":"never-your-fault","type":"match","hook":"Match each blaming question to the believing one that should replace it.","pairs":[{"left":"\"What did you do to him?\"","right":"\"What did he do to you?\""},{"left":"\"Why didn't you leave?\"","right":"\"What do you need right now?\""},{"left":"\"Are you exaggerating?\"","right":"\"I believe you.\""},{"left":"\"Why provoke him?\"","right":"\"None of this is your fault.\""},{"left":"\"Couldn't you keep quiet?\"","right":"\"You're safe to tell me.\""}],"relearn":"Swap blaming questions for believing ones: ask what he did, what they need, and affirm it's not their fault.","persona":"Saxena","source":"swap the question"},
  {"id":"rh-1054","cat":"never-your-fault","type":"match","hook":"Match each survivor to a true reassurance that fits their fear.","pairs":[{"left":"A man afraid of being mocked","right":"Anyone can be abused; you're believed"},{"left":"A wife told she shamed the family","right":"The shame is the abuser's, not yours"},{"left":"Someone who returned more than once","right":"Returning is normal, not your fault"},{"left":"A survivor who froze","right":"Freezing is survival, not consent"},{"left":"A parent who stayed for the kids","right":"Staying for them was love, not a fault"}],"relearn":"Mocked men, shamed wives, returners, those who froze, parents who stayed: each deserves a clearing truth.","persona":"any","source":"to reassurance"},
  {"id":"rh-1055","cat":"never-your-fault","type":"match","hook":"Match the wrong instinct to the survivor-centred one that replaces it.","pairs":[{"left":"Interrogate the survivor","right":"Believe them first"},{"left":"Push them to leave now","right":"Respect their own pace"},{"left":"Decide and act for them","right":"Ask what they need"},{"left":"Hint they provoked it","right":"Name it's not their fault"},{"left":"Tell them to keep quiet","right":"Make it safe to speak"}],"relearn":"Believe, respect pace, ask what's needed, affirm no-fault and make it safe to speak; never interrogate or push.","persona":"Saxena","source":"instinct to right move"},
  {"id":"rh-1056","cat":"never-your-fault","type":"match","hook":"Match each need a survivor names to a real route in India.","pairs":[{"left":"In immediate danger","right":"Emergency 112"},{"left":"Wants domestic-violence support","right":"Women Helpline 181"},{"left":"A woman in distress, day or night","right":"1091"},{"left":"Needs free legal help","right":"NALSA legal aid 15100"},{"left":"Just needs to be believed","right":"A trusted person"}],"relearn":"112 for danger, 181 for DV support, 1091 in distress, NALSA 15100 for legal aid, a trusted person to be believed.","persona":"Razia","source":"need to route"},
  {"id":"rh-1057","cat":"never-your-fault","type":"reflect","hook":"Lensy: whatever you wore, said or did, the abuse was never your fault. Sit with that?","prompt":"What rises for you?","options":["It wasn't my fault","Hard to believe","I'm trying to"],"affirm":"Whatever you wore, said or did, the choice to harm was the abuser's alone; the fault was never yours.","relearn":"Whatever you wore, said or did, abuse was never your fault; the choice to harm was the abuser's alone.","persona":"any","source":"never your fault"},
  {"id":"rh-1058","cat":"never-your-fault","type":"reflect","hook":"Lensy: the shame of what happened belongs to the one who hurt you, not to you. Let that land?","prompt":"What do you notice?","options":["Not my shame","Still carrying it","Setting it down"],"affirm":"Shame is the abuser's to carry, never yours; you can begin, gently, to set down what was never yours.","relearn":"The shame of abuse belongs to the abuser, never to the person harmed; you can set it down.","persona":"any","source":"shame isn't yours"},
  {"id":"rh-1059","cat":"never-your-fault","type":"reflect","hook":"Lensy: men and others who are silenced are believed here, fully and equally. Does that reach you?","prompt":"What comes up?","options":["I'm believed too","I wasn't sure","That helps"],"affirm":"Survivors of every gender are believed here; your experience is real, and it was never your fault.","relearn":"Survivors of any gender are believed fully and equally; abuse is real and never the survivor's fault.","persona":"any","source":"believed equally"},
  {"id":"rh-1060","cat":"never-your-fault","type":"reflect","hook":"Lensy: staying, leaving, or not yet knowing your options, none of it makes the abuse your fault. Agree?","prompt":"What feels true?","options":["None of it's my fault","I needed that","Still learning"],"affirm":"Staying, leaving or not yet knowing your options is never a reason for blame; the fault stays the abuser's.","relearn":"Staying, leaving or not knowing your options is never a reason for blame; the fault stays the abuser's.","persona":"any","source":"no reason for blame"},
  {"id":"rh-1061","cat":"never-your-fault","type":"reflect","hook":"Lensy: recognising what happened isn't weakness, it's the first brave step. Recognise that?","prompt":"What stirs?","options":["It's a first step","Feels brave","I'm naming it"],"affirm":"Naming what happened is courage, not weakness; recognition is where safety and healing begin.","relearn":"Naming abuse is the first brave step, not weakness; recognition is where safety and healing begin.","persona":"any","source":"naming is brave"},
  {"id":"rh-1062","cat":"never-your-fault","type":"reflect","hook":"Lensy: you are not what was done to you; the harm reflects them, never your worth. Believe it for yourself?","prompt":"What rises?","options":["I'm more than this","Working on it","I hear that"],"affirm":"You are not what was done to you; the harm reflects the abuser's choices, never your worth or who you are.","relearn":"You are not what was done to you; abuse reflects the abuser's choices, never your worth.","persona":"any","source":"not what was done to you"},
  {"id":"rh-1063","cat":"never-your-fault","type":"reflect","hook":"Lensy: healing has no timetable, and going at your own pace is not a failure. Let yourself believe that?","prompt":"What feels right?","options":["My own pace","No rush","I'll be gentle"],"affirm":"Healing has no timetable; your pace is the right pace, and being gentle with yourself is never a failure.","relearn":"Healing has no timetable; your own pace is the right pace, and self-compassion is never a failure.","persona":"any","source":"your own pace"},
  {"id":"rh-1064","cat":"never-your-fault","type":"reflect","hook":"Lensy: you don't have to carry this alone; a trusted person or 181, 1091, 112 is there. Worth remembering?","prompt":"What lands?","options":["I'm not alone","Help is there","I'll reach out"],"affirm":"You don't have to carry this alone; a trusted person, 181, 1091 or 112 is there, and it's never your fault.","relearn":"You don't have to carry abuse alone; a trusted person, 181, 1091 or 112 is there, and it's never your fault.","persona":"any","source":"not alone"},
  {"id":"rh-1080","cat":"respect-daily","type":"sort","persona":"any","source":"mental load","relearn":"Noticing and planning the home together shares the mental load; one person carrying it all isn't respect.","hook":"Sort: sharing the mental load, or dumping it on one person?","items":[{"id":"a","text":"Both track what the home needs"},{"id":"b","text":"One must remember every chore and bill"},{"id":"c","text":"You plan meals and school runs together"},{"id":"d","text":"\"Just tell me what to do\" every time"},{"id":"e","text":"Both notice when supplies run low"},{"id":"f","text":"One person reminds, nags and carries it alone"}],"bins":[{"id":"share","label":"Shared load","valence":"pos"},{"id":"dump","label":"One carries all","valence":"neg"}],"key":{"a":"share","b":"dump","c":"share","d":"dump","e":"share","f":"dump"}},
  {"id":"rh-1081","cat":"respect-daily","type":"sort","persona":"any","source":"fair conflict","relearn":"Listening, staying calm and finding a middle path is respectful disagreement; shouting or stonewalling silences it.","hook":"Sort: a respectful disagreement, or a silencing one?","items":[{"id":"a","text":"You both say your side and listen"},{"id":"b","text":"One shouts until the other gives up"},{"id":"c","text":"You look for a middle path together"},{"id":"d","text":"Silent treatment for days after a no"},{"id":"e","text":"You can disagree and still feel safe"},{"id":"f","text":"Bringing up old faults to win"}],"bins":[{"id":"fair","label":"Respectful","valence":"pos"},{"id":"silence","label":"Silencing","valence":"neg"}],"key":{"a":"fair","b":"silence","c":"fair","d":"silence","e":"fair","f":"silence"}},
  {"id":"rh-1082","cat":"respect-daily","type":"sort","persona":"any","source":"us without erasing me","relearn":"Keeping your work, friends and choices is respect; needing permission for ordinary things erases you.","hook":"Sort: respects your own life, or erases it?","items":[{"id":"a","text":"You keep your own friends and hobbies"},{"id":"b","text":"You need permission to see your family"},{"id":"c","text":"Your job and goals still matter"},{"id":"d","text":"You drop everything you once loved"},{"id":"e","text":"\"Us\" grows without you disappearing"},{"id":"f","text":"Your name barely comes up any more"}],"bins":[{"id":"keep","label":"Keeps 'me'","valence":"pos"},{"id":"erase","label":"Erases 'me'","valence":"neg"}],"key":{"a":"keep","b":"erase","c":"keep","d":"erase","e":"keep","f":"erase"}},
  {"id":"rh-1083","cat":"respect-daily","type":"sort","persona":"Reshma","source":"money say","relearn":"Both seeing the accounts and deciding spending is an equal say; one hiding money or rationing it isn't.","hook":"Sort: an equal say in money, or one-sided control?","items":[{"id":"a","text":"Both of you can see the bank balance"},{"id":"b","text":"You must beg for every rupee"},{"id":"c","text":"Big spends are decided together"},{"id":"d","text":"Your earnings vanish into their account"},{"id":"e","text":"You each have some money of your own"},{"id":"f","text":"They hide what the family actually earns"}],"bins":[{"id":"equal","label":"Equal say","valence":"pos"},{"id":"control","label":"One controls","valence":"neg"}],"key":{"a":"equal","b":"control","c":"equal","d":"control","e":"equal","f":"control"}},
  {"id":"rh-1084","cat":"respect-daily","type":"sort","persona":"any","source":"sharing not helping","relearn":"Owning tasks without being asked is sharing; only 'helping when told' leaves the load on one person.","hook":"Sort: chores shared as a team, or 'helping' on request?","items":[{"id":"a","text":"They cook some nights without being told"},{"id":"b","text":"\"I'll help if you ask nicely\""},{"id":"c","text":"Both just notice the bins are full"},{"id":"d","text":"You assign every single task"},{"id":"e","text":"Each owns a few jobs as their own"},{"id":"f","text":"\"It's your house, your work\""}],"bins":[{"id":"team","label":"Shared as a team","valence":"pos"},{"id":"help","label":"'Helps' if asked","valence":"neg"}],"key":{"a":"team","b":"help","c":"team","d":"help","e":"team","f":"help"}},
  {"id":"rh-1085","cat":"respect-daily","type":"sort","persona":"Reshma","source":"in-laws","relearn":"Deciding family matters as a couple is respect; having in-laws' wishes imposed over your voice isn't.","hook":"Sort: in-law decisions made together, or imposed on you?","items":[{"id":"a","text":"You two agree before saying yes to family"},{"id":"b","text":"In-laws overrule you and your partner stays silent"},{"id":"c","text":"Your wishes count in family plans"},{"id":"d","text":"You're told to obey, not discuss"},{"id":"e","text":"Your partner backs your voice with their family"},{"id":"f","text":"Your opinion is dismissed as 'not your place'"}],"bins":[{"id":"together","label":"Decided together","valence":"pos"},{"id":"imposed","label":"Imposed on you","valence":"neg"}],"key":{"a":"together","b":"imposed","c":"together","d":"imposed","e":"together","f":"imposed"}},
  {"id":"rh-1086","cat":"respect-daily","type":"sort","persona":"any","source":"valuing work","relearn":"Valuing your job, study or homemaking is respect; mocking it or calling it worthless is not.","hook":"Sort: a partner who values your work, or belittles it?","items":[{"id":"a","text":"They're proud of the work you do"},{"id":"b","text":"\"What you do isn't real work\""},{"id":"c","text":"Your homemaking is treated as real labour"},{"id":"d","text":"They mock your career out loud"},{"id":"e","text":"They ask about your day and mean it"},{"id":"f","text":"\"You'd be nothing without me\""}],"bins":[{"id":"value","label":"Values it","valence":"pos"},{"id":"belittle","label":"Belittles it","valence":"neg"}],"key":{"a":"value","b":"belittle","c":"value","d":"belittle","e":"value","f":"belittle"}},
  {"id":"rh-1087","cat":"respect-daily","type":"sort","persona":"any","source":"co-parenting","relearn":"Raising children with both voices is respect; one parent dictating every rule and overruling the other isn't.","hook":"Sort: parenting decided as a pair, or dictated by one?","items":[{"id":"a","text":"You agree on the children's routine together"},{"id":"b","text":"One sets every rule, no discussion"},{"id":"c","text":"Both of you comfort and discipline"},{"id":"d","text":"\"I'm the parent that matters\""},{"id":"e","text":"You back each other in front of the kids"},{"id":"f","text":"One undermines the other to the children"}],"bins":[{"id":"pair","label":"Decided as a pair","valence":"pos"},{"id":"one","label":"One dictates","valence":"neg"}],"key":{"a":"pair","b":"one","c":"pair","d":"one","e":"pair","f":"one"}},
  {"id":"rh-1088","cat":"respect-daily","type":"sort","persona":"any","source":"even-handed","relearn":"Respect owed by and to both partners of any gender is mutual; a rule only one must follow isn't.","hook":"Sort: respect that goes both ways, or a one-way rule?","items":[{"id":"a","text":"Both apologise when they're wrong"},{"id":"b","text":"Only one is ever allowed to be upset"},{"id":"c","text":"Each can ask the other to change"},{"id":"d","text":"\"Rules are for you, not me\""},{"id":"e","text":"Both your needs get airtime"},{"id":"f","text":"One's comfort always outranks the other's"}],"bins":[{"id":"both","label":"Both ways","valence":"pos"},{"id":"oneway","label":"One-way rule","valence":"neg"}],"key":{"a":"both","b":"oneway","c":"both","d":"oneway","e":"both","f":"oneway"}},
  {"id":"rh-1089","cat":"respect-daily","type":"sort","persona":"any","source":"everyday dignity","relearn":"Privacy, kind words and being trusted keep your dignity; daily put-downs and snooping chip at it.","hook":"Sort: keeps your dignity, or chips at it daily?","items":[{"id":"a","text":"They speak to you kindly, even when cross"},{"id":"b","text":"Constant small put-downs all day"},{"id":"c","text":"Your privacy and space are respected"},{"id":"d","text":"They read your messages without asking"},{"id":"e","text":"You're trusted to make your own choices"},{"id":"f","text":"Eye-rolls and sighs at everything you say"}],"bins":[{"id":"dignity","label":"Keeps dignity","valence":"pos"},{"id":"chip","label":"Chips at it","valence":"neg"}],"key":{"a":"dignity","b":"chip","c":"dignity","d":"chip","e":"dignity","f":"chip"}},
  {"id":"rh-1090","cat":"respect-daily","type":"sort","persona":"any","source":"shared plans","relearn":"Both shaping where you live, save and spend is an equal voice; one deciding it all alone overrules you.","hook":"Sort: an equal voice in plans, or being overruled?","items":[{"id":"a","text":"You both choose where to live"},{"id":"b","text":"They booked the move without telling you"},{"id":"c","text":"You plan savings goals together"},{"id":"d","text":"\"I've decided, that's final\""},{"id":"e","text":"Holidays are picked by both of you"},{"id":"f","text":"Your preference is never even asked"}],"bins":[{"id":"voice","label":"Equal voice","valence":"pos"},{"id":"over","label":"Overruled","valence":"neg"}],"key":{"a":"voice","b":"over","c":"voice","d":"over","e":"voice","f":"over"}},
  {"id":"rh-1091","cat":"respect-daily","type":"sort","persona":"any","source":"fair rest","relearn":"Both partners getting downtime is fair; one resting while the other never stops is not respect.","hook":"Sort: a fair share of rest, or rest for one only?","items":[{"id":"a","text":"You both get time to relax"},{"id":"b","text":"One sits while the other never stops"},{"id":"c","text":"Weekends include rest for each of you"},{"id":"d","text":"\"Your job is to keep going\""},{"id":"e","text":"You take turns with the late-night baby"},{"id":"f","text":"One's tiredness counts, the other's doesn't"}],"bins":[{"id":"fair","label":"Fair rest","valence":"pos"},{"id":"unfair","label":"Rest for one","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"}},
  {"id":"rh-1092","cat":"respect-daily","type":"sort","persona":"any","source":"adults not parent-child","relearn":"Two adults negotiating as equals is respect; one treating the other as a child to manage is not.","hook":"Sort: handled like adults, or like a parent and child?","items":[{"id":"a","text":"You negotiate as equals"},{"id":"b","text":"They give you 'permission' like a child"},{"id":"c","text":"Both trusted to handle money and time"},{"id":"d","text":"You're scolded for small mistakes"},{"id":"e","text":"Mistakes are talked through, not punished"},{"id":"f","text":"They set a 'curfew' for you"}],"bins":[{"id":"adults","label":"Two adults","valence":"pos"},{"id":"pc","label":"Parent-and-child","valence":"neg"}],"key":{"a":"adults","b":"pc","c":"adults","d":"pc","e":"adults","f":"pc"}},
  {"id":"rh-1093","cat":"respect-daily","type":"sort","persona":"any","source":"feelings heard","relearn":"Taking your feelings seriously is respect; calling them dramatic or 'too sensitive' dismisses them.","hook":"Sort: makes room for your feelings, or dismisses them?","items":[{"id":"a","text":"\"Tell me what's upsetting you\""},{"id":"b","text":"\"You're too sensitive, drop it\""},{"id":"c","text":"They sit with you when you're low"},{"id":"d","text":"Your worry is laughed off"},{"id":"e","text":"Your bad day is taken seriously"},{"id":"f","text":"\"Stop being so dramatic\""}],"bins":[{"id":"room","label":"Makes room","valence":"pos"},{"id":"dismiss","label":"Dismisses","valence":"neg"}],"key":{"a":"room","b":"dismiss","c":"room","d":"dismiss","e":"room","f":"dismiss"}},
  {"id":"rh-1094","cat":"respect-daily","type":"sort","persona":"any","source":"raising it kindly","relearn":"Naming a problem calmly and as a team is kind; mocking, name-calling or contempt corrodes respect.","hook":"Sort: a kind way to raise a problem, or a contemptuous one?","items":[{"id":"a","text":"\"Can we sort the bills out together?\""},{"id":"b","text":"\"You're useless, as always\""},{"id":"c","text":"\"I felt hurt when that happened\""},{"id":"d","text":"Sneering and name-calling"},{"id":"e","text":"\"Let's fix this as a team\""},{"id":"f","text":"Mocking you in front of others"}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"contempt","label":"Contempt","valence":"neg"}],"key":{"a":"kind","b":"contempt","c":"kind","d":"contempt","e":"kind","f":"contempt"}},
  {"id":"rh-1095","cat":"respect-daily","type":"sort","persona":"any","source":"keeping ties","relearn":"Keeping your own friends and family is healthy; being slowly cut off from them is a warning, not closeness.","hook":"Sort: respects you keeping ties, or cuts you off?","items":[{"id":"a","text":"You still visit your own parents"},{"id":"b","text":"Friends are slowly pushed away"},{"id":"c","text":"They're glad you have close friends"},{"id":"d","text":"\"You don't need anyone but me\""},{"id":"e","text":"Your calls home are welcomed"},{"id":"f","text":"Every outing causes a fight"}],"bins":[{"id":"ties","label":"Keeps your ties","valence":"pos"},{"id":"cut","label":"Cuts you off","valence":"neg"}],"key":{"a":"ties","b":"cut","c":"ties","d":"cut","e":"ties","f":"cut"}},
  {"id":"rh-1096","cat":"respect-daily","type":"sort","persona":"any","source":"appreciation","relearn":"Noticing and thanking each other's effort is respect; treating one person's work as invisible isn't.","hook":"Sort: appreciation that flows, or being taken for granted?","items":[{"id":"a","text":"\"Thank you for handling that\""},{"id":"b","text":"Your effort is never noticed"},{"id":"c","text":"Each thanks the other for small things"},{"id":"d","text":"\"That's just what you're for\""},{"id":"e","text":"Good days are credited to both"},{"id":"f","text":"Only complaints, never thanks"}],"bins":[{"id":"seen","label":"Appreciated","valence":"pos"},{"id":"granted","label":"Taken for granted","valence":"neg"}],"key":{"a":"seen","b":"granted","c":"seen","d":"granted","e":"seen","f":"granted"}},
  {"id":"rh-1097","cat":"respect-daily","type":"reflect","persona":"any","source":"mental load","relearn":"The mental load is real work; sharing it is part of respect.","hook":"Lensy: the invisible work of remembering and planning the home is real work. Recognise that?","prompt":"What do you think?","options":["Yes","It's real work","I hadn't named it"],"affirm":"The mental load of remembering and planning is real labour; sharing it, not just 'helping', is respect."},
  {"id":"rh-1098","cat":"respect-daily","type":"reflect","persona":"any","source":"safe disagreement","relearn":"Disagreement handled with respect is normal and healthy.","hook":"Lensy: you can disagree with your partner and still be a loving, loyal one. True for you?","prompt":"What do you think?","options":["Yes","Disagreement is okay","Still loyal"],"affirm":"Disagreeing respectfully is normal and healthy; a real partnership has room for two minds, not one."},
  {"id":"rh-1099","cat":"respect-daily","type":"reflect","persona":"any","source":"needs count","relearn":"Both partners' needs count equally; fairness, not one-sided sacrifice.","hook":"Lensy: your needs count just as much as your partner's, never less. Believe that for yourself?","prompt":"What do you think?","options":["Yes","Mine count too","Just as much"],"affirm":"Your needs count equally; a fair home isn't built on one person quietly sacrificing themselves."},
  {"id":"rh-1100","cat":"respect-daily","type":"reflect","persona":"any","source":"keeping ties","relearn":"You keep your own friends and family; no permission is needed.","hook":"Lensy: you don't need anyone's permission to see your own family and friends. Agree?","prompt":"What do you think?","options":["Yes","No permission needed","They're mine"],"affirm":"Your ties to family and friends are yours to keep; a respectful partner is glad you have them."},
  {"id":"rh-1101","cat":"respect-daily","type":"reflect","persona":"any","source":"us without erasing me","relearn":"Partnership builds 'us' without erasing 'me'.","hook":"Lensy: building a life together shouldn't mean one of you disappears. Land for you?","prompt":"What do you think?","options":["Yes","Keep my 'me'","Us and me"],"affirm":"A good partnership builds 'us' without erasing 'me'; you both stay whole people inside it."},
  {"id":"rh-1102","cat":"respect-daily","type":"reflect","persona":"any","source":"even-handed","relearn":"Mutual respect is even-handed: owed to and by partners of any gender.","hook":"Lensy: respect at home is owed by you and to you, whatever your gender. Recognise that?","prompt":"What do you think?","options":["Yes","Both ways","Either of us"],"affirm":"Mutual respect is even-handed; it's owed to and by partners of any gender, never a one-way rule."},
  {"id":"rh-1103","cat":"respect-daily","type":"reflect","persona":"Reshma","source":"money say","relearn":"Both partners' money and decisions count, not just the higher earner's.","hook":"Lensy: how money is spent is a decision for both of you, not just whoever earns more. Agree?","prompt":"What do you think?","options":["Yes","Both decide","Not just the earner"],"affirm":"An equal voice in money belongs to both partners; earning more doesn't buy the only say."},
  {"id":"rh-1104","cat":"respect-daily","type":"reflect","persona":"any","source":"valuing work","relearn":"Valuing your partner's work and goals is real respect.","hook":"Lensy: a partner who's proud of your work and goals is showing real respect. Feel that?","prompt":"What do you think?","options":["Yes","Proud of me","That's respect"],"affirm":"Being valued for your work, study or homemaking is real respect; belittling it never is."},
  {"id":"rh-1105","cat":"respect-daily","type":"reflect","persona":"any","source":"fair rest","relearn":"Rest and downtime are shared; both partners deserve them.","hook":"Lensy: rest and downtime should be shared, not just one person's right. True for you?","prompt":"What do you think?","options":["Yes","Rest is shared","Both deserve it"],"affirm":"Both partners deserve rest; a home where only one ever relaxes isn't a fair one."},
  {"id":"rh-1106","cat":"respect-daily","type":"reflect","persona":"any","source":"adults not parent-child","relearn":"Partners meet as two equal adults, not parent and child.","hook":"Lensy: you're two adults here, not a parent and a child to be managed. Recognise that?","prompt":"What do you think?","options":["Yes","Two adults","Not managed"],"affirm":"A respectful partnership is two adults as equals, not one giving the other 'permission' like a child."},
  {"id":"rh-1107","cat":"respect-daily","type":"reflect","persona":"any","source":"feelings heard","relearn":"Taking each other's feelings seriously is respect.","hook":"Lensy: your feelings deserve to be heard, not waved away as 'too much'. Agree?","prompt":"What do you think?","options":["Yes","Heard, not waved away","Mine matter"],"affirm":"Your feelings deserve a hearing; 'you're too sensitive' is dismissal, not respect."},
  {"id":"rh-1108","cat":"respect-daily","type":"reflect","persona":"any","source":"appreciation","relearn":"Appreciating each other's effort keeps daily respect alive.","hook":"Lensy: saying 'thank you' for each other's effort keeps respect alive day to day. Land for you?","prompt":"What do you think?","options":["Yes","Thanks matters","Stay grateful"],"affirm":"Noticing and thanking each other's effort is small but real respect; being taken for granted corrodes it."},
  {"id":"rh-1109","cat":"respect-daily","type":"branch","persona":"any","source":"career decision","relearn":"Your career is a joint decision; an equal voice covers your own future.","hook":"Your partner assumes you'll quit your job after the wedding, without asking you.","options":[{"text":"Talk it through; your career is a joint decision, not an assumption","consequence":"You keep your equal voice over your own future.","best":true},{"text":"Quietly give it up to avoid an argument","consequence":"Talking it through keeps your equal voice; silently giving up your job erases it."}],"debrief":"Big life choices like your job are decided together, not assumed away."},
  {"id":"rh-1110","cat":"respect-daily","type":"branch","persona":"any","source":"mental load","relearn":"Name the mental load and share it, rather than carrying it invisibly.","hook":"You're carrying every bit of the household planning and feeling invisible.","options":[{"text":"Name the mental load and ask to truly share it, not just 'help'","consequence":"You move toward sharing the real work.","best":true},{"text":"Keep doing it all so nothing 'falls apart'","consequence":"Naming the load and sharing it is respect; doing it all silently keeps you invisible."}],"debrief":"The mental load is real work; sharing it is part of respect, not 'helping when asked'."},
  {"id":"rh-1111","cat":"respect-daily","type":"branch","persona":"Reshma","source":"money say","relearn":"Both partners share visibility and say over the money.","hook":"Your partner says only big purchases matter, so small spends are theirs to control.","options":[{"text":"Set that both of you can see and shape the money","consequence":"You build an equal say over finances.","best":true},{"text":"Hand over your earnings and ask for what you need","consequence":"An equal say means both see the money; handing it all over and asking isn't equal."}],"debrief":"An equal voice means both partners' money and decisions count."},
  {"id":"rh-1112","cat":"respect-daily","type":"branch","persona":"any","source":"fair conflict","relearn":"Handle disagreement calmly and openly, not with silence.","hook":"A small disagreement is brewing and you're tempted to just go silent.","options":[{"text":"Stay in it calmly and say what you actually feel","consequence":"You keep disagreement respectful and open.","best":true},{"text":"Shut down and give the silent treatment","consequence":"Staying calm keeps disagreement respectful; silent treatment punishes instead of resolving."}],"debrief":"Disagreement handled with respect is healthy; stonewalling is not."},
  {"id":"rh-1113","cat":"respect-daily","type":"branch","persona":"any","source":"shared plans","relearn":"Shared plans are decided together; both voices count.","hook":"Your partner keeps deciding family visits and trips without asking you.","options":[{"text":"Agree that plans affecting you both are made together","consequence":"You reclaim an equal voice in shared plans.","best":true},{"text":"Just go along with whatever is announced","consequence":"Deciding shared plans together is an equal voice; only going along erodes it."}],"debrief":"Plans that affect you both should be made together."},
  {"id":"rh-1114","cat":"respect-daily","type":"branch","persona":"any","source":"keeping ties","relearn":"Keep your own ties; you don't need permission for them.","hook":"Your partner is slowly fencing you off from your own friends and family.","options":[{"text":"Keep your ties and say clearly that they matter to you","consequence":"You protect connections that are yours.","best":true},{"text":"Drop everyone to keep the peace","consequence":"Keeping your ties protects you; cutting everyone off to keep peace isolates you."}],"debrief":"Keeping your own friends and family is healthy; isolation is a warning, not closeness."},
  {"id":"rh-1115","cat":"respect-daily","type":"branch","persona":"any","source":"us without erasing me","relearn":"Keep your own interests; 'us' shouldn't erase 'me'.","hook":"You realise you've stopped doing everything you once loved since moving in together.","options":[{"text":"Pick one of your own things back up and protect it","consequence":"You keep 'me' alive inside 'us'.","best":true},{"text":"Decide your old self doesn't matter now","consequence":"Reclaiming your own interests keeps you whole; deciding 'me' doesn't matter erases you."}],"debrief":"Partnership builds 'us' without erasing 'me'."},
  {"id":"rh-1116","cat":"respect-daily","type":"branch","persona":"any","source":"valuing work","relearn":"Homemaking is real work; your rest counts as much as theirs.","hook":"Your partner waves off your tiredness, saying running the home isn't 'real work'.","options":[{"text":"Name homemaking as real labour that deserves rest too","consequence":"You assert that your work and rest count.","best":true},{"text":"Accept that your exhaustion doesn't count","consequence":"Naming homemaking as real work claims your rest; accepting it 'doesn't count' isn't fair."}],"debrief":"Homemaking is real labour, and rest belongs to both partners."},
  {"id":"rh-1117","cat":"respect-daily","type":"branch","persona":"Reshma","source":"even-handed","relearn":"Marriage is two equals; an equal voice belongs to both.","hook":"A family elder tells you to obey your spouse and never question them.","options":[{"text":"Hold that a marriage is two equals, not obey-and-rule","consequence":"You keep your equal standing.","best":true},{"text":"Accept that your role is just to obey","consequence":"Holding to equality keeps your standing; accepting 'just obey' makes the home one-sided."}],"debrief":"A respectful marriage is a partnership of equals, not a leader and a follower."},
  {"id":"rh-1118","cat":"respect-daily","type":"branch","persona":"any","source":"co-parenting","relearn":"Parenting decisions are made together, with both voices counting.","hook":"You and your partner disagree on the children's schooling and it's getting tense.","options":[{"text":"Hear each other out and decide it together as parents","consequence":"You co-parent with two voices.","best":true},{"text":"Let whoever shouts loudest set the rule","consequence":"Deciding together respects both parents; letting the loudest win silences one."}],"debrief":"Raising children works best with both parents' voices, decided together."},
  {"id":"rh-1119","cat":"respect-daily","type":"branch","persona":"any","source":"money say","relearn":"Money is a shared problem solved together, not 'nagging'.","hook":"Your partner treats your money worries as you 'nagging' instead of a shared problem.","options":[{"text":"Frame the budget as something you'll solve as a team","consequence":"You turn it into shared work, not blame.","best":true},{"text":"Stop raising it so you're not called a nag","consequence":"Framing it as teamwork shares the problem; staying silent to avoid 'nag' leaves it on you."}],"debrief":"Money worries are a shared problem, raised kindly and solved as a team."},
  {"id":"rh-1120","cat":"respect-daily","type":"branch","persona":"any","source":"everyday dignity","relearn":"Public put-downs aren't okay; everyday dignity counts.","hook":"Your partner snaps at you in front of others, then says you're 'too sensitive' to mind.","options":[{"text":"Calmly say being put down in public isn't okay with you","consequence":"You hold a line on everyday dignity.","best":true},{"text":"Laugh it off and pretend it didn't sting","consequence":"Naming it kindly protects your dignity; laughing it off lets the put-downs continue."}],"debrief":"Kind words and respect in public are part of everyday dignity."},
  {"id":"rh-1121","cat":"respect-daily","type":"strike-rewrite","persona":"Reshma","source":"who decides","relearn":"Both partners' decisions count; earning more doesn't buy the only say.","hook":"\"Whoever earns the money should make all the decisions.\"","myth":{"un":"Whoever earns the money makes all the decisions.","re":"Both partners get an equal voice in decisions; earning more doesn't buy the only say.","why":"A home is shared, so its choices are shared too."}},
  {"id":"rh-1122","cat":"respect-daily","type":"strike-rewrite","persona":"any","source":"whose job","relearn":"Home work is shared; owning it together is respect, not 'helping'.","hook":"\"Housework is the woman's job, and a man just 'helps out'.\"","myth":{"un":"Housework is the woman's job; a man only 'helps out'.","re":"Running a home is shared work; owning tasks together is respect, not 'helping' on request.","why":"A household belongs to everyone who lives in it."}},
  {"id":"rh-1123","cat":"respect-daily","type":"strike-rewrite","persona":"any","source":"real peace","relearn":"Respectful disagreement is healthy; silence isn't real peace.","hook":"\"A good partner never disagrees and keeps the peace at any cost.\"","myth":{"un":"A good partner never disagrees and keeps the peace at any cost.","re":"Disagreeing with respect is healthy; peace built on one person's silence isn't real peace.","why":"Two minds will differ; respect is how they meet."}},
  {"id":"rh-1124","cat":"respect-daily","type":"strike-rewrite","persona":"any","source":"keep yourself","relearn":"You keep your own time, choices and dignity inside a marriage.","hook":"\"Once you marry, your time and choices belong to your spouse.\"","myth":{"un":"Once you marry, your time and choices belong to your spouse.","re":"You keep your own time, choices and dignity in a marriage; partnership doesn't hand them over.","why":"A wedding joins two lives; it doesn't erase one."}},
  {"id":"rh-1125","cat":"respect-daily","type":"strike-rewrite","persona":"any","source":"two voices","relearn":"A respectful home runs on two equal voices, not one final word.","hook":"\"The man is the head of the house, so his word is final.\"","myth":{"un":"The man is the head of the house, so his word is final.","re":"A respectful home runs on two voices, not one final word; equality isn't weakness.","why":"Leadership at home means sharing, not ruling."}},
  {"id":"rh-1126","cat":"respect-daily","type":"strike-rewrite","persona":"any","source":"not selfish","relearn":"Keeping your own goals isn't selfish; 'us' shouldn't erase 'me'.","hook":"\"Caring about your own goals after marriage is selfish.\"","myth":{"un":"Caring about your own goals after marriage is selfish.","re":"Keeping your own goals is healthy; a partnership builds 'us' without erasing either 'me'.","why":"Two whole people make a stronger team."}},
  {"id":"rh-1127","cat":"respect-daily","type":"strike-rewrite","persona":"any","source":"invisible work","relearn":"The mental load is real work; sharing it is part of respect.","hook":"\"Doing the remembering and planning isn't really work.\"","myth":{"un":"Doing the remembering and planning isn't really work.","re":"The mental load of running a home is real labour; noticing and sharing it is respect.","why":"Invisible work is still work."}},
  {"id":"rh-1128","cat":"respect-daily","type":"role-play","persona":"any","source":"mental load","relearn":"Ask to share the mental load openly, as a team.","hook":"You want to ask your partner to truly share the home's mental load.","setup":"Name it as a team. Say:","yourLine":[{"text":"\"Let's split who tracks what at home, so it isn't all in one head.\"","best":true},{"text":"Keep carrying it all and hope they notice"}]},
  {"id":"rh-1129","cat":"respect-daily","type":"role-play","persona":"Reshma","source":"money say","relearn":"Ask for an equal say in money, calmly and clearly.","hook":"Money decisions keep being made without you, and you want an equal say.","setup":"Ask plainly and calmly. Say:","yourLine":[{"text":"\"I'd like us to see the accounts together and decide big spends as a pair.\"","best":true},{"text":"Say nothing and accept being left out"}]},
  {"id":"rh-1130","cat":"respect-daily","type":"role-play","persona":"any","source":"fair conflict","relearn":"Keep a disagreement respectful by slowing down and listening.","hook":"A disagreement is heating up and you want to keep it respectful.","setup":"Slow it down. Say:","yourLine":[{"text":"\"I want to hear your side too, can we take this calmly?\"","best":true},{"text":"Raise your voice until they back down"}]},
  {"id":"rh-1131","cat":"respect-daily","type":"role-play","persona":"any","source":"shared plans","relearn":"Ask to be consulted on plans that affect you both.","hook":"Your partner keeps making plans for you without asking. You want a say.","setup":"Set it gently but clearly. Say:","yourLine":[{"text":"\"Please check with me first, plans that affect us should be ours to make.\"","best":true},{"text":"Go along with whatever they decide"}]},
  {"id":"rh-1132","cat":"respect-daily","type":"role-play","persona":"any","source":"keeping ties","relearn":"Keep your own friendships and ask your partner to welcome them.","hook":"You want to protect your own friendships without it becoming a fight.","setup":"Be warm and firm. Say:","yourLine":[{"text":"\"My friends matter to me, and I'd love you to be glad I have them.\"","best":true},{"text":"Quietly let the friendships fade"}]},
  {"id":"rh-1133","cat":"respect-daily","type":"role-play","persona":"Reshma","source":"valuing work","relearn":"Name homemaking as real work that deserves respect.","hook":"Your homemaking is being dismissed as 'not real work' and you want it valued.","setup":"Name your worth plainly. Say:","yourLine":[{"text":"\"Running this home is real work, and I'd like it respected as that.\"","best":true},{"text":"Accept that what you do doesn't count"}]},
  {"id":"rh-1134","cat":"respect-daily","type":"role-play","persona":"any","source":"equal voice","relearn":"Set an equal-voice promise from the start.","hook":"You want to start married life with a shared promise of equal voice.","setup":"Make the promise together. Say:","yourLine":[{"text":"\"Let's promise to decide the big things as equals, both voices counting.\"","best":true},{"text":"Assume one of you will just lead"}]},
  {"id":"rh-1135","cat":"respect-daily","type":"match","persona":"any","source":"habits to traits","relearn":"Shared money, shared load, respectful conflict, independence and appreciation each show respect.","hook":"Match each home habit to what it shows.","pairs":[{"left":"Deciding big spends together","right":"An equal say in money"},{"left":"Both noticing what the home needs","right":"A shared mental load"},{"left":"Listening when you disagree","right":"Respectful conflict"},{"left":"Keeping your own friends","right":"Healthy independence"},{"left":"Thanking each other's effort","right":"Daily appreciation"}]},
  {"id":"rh-1136","cat":"respect-daily","type":"match","persona":"any","source":"respect vs its opposite","relearn":"Each respectful habit replaces a one-sided one: sharing, equal say, calm talk, ties and joint choices.","hook":"Match the respectful move to the unhealthy one it replaces.","pairs":[{"left":"Sharing chores as a team","right":"'Helping' only when asked"},{"left":"An equal say in money","right":"Controlling all the money"},{"left":"Calm disagreement","right":"The silent treatment"},{"left":"Welcoming your friends","right":"Cutting you off from them"},{"left":"Deciding together","right":"One person's final word"}]},
  {"id":"rh-1137","cat":"respect-daily","type":"match","persona":"any","source":"reading the words","relearn":"Words reveal respect or control: an equal voice and appreciation, or belittling and one-sided control.","hook":"Match the partner's line to what it really signals.","pairs":[{"left":"\"Let's decide this together\"","right":"An equal voice"},{"left":"\"What you do isn't real work\"","right":"Belittling"},{"left":"\"Tell me what's upsetting you\"","right":"Making room for feelings"},{"left":"\"I'm the only one who decides\"","right":"One-sided control"},{"left":"\"Thank you for handling that\"","right":"Appreciation"}]},
  {"id":"rh-1138","cat":"respect-daily","type":"match","persona":"any","source":"areas of fairness","relearn":"Fairness covers planning, money, rest, independence and parenting alike.","hook":"Match each form of fairness to the part of home life it covers.","pairs":[{"left":"Shared mental load","right":"Planning and remembering"},{"left":"Equal say","right":"Money and big decisions"},{"left":"Shared rest","right":"Downtime and tiredness"},{"left":"Kept independence","right":"Friends, family and goals"},{"left":"Co-parenting","right":"Raising the children"}]},
  {"id":"rh-1139","cat":"respect-daily","type":"match","persona":"any","source":"values to practice","relearn":"Respect, equal voice, autonomy, a fair load and safe disagreement each have a daily practice.","hook":"Match the value to a one-line way to live it at home.","pairs":[{"left":"Mutual respect","right":"Speak kindly even when cross"},{"left":"Equal voice","right":"Decide the big things together"},{"left":"Autonomy kept","right":"No permission needed for your own life"},{"left":"Fair load","right":"Both notice and do the work"},{"left":"Safe disagreement","right":"Differ without fear"}]},
  {"id":"rh-1140","cat":"respect-daily","type":"match","persona":"any","source":"what staying whole protects","relearn":"Keeping your goals, friends, money, voice and rest protects who you are inside a partnership.","hook":"Match each 'us without erasing me' truth to what it protects.","pairs":[{"left":"You keep your goals","right":"Your sense of self"},{"left":"You keep your friends","right":"Your support network"},{"left":"You keep some money","right":"Your footing"},{"left":"You keep your voice","right":"Your say in decisions"},{"left":"You keep your rest","right":"Your health"}]},
  {"id":"rh-1141","cat":"respect-daily","type":"match","persona":"Razia","source":"even-handed truths","relearn":"Mutual respect is even-handed: owed to and by partners of any gender.","hook":"Match the even-handed truth to who it applies to.","pairs":[{"left":"Respect is owed both ways","right":"Both partners"},{"left":"Either can ask for change","right":"Each of them"},{"left":"Anyone can be belittled","right":"Any gender"},{"left":"Both deserve rest","right":"Each partner"},{"left":"Both voices count","right":"The whole couple"}]},
  {"id":"rh-1142","cat":"respect-daily","type":"spot","persona":"any","source":"control vs equal voice","relearn":"An equal voice means sharing money and decisions, not controlling them.","hook":"Spot the two lines that show one-sided control, not partnership.","scene":[{"id":"a","text":"\"Let's plan the budget together\"","trick":false},{"id":"b","text":"\"I decide the money, you don't need to know\"","trick":true},{"id":"c","text":"\"What do you think we should do?\"","trick":false},{"id":"d","text":"\"Ask me before you spend a rupee\"","trick":true},{"id":"e","text":"\"Your opinion matters here\"","trick":false}],"why":"Deciding money alone and demanding permission to spend are one-sided control, not an equal voice."},
  {"id":"rh-1143","cat":"respect-daily","type":"spot","persona":"any","source":"mental load red flags","relearn":"Sharing the mental load is respect; making one person carry it isn't.","hook":"Spot the two moves that dump the home's load on one person.","scene":[{"id":"a","text":"Both notice when the milk runs out","trick":false},{"id":"b","text":"\"Remembering everything is your job\"","trick":true},{"id":"c","text":"They cook some nights without being asked","trick":false},{"id":"d","text":"\"I'll help if you make a list for me\"","trick":true},{"id":"e","text":"You plan the week together","trick":false}],"why":"Making one person remember it all, and only 'helping' off a list, dumps the mental load on them."},
  {"id":"rh-1144","cat":"respect-daily","type":"spot","persona":"any","source":"silencing red flags","relearn":"Respectful disagreement listens; silencing and threats don't.","hook":"Spot the two responses that silence a disagreement instead of handling it.","scene":[{"id":"a","text":"\"Tell me your side, I'm listening\"","trick":false},{"id":"b","text":"Days of silent treatment after a 'no'","trick":true},{"id":"c","text":"\"Let's find a middle path\"","trick":false},{"id":"d","text":"\"You'll regret arguing with me\"","trick":true},{"id":"e","text":"\"We can disagree and still be okay\"","trick":false}],"why":"Silent treatment and threats shut down a disagreement; listening and finding middle ground handle it."},
  {"id":"rh-1145","cat":"respect-daily","type":"spot","persona":"any","source":"erasing-me red flags","relearn":"Partnership builds 'us' without erasing 'me'.","hook":"Spot the two lines that erase your own life, not just join two lives.","scene":[{"id":"a","text":"\"I'm glad you still see your friends\"","trick":false},{"id":"b","text":"\"You don't need anyone but me\"","trick":true},{"id":"c","text":"\"Keep chasing your own goals\"","trick":false},{"id":"d","text":"\"Drop all that now that we're married\"","trick":true},{"id":"e","text":"\"Your family is welcome here\"","trick":false}],"why":"Cutting you off from people and telling you to drop your own life erase 'me'; the others keep it."},
  {"id":"rh-1146","cat":"respect-daily","type":"spot","persona":"any","source":"belittling red flags","relearn":"Valuing a partner's work is respect; belittling it isn't.","hook":"Spot the two phrases that belittle a partner's work.","scene":[{"id":"a","text":"\"I'm proud of what you do\"","trick":false},{"id":"b","text":"\"What you do isn't real work\"","trick":true},{"id":"c","text":"\"Your homemaking holds us together\"","trick":false},{"id":"d","text":"\"You'd be nothing without me\"","trick":true},{"id":"e","text":"\"How was your day at work?\"","trick":false}],"why":"'Not real work' and 'nothing without me' belittle; pride and interest value the work instead."},
  {"id":"rh-1147","cat":"respect-daily","type":"spot","persona":"any","source":"parent-child red flags","relearn":"Partners meet as two adults, not parent and child.","hook":"Spot the two moves that treat a partner like a child to manage.","scene":[{"id":"a","text":"\"Let's sort this out as equals\"","trick":false},{"id":"b","text":"Setting a 'curfew' for a grown adult","trick":true},{"id":"c","text":"Trusting you with your own time","trick":false},{"id":"d","text":"\"I'll give you permission this once\"","trick":true},{"id":"e","text":"Talking mistakes through, not punishing","trick":false}],"why":"A curfew and giving 'permission' treat an adult as a child; equals trust and talk things through."},
  {"id":"rh-1148","cat":"respect-daily","type":"spot","persona":"any","source":"dignity red flags","relearn":"Kind words and respect protect everyday dignity.","hook":"Spot the two lines that chip at a partner's everyday dignity.","scene":[{"id":"a","text":"\"I felt hurt, can we talk?\"","trick":false},{"id":"b","text":"Mocking you in front of guests","trick":true},{"id":"c","text":"\"Take the space you need\"","trick":false},{"id":"d","text":"\"You're useless, as always\"","trick":true},{"id":"e","text":"\"Thank you for sorting that\"","trick":false}],"why":"Public mockery and name-calling chip at dignity; honest talk and thanks protect it."},
  {"id":"rh-1149","cat":"respect-daily","type":"spot","persona":"Reshma","source":"money control red flags","relearn":"An equal say in money is respect; controlling it isn't.","hook":"Spot the two ways money gets used to control, not shared fairly.","scene":[{"id":"a","text":"Both can see the bank balance","trick":false},{"id":"b","text":"Earnings vanish into one account","trick":true},{"id":"c","text":"Big spends are agreed together","trick":false},{"id":"d","text":"You must beg for everyday money","trick":true},{"id":"e","text":"You each keep a little of your own","trick":false}],"why":"Taking all the earnings and making you beg are control; shared visibility and joint spending are fair."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1170","hook":"A neighbour confides her husband hits her and begs you not to tell anyone.","persona":"any","source":"a neighbour discloses","options":[{"text":"Believe her, stay close, and share routes (181, a trusted person) when she's ready","consequence":"She feels believed and knows help exists.","outcome":"believed","best":true},{"text":"Tell her she must leave him today or you can't help","consequence":"Whether and when to leave is her choice; pushing it can raise her danger."}],"debrief":"Believe first, stay close, offer routes (181, a trusted person): her pace, her choice.","relearn":"Believe a survivor and share routes (181); leaving is her choice, never your push."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1171","hook":"You finally name to yourself that what's happening at home is abuse, and feel ashamed.","persona":"any","source":"naming it for yourself","options":[{"text":"Treat naming it as a brave first step and reach one trusted person","consequence":"Recognising it is strength, and you're no longer alone with it.","outcome":"named","best":true},{"text":"Push it away because you feel it's your shame to carry","consequence":"Shame belongs to the abuser, not you; naming it is the first step, not a weakness."}],"debrief":"Naming abuse is a brave first step; the shame is the abuser's.","relearn":"Naming abuse is a brave first step; the shame is the abuser's, and help is reachable."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1172","hook":"Things feel tense and you sense danger may be rising; you want to be ready.","persona":"any","source":"sensing rising risk","options":[{"text":"Quietly set up a safe place to go and a way to call for help","consequence":"You have a careful plan if you ever need it.","outcome":"ready","best":true},{"text":"Confront them head-on to clear the air","consequence":"Risk can rise when abuse is challenged; a quiet plan is safer than a confrontation."}],"debrief":"When risk feels like it's rising, a quiet plan, like a safe place or a way to call help, is wise.","relearn":"Sensing rising danger? Quietly plan a safe place and a way to call for help."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1173","hook":"Lensy: you're helping a friend who's being abused, and you want to do it right.","persona":"Saxena","source":"supporting, not taking over","options":[{"text":"Ask what they need and follow their pace, without taking over","consequence":"They stay in control of their choices, which keeps them safer.","outcome":"led-by-them","best":true},{"text":"Take charge and arrange everything for them","consequence":"Taking over removes a survivor's control; ask what they need and respect their pace."}],"debrief":"Believe, ask what they need, respect their pace, don't take over.","relearn":"Support a survivor by asking what they need and respecting their pace. Don't take over."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1174","hook":"You want to keep proof of what's happening but worry the abuser might find it.","persona":"any","source":"a safe record","options":[{"text":"Keep a dated record somewhere only you can reach, like a trusted friend's phone","consequence":"Your evidence stays safe, out of the abuser's reach.","outcome":"recorded","best":true},{"text":"Keep the notes openly on the shared family phone","consequence":"A shared phone isn't safe; keep a record where only you or a trusted person can reach it."}],"debrief":"A dated record kept where only you or a trusted person can reach is safe and useful.","relearn":"Keep a dated record somewhere only you or a trusted person can reach."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1175","hook":"You share one family phone with permission and have no privacy to call for help.","persona":"Reshma","source":"no private phone","options":[{"text":"Reach a trusted relative, neighbour or health worker in private to help you call","consequence":"You find a safe, private way to reach help.","outcome":"reached","best":true},{"text":"Decide help is impossible without your own phone","consequence":"A trusted person can help you reach 181 or 1091; no private phone doesn't mean no help."}],"debrief":"No private phone? A trusted person can help you reach 181 safely.","relearn":"No private phone? Reach a trusted person who can help you call 181 or 1091 safely."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1176","hook":"A man says his wife controls his money and humiliates him, fearing no one will believe him.","persona":"any","source":"a male survivor","options":[{"text":"Believe him and tell him help is for him too: a trusted person, 181, 112","consequence":"He feels believed and learns support is real for him.","outcome":"believed","best":true},{"text":"Laugh it off; men can handle their own homes","consequence":"Anyone of any gender can be a victim; believe him and point him to help."}],"debrief":"Anyone of any gender can be abused; a male survivor is believed equally.","relearn":"Anyone of any gender can be a victim; believe him, and help (181, 112) is his too."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1177","hook":"A fight at home is turning physical right now and you're frightened for your safety.","persona":"any","source":"immediate danger","options":[{"text":"Get to a safer room or outside and call 112 for emergency help","consequence":"You reach emergency help while moving toward safety.","outcome":"safe","best":true},{"text":"Stay and try to calm them down to avoid making it worse","consequence":"In immediate danger your safety comes first; move to a safer place and call 112."}],"debrief":"In immediate danger, get to a safer place and call 112; your safety comes first.","relearn":"In immediate danger, get to safety and call 112: your safety comes first."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1178","hook":"Lensy: a woman asks Razia whether the law can actually help her stay safe and housed.","persona":"Razia","source":"the law as a route","options":[{"text":"Explain that protection and residence orders exist, as her choices","consequence":"She learns real routes exist, without being pushed into any.","outcome":"informed","best":true},{"text":"Tell her the law never helps women like her","consequence":"Protection, residence and maintenance orders are real routes worth knowing."}],"debrief":"The DV Act 2005 offers protection, residence and maintenance orders: her choice.","relearn":"The DV Act 2005 offers protection, residence and maintenance orders: real routes."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1179","hook":"You want a way to signal a trusted person if you're ever in danger and can't speak freely.","persona":"any","source":"a code word","options":[{"text":"Agree a simple code word that means 'call and check on me or send help'","consequence":"You have a quiet signal that brings help fast.","outcome":"signalled","best":true},{"text":"Plan to explain the whole situation in the moment instead","consequence":"In a crisis there may be no time; a pre-agreed code word brings help faster."}],"debrief":"A code word with a trusted person is a quiet, fast way to call for help.","relearn":"Agree a code word with a trusted person so they can act if you're ever in danger."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1180","hook":"You think you need legal help but believe you could never afford a lawyer.","persona":"any","source":"free legal aid","options":[{"text":"Reach NALSA free legal aid (15100), which is for people who can't pay","consequence":"You learn free legal help is genuinely available to you.","outcome":"aided","best":true},{"text":"Give up on legal help because of the cost","consequence":"NALSA free legal aid (15100) exists exactly for those who can't pay; cost needn't stop you."}],"debrief":"NALSA free legal aid (15100) is for those who can't pay; cost shouldn't block help.","relearn":"NALSA free legal aid (15100) is free for those who can't pay; cost needn't block help."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1181","hook":"A friend in an abusive marriage tells you she isn't ready to leave yet.","persona":"any","source":"not ready to leave","options":[{"text":"Respect her choice, stay supportive, keep routes open for when she's ready","consequence":"She keeps your support and a path to help on her own timeline.","outcome":"supported","best":true},{"text":"Tell her you're done helping until she leaves","consequence":"Whether and when to leave is hers; staying supportive keeps her safer than withdrawing."}],"debrief":"Whether and when to leave is hers; staying supportive keeps help's door open.","relearn":"Not ready to leave is a valid choice; stay supportive and keep help routes open."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1182","hook":"You worry your children are being affected by the abuse at home.","persona":"any","source":"children affected","options":[{"text":"Include the children in your safety plan and reach a trusted person or 181","consequence":"You take a careful step toward safety for you and them.","outcome":"protected","best":true},{"text":"Assume the children are too young to be affected","consequence":"Children feel the tension; including them in a safety plan and reaching 181 helps."}],"debrief":"Children feel the abuse too; a safety plan that includes them, plus 181, helps.","relearn":"Include children in your safety plan and reach a trusted person or 181 for support."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1183","hook":"You want to be able to leave quickly and safely if you ever decide to.","persona":"any","source":"documents ready","options":[{"text":"Keep key documents and a little money ready somewhere safe","consequence":"You could leave quickly and safely if you ever choose to.","outcome":"ready","best":true},{"text":"Assume you can gather everything in the moment","consequence":"In a crisis there's rarely time; key documents kept ready let you leave quickly."}],"debrief":"Key documents and a little money kept ready, somewhere safe, let you leave quickly if you choose.","relearn":"Keep key documents and a little money ready somewhere safe, in case you choose to leave."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1184","hook":"You're scared that if you call a helpline they'll judge you or not believe you.","persona":"any","source":"fear of not being believed","options":[{"text":"Call 181 anyway; helplines are there to believe and help, not to judge","consequence":"You reach people whose job is to support you.","outcome":"reached","best":true},{"text":"Stay silent to avoid the risk of being judged","consequence":"181 is there to believe and support you; staying silent leaves you alone with it."}],"debrief":"Helplines like 181 exist to believe and support you, not to judge; you don't need proof to call.","relearn":"Helplines (181) are there to believe and support you. You don't need proof to call."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1185","hook":"You're cut off from your own family and the only people around belong to the abuser.","persona":"Reshma","source":"isolated","options":[{"text":"Quietly rebuild one safe link: a neighbour, a health worker, or 181","consequence":"You open a small, safe channel to help.","outcome":"linked","best":true},{"text":"Accept that you have no one and can't reach help","consequence":"Even isolated, one safe link, like a neighbour, a health worker, or 181, reaches help."}],"debrief":"Isolation is a tool of control; one safe link, or 181, reopens the door to help.","relearn":"Even when isolated, one safe link, like a neighbour, a health worker, or 181, reaches help."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1186","hook":"You've decided to call for help but freeze, not knowing what to say.","persona":"any","source":"making the first call","options":[{"text":"Say simply 'I'm being hurt at home and I need help', and let them guide you","consequence":"That short sentence is enough to start; they take it from there.","outcome":"started","best":true},{"text":"Hang up because you can't find the perfect words","consequence":"A simple 'I'm being hurt and need help' is enough; you don't need perfect words."}],"debrief":"A simple 'I'm being hurt and I need help' is enough; the helpline guides you.","relearn":"You don't need perfect words: 'I'm being hurt and I need help' is enough to start."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1187","hook":"You have no money of your own and feel that traps you with no way to ever get help.","persona":"Reshma","source":"building footing","options":[{"text":"Start a tiny, hidden saving and learn the free routes (181, legal aid)","consequence":"You build a small footing and a path to help.","outcome":"footing","best":true},{"text":"Conclude that without money there's no help","consequence":"Free routes (181, NALSA legal aid) cost nothing; a tiny saving builds footing over time."}],"debrief":"A tiny saving plus free routes (181, legal aid) build footing over time.","relearn":"Free routes (181, NALSA legal aid) cost nothing; a tiny quiet saving builds footing over time."},
  {"cat":"safety-and-help","type":"branch","id":"rh-1188","hook":"You're worried for a relative and feel like dragging her to the police yourself.","persona":"any","source":"respecting her pace","options":[{"text":"Slow down, ask what she wants, and offer routes without forcing any","consequence":"She stays in charge of her own safety and trusts you with it.","outcome":"trusted","best":true},{"text":"Take her to file a complaint whether she wants to or not","consequence":"Acting against her choice can raise danger and break trust; ask and offer routes."}],"debrief":"A survivor knows her own danger best; ask what she wants, offer routes, never force.","relearn":"A survivor knows her own danger best; offer routes, never force."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1189","persona":"any","source":"believe first","hook":"Lensy: when someone shares that they're being hurt at home, believing them comes first. True?","prompt":"What do you think?","options":["Yes","Believe first","No assessment needed"],"affirm":"Believing a survivor first, before any questions, is what helps; they're the expert on their danger.","relearn":"When someone discloses abuse, believe them first; they're the expert on their own danger."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1190","persona":"any","source":"it's not private","hook":"Lensy: 'it happens at home' is never a reason that help shouldn't reach you. Agree?","prompt":"What do you think?","options":["Yes","Help still reaches","Not a shield"],"affirm":"'It's private' is no shield; abuse isn't a family secret, and help is real and reachable.","relearn":"'It happens at home' is no shield; help is real and reachable for abuse."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1191","persona":"any","source":"reaching out is strength","hook":"Lensy: reaching out for help with abuse is a sign of strength, not weakness. Does that land?","prompt":"What do you think?","options":["Yes","It's strength","Brave step"],"affirm":"Reaching out is strength; naming abuse and seeking help is a brave step, never a weakness.","relearn":"Reaching out for help with abuse is strength, not weakness."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1192","persona":"any","source":"survivor's pace","hook":"Lensy: a survivor sets the pace of their own choices, and that deserves respect. Right?","prompt":"What do you think?","options":["Yes","Their pace","Respect it"],"affirm":"A survivor sets the pace; respecting it, not rushing or taking over, keeps them safer and in control.","relearn":"A survivor sets the pace of their choices; respect it, don't rush or take over."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1193","persona":"any","source":"help for any gender","hook":"Lensy: help is for survivors of any gender, equally. Does that feel true to you?","prompt":"What do you think?","options":["Yes","Any gender","Believed equally"],"affirm":"Help is for survivors of any gender; men and others are believed and supported equally.","relearn":"Help is for survivors of any gender; everyone is believed and supported equally."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1194","persona":"Saxena","source":"ask, don't take over","hook":"Lensy: the kindest help asks 'what do you need?' instead of deciding for someone. Agree?","prompt":"What do you think?","options":["Yes","Ask what they need","Don't take over"],"affirm":"Asking 'what do you need?' keeps a survivor in control; the best help supports without taking over.","relearn":"The kindest help asks 'what do you need?' and supports without taking over."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1195","persona":"any","source":"no proof needed","hook":"Lensy: you don't need proof or perfect words to deserve help. Does that reassure you?","prompt":"What do you think?","options":["Yes","No proof needed","Deserve help"],"affirm":"You don't need proof or perfect words; from the first call, you deserve to be believed and helped.","relearn":"You don't need proof or perfect words to deserve help."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1196","persona":"any","source":"a plan is care","hook":"Lensy: making a quiet safety plan is an act of care for yourself, not paranoia. True?","prompt":"What do you think?","options":["Yes","It's care","Not paranoia"],"affirm":"A quiet safety plan, like a safe place, documents, or a code word, is care for yourself, never paranoia.","relearn":"A quiet safety plan is an act of self-care, not paranoia."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1197","persona":"any","source":"one trusted person","hook":"Lensy: even one trusted person you can reach can change everything. Does that ring true?","prompt":"What do you think?","options":["Yes","One person matters","Changes things"],"affirm":"One trusted person you can reach breaks the isolation; you don't have to carry this alone.","relearn":"Even one trusted person you can reach breaks isolation; you're not alone."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1198","persona":"Reshma","source":"help despite barriers","hook":"Lensy: little money or privacy doesn't put help out of reach. Can you believe that?","prompt":"What do you think?","options":["Yes","Still reachable","Free routes exist"],"affirm":"Little money or privacy doesn't put help out of reach; free, discreet routes (181) still exist for you.","relearn":"Little money or privacy doesn't put help out of reach; free, discreet routes exist."},
  {"cat":"safety-and-help","type":"reflect","id":"rh-1199","persona":"any","source":"your safety first","hook":"Lensy: in a moment of danger, your safety comes before anything else. Clear?","prompt":"What do you think?","options":["Yes","Safety first","Then call 112"],"affirm":"In danger, your safety comes first; get to a safer place, then call 112. Nothing matters more.","relearn":"In a moment of danger, your safety comes first; get safe, then call 112."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1200","persona":"any","source":"safety-plan or not","hook":"Sort: part of a careful safety plan, or not?","items":[{"id":"a","text":"A safe place you can go"},{"id":"b","text":"Key documents kept ready"},{"id":"c","text":"A code word with a trusted person"},{"id":"d","text":"Confronting them when they're angry"},{"id":"e","text":"Hoping it just stops on its own"},{"id":"f","text":"Telling no one at all"}],"bins":[{"id":"plan","label":"Safety plan","valence":"pos"},{"id":"not","label":"Not a plan","valence":"neg"}],"key":{"a":"plan","b":"plan","c":"plan","d":"not","e":"not","f":"not"},"relearn":"A safe place, ready documents and a code word are a safety plan; confronting, hoping or hiding aren't."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1201","persona":"any","source":"who to reach","hook":"Sort: a real route to help, or not?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"A trusted person"},{"id":"c","text":"NALSA free legal aid"},{"id":"d","text":"Asking the abuser to stop"},{"id":"e","text":"Waiting for it to pass"},{"id":"f","text":"Hiding it forever"}],"bins":[{"id":"route","label":"Real route","valence":"pos"},{"id":"noroute","label":"Not a route","valence":"neg"}],"key":{"a":"route","b":"route","c":"route","d":"noroute","e":"noroute","f":"noroute"},"relearn":"181, a trusted person and NALSA legal aid are real routes; asking the abuser, waiting or hiding aren't."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1202","persona":"any","source":"believe or blame","hook":"Sort: what a survivor needs to hear, or what they don't.","items":[{"id":"a","text":"'I believe you'"},{"id":"b","text":"'It's not your fault'"},{"id":"c","text":"'I'm here. What do you need?'"},{"id":"d","text":"'What did you do to set them off?'"},{"id":"e","text":"'Just keep the peace at home'"},{"id":"f","text":"'You should have left long ago'"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"helps","d":"harms","e":"harms","f":"harms"},"relearn":"'I believe you', 'not your fault' and 'what do you need?' help; blame, 'keep the peace' and 'should have left' harm."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1203","persona":"Razia","source":"match need to route","hook":"Sort: handle it yourself, or reach real help?","items":[{"id":"a","text":"In immediate danger right now"},{"id":"b","text":"You need a protection order"},{"id":"c","text":"You want free legal advice"},{"id":"d","text":"You feel you must cope alone"},{"id":"e","text":"You decide it's too private to tell"},{"id":"f","text":"You wait until it's 'bad enough'"}],"bins":[{"id":"reach","label":"Reach help","valence":"pos"},{"id":"stuck","label":"Stays stuck","valence":"neg"}],"key":{"a":"reach","b":"reach","c":"reach","d":"stuck","e":"stuck","f":"stuck"},"relearn":"Danger, a protection order or legal advice all have real routes; coping alone, silence or waiting keep you stuck."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1204","persona":"any","source":"speak up cue","hook":"Sort: a 'reach for help now' sign, or a steadying truth?","items":[{"id":"a","text":"You feel unsafe at home"},{"id":"b","text":"The fear is rising before they leave"},{"id":"c","text":"A friend discloses they're being hurt"},{"id":"d","text":"Abuse is never the victim's fault"},{"id":"e","text":"Help exists for any gender"},{"id":"f","text":"Reaching out is strength"}],"bins":[{"id":"act","label":"Reach for help","valence":"tell"},{"id":"truth","label":"Steadying truth","valence":"pos"}],"key":{"a":"act","b":"act","c":"act","d":"truth","e":"truth","f":"truth"},"relearn":"Feeling unsafe, rising fear or a disclosure mean reach for help; the rest are steadying truths to hold onto."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1205","persona":"any","source":"safe or risky way to keep proof","hook":"Sort: a safe way to keep a record, or a risky one?","items":[{"id":"a","text":"Notes kept on a trusted friend's phone"},{"id":"b","text":"A dated log only you can reach"},{"id":"c","text":"Copies left with a trusted person"},{"id":"d","text":"A diary the abuser could find"},{"id":"e","text":"Notes on the shared family phone"},{"id":"f","text":"Telling the abuser you're recording it"}],"bins":[{"id":"safe","label":"Kept safely","valence":"pos"},{"id":"risky","label":"Risky","valence":"uhoh"}],"key":{"a":"safe","b":"safe","c":"safe","d":"risky","e":"risky","f":"risky"},"relearn":"A record kept where only you or a trusted person can reach is safe; a shared phone or visible diary is risky."},
  {"cat":"safety-and-help","type":"sort","id":"rh-1206","persona":"Reshma","source":"discreet or exposed","hook":"Sort: a discreet way to reach help, or one that could be seen?","items":[{"id":"a","text":"Speaking to a health worker in private"},{"id":"b","text":"A quiet word with a trusted neighbour"},{"id":"c","text":"Calling 181 when you're alone"},{"id":"d","text":"Searching loudly on the shared phone"},{"id":"e","text":"Telling the abuser's relatives first"},{"id":"f","text":"Announcing your plan at home"}],"bins":[{"id":"discreet","label":"Discreet","valence":"pos"},{"id":"exposed","label":"Could be seen","valence":"uhoh"}],"key":{"a":"discreet","b":"discreet","c":"discreet","d":"exposed","e":"exposed","f":"exposed"},"relearn":"A private word with a health worker, neighbour or 181 is discreet; the shared phone or the abuser's kin can expose you."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1207","persona":"any","source":"asking a friend to be your contact","hook":"You want a trusted friend to be your emergency contact.","setup":"Ask them plainly. Say:","yourLine":[{"text":"\"Can you be the person I call if I'm ever in danger at home? I may need you fast.\"","best":true},{"text":"Say nothing, in case asking makes it awkward"}],"relearn":"Ask a trusted friend to be your emergency contact, so they can act fast if you're in danger."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1208","persona":"any","source":"telling a counsellor","hook":"You're sitting with a counsellor and want to name what's happening.","setup":"You can keep it simple. Say:","yourLine":[{"text":"\"I'm being controlled and hurt at home, and I want help to understand my options.\"","best":true},{"text":"Talk about everything except the abuse"}],"relearn":"Naming 'I'm being hurt at home and I want help' to a counsellor is enough to start getting support."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1209","persona":"Saxena","source":"what to say to a survivor","hook":"A friend has just told you they're being abused at home.","setup":"The first words matter. Say:","yourLine":[{"text":"\"I believe you. This isn't your fault. I'm here. What do you need?\"","best":true},{"text":"\"Are you sure? What did you do to upset them?\""}],"relearn":"To a survivor, say 'I believe you, it's not your fault, I'm here': believe first, never interrogate."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1210","persona":"any","source":"calling 181","hook":"You've decided to call the Women Helpline and you're nervous.","setup":"Once they answer, you can say:","yourLine":[{"text":"\"I'm being hurt at home and I need help and to know what I can do.\"","best":true},{"text":"Apologise and say it's probably nothing"}],"relearn":"On 181, 'I'm being hurt at home and I need help' is enough; they guide you from there."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1211","persona":"any","source":"asking to keep your papers","hook":"You want to ask a trusted relative to safely hold copies of your documents.","setup":"Ask quietly. Say:","yourLine":[{"text":"\"Could you keep copies of my important papers safe for me, just in case?\"","best":true},{"text":"Decide it's safer to ask no one and risk nothing"}],"relearn":"Ask a trusted person to safely hold copies of your key documents, so you can leave fast if you choose."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1212","persona":"Reshma","source":"a quiet word with a neighbour","hook":"A kind neighbour asks gently if everything is alright at home.","setup":"You can open the door a little. Say:","yourLine":[{"text":"\"Things aren't okay at home. Could I talk to you when no one's around?\"","best":true},{"text":"\"Everything's fine,\" and change the subject"}],"relearn":"A quiet 'things aren't okay, can we talk in private?' to a trusted neighbour is a safe first step."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1213","persona":"any","source":"male survivor speaking up","hook":"You're a man being abused at home, telling a friend for the first time.","setup":"You deserve to be heard. Say:","yourLine":[{"text":"\"I'm being abused at home. I know it's hard to picture, but I need support.\"","best":true},{"text":"Make a joke about it so it doesn't sound serious"}],"relearn":"A man can say 'I'm being abused and I need support' and be believed; help is for any gender."},
  {"cat":"safety-and-help","type":"role-play","id":"rh-1214","persona":"any","source":"setting up a check-in","hook":"You want a trusted person to check on you regularly while things are tense.","setup":"Set it up clearly. Say:","yourLine":[{"text":"\"Please message me each evening; if I don't reply by night, call and check on me.\"","best":true},{"text":"Hope someone notices if something goes wrong"}],"relearn":"Set up a regular check-in with a trusted person, with a plan for what they do if you go quiet."},
  {"cat":"safety-and-help","type":"match","id":"rh-1215","persona":"any","source":"need to route","hook":"Match each need to where help lives (India).","pairs":[{"left":"In danger right now","right":"Emergency 112"},{"left":"Domestic abuse support","right":"Women Helpline 181"},{"left":"A woman in distress","right":"1091"},{"left":"Free legal advice","right":"NALSA legal aid 15100"},{"left":"Someone who knows you","right":"A trusted person"}],"relearn":"112 for danger, 181 for abuse support, 1091 in distress, 15100 for free legal aid, plus a trusted person."},
  {"cat":"safety-and-help","type":"match","id":"rh-1216","persona":"any","source":"safety-plan pieces","hook":"Match each safety-plan piece to what it's for.","pairs":[{"left":"A code word","right":"Signals a trusted person to act"},{"left":"Key documents kept ready","right":"Lets you leave quickly if you choose"},{"left":"A dated record","right":"Supports protection later"},{"left":"A safe place to go","right":"Somewhere to reach in a hurry"},{"left":"A little money set aside","right":"Covers the first steps away"}],"relearn":"A code word, ready documents, a dated record, a safe place and a little money each serve a clear safety purpose."},
  {"cat":"safety-and-help","type":"match","id":"rh-1217","persona":"Razia","source":"DV Act routes","hook":"Match each need to its real route (India).","pairs":[{"left":"Know your rights in depth","right":"Free legal aid (NALSA)"},{"left":"Stop the violence legally","right":"A protection order"},{"left":"Stay in your own home","right":"A residence order"},{"left":"Money to live on","right":"A maintenance order"},{"left":"Reach support any hour","right":"Women Helpline 181"}],"relearn":"Free legal aid, plus protection, residence and maintenance orders under the DV Act 2005, and 181, are real routes."},
  {"cat":"safety-and-help","type":"match","id":"rh-1218","persona":"any","source":"believe vs blame","hook":"Match each thing said to whether it helps or hurts a survivor.","pairs":[{"left":"'I believe you'","right":"Helps them feel safe"},{"left":"'It's not your fault'","right":"Lifts shame off them"},{"left":"'What did you do to provoke it?'","right":"Wrongly blames them"},{"left":"'Just keep the peace'","right":"Pressures them to endure"},{"left":"'What do you need?'","right":"Keeps them in control"}],"relearn":"'I believe you', 'not your fault' and 'what do you need?' help; blame and 'keep the peace' hurt."},
  {"cat":"safety-and-help","type":"match","id":"rh-1219","persona":"any","source":"discreet routes for barriers","hook":"Match each barrier to a discreet way around it.","pairs":[{"left":"No private phone","right":"A trusted person helps you call"},{"left":"No money for a lawyer","right":"NALSA free legal aid"},{"left":"Cut off from your family","right":"A neighbour or health worker"},{"left":"Nowhere obvious to go","right":"A shelter via 181"},{"left":"Fear of not being believed","right":"A helpline trained to believe you"}],"relearn":"No phone, no money, isolation, nowhere to go or fear of disbelief each have a discreet route around them."},
  {"cat":"safety-and-help","type":"match","id":"rh-1220","persona":"any","source":"emergency vs planning","hook":"Match each situation to the right first move.","pairs":[{"left":"Being hurt this minute","right":"Get safe and call 112"},{"left":"Things feel like they're escalating","right":"Make a quiet safety plan"},{"left":"Wanting to know your rights","right":"Reach free legal aid"},{"left":"Needing to talk it through","right":"Call 181 or a counsellor"},{"left":"Worried about a friend","right":"Believe them and offer routes"}],"relearn":"Immediate harm needs 112; escalation needs a plan; rights need legal aid; talking needs 181; a friend needs belief."},
  {"cat":"safety-and-help","type":"match","id":"rh-1221","persona":"Saxena","source":"supporting well","hook":"Match each helper move to why it matters.","pairs":[{"left":"Believe them first","right":"They're the expert on their danger"},{"left":"Ask what they need","right":"Keeps them in control"},{"left":"Respect their pace","right":"Leaving is their choice, not yours"},{"left":"Don't take over","right":"Doing it for them removes their power"},{"left":"Keep the routes open","right":"They can reach help when ready"}],"relearn":"Believe, ask what they need, respect their pace, don't take over, and keep routes open. That's good support."},
  {"cat":"safety-and-help","type":"match","id":"rh-1222","persona":"any","source":"safe vs risky record","hook":"Match each way of keeping a record to whether it's safe or risky.","pairs":[{"left":"Notes on a trusted friend's phone","right":"Safe: out of the abuser's reach"},{"left":"A diary left at home","right":"Risky: could be found"},{"left":"Copies held by a trusted person","right":"Safe: kept off-site"},{"left":"Notes on the shared phone","right":"Risky: can be monitored"},{"left":"Telling the abuser you're recording","right":"Risky: can raise danger"}],"relearn":"A record kept where only you or a trusted person can reach is safe; a home diary or shared phone is risky."},
  {"cat":"safety-and-help","type":"match","id":"rh-1223","persona":"any","source":"who can help","hook":"Match each helper to what they can offer.","pairs":[{"left":"Women Helpline 181","right":"Support and guidance any hour"},{"left":"NALSA (15100)","right":"Free legal aid"},{"left":"A trusted neighbour","right":"A safe place close by"},{"left":"A counsellor","right":"A space to talk it through"},{"left":"Emergency 112","right":"Help in immediate danger"}],"relearn":"181 for support, NALSA (15100) for legal aid, a neighbour for a safe place, a counsellor to talk, 112 in danger."},
  {"cat":"safety-and-help","type":"match","id":"rh-1224","persona":"any","source":"first step by need","hook":"Match each feeling to a gentle first step.","pairs":[{"left":"'I'm scared right now'","right":"Reach a safe place and 112"},{"left":"'I feel completely alone'","right":"Reach one trusted person"},{"left":"'I have no proof'","right":"You don't need proof to call"},{"left":"'I can't afford help'","right":"Free routes exist (181, NALSA)"},{"left":"'Maybe I'm overreacting'","right":"Your sense of danger matters"}],"relearn":"Fear, isolation, having no proof, no money or self-doubt each have a gentle, real first step."},
  {"cat":"safety-and-help","type":"match","id":"rh-1225","persona":"Reshma","source":"barriers to routes","hook":"Match each worry to a route that still works.","pairs":[{"left":"'He controls all the money'","right":"Free legal aid and 181 cost nothing"},{"left":"'I'm watched all the time'","right":"A health worker can help in private"},{"left":"'I have nowhere to go'","right":"A shelter reachable via 181"},{"left":"'My family is far away'","right":"A trusted neighbour close by"},{"left":"'No one would believe me'","right":"Helplines are trained to believe"}],"relearn":"Money control, surveillance, nowhere to go, distance or disbelief each have a route that still works."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1226","persona":"any","source":"spot the unsafe move","hook":"Spot the two moves that make a survivor LESS safe.","scene":[{"id":"a","text":"Confronting the abuser alone when they're angry","trick":true},{"id":"b","text":"Keeping key documents ready in a safe spot","trick":false},{"id":"c","text":"Announcing your exit plan out loud at home","trick":true},{"id":"d","text":"Agreeing a code word with a trusted person","trick":false},{"id":"e","text":"Knowing a safe place you can go","trick":false}],"why":"Confronting them alone and announcing your plan can raise danger; quiet preparation keeps you safer.","relearn":"Confronting an abuser alone or announcing your plan raises danger; quiet preparation is safer."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1227","persona":"any","source":"spot the blaming reply","hook":"Spot the two replies that wrongly blame a survivor.","scene":[{"id":"a","text":"'I believe you, and it's not your fault'","trick":false},{"id":"b","text":"'What did you do to set them off?'","trick":true},{"id":"c","text":"'I'm here. What do you need?'","trick":false},{"id":"d","text":"'If you'd just kept quiet, it wouldn't happen'","trick":true},{"id":"e","text":"'You don't have to carry this alone'","trick":false}],"why":"Asking what they 'did' and 'if you'd kept quiet' blame the survivor; the others believe and support.","relearn":"'What did you do?' and 'if you'd kept quiet' wrongly blame a survivor; believe and support instead."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1228","persona":"any","source":"spot the unsafe record","hook":"Spot the two unsafe ways to keep a record of incidents.","scene":[{"id":"a","text":"A dated log on a trusted friend's phone","trick":false},{"id":"b","text":"A diary left open at home","trick":true},{"id":"c","text":"Copies kept with a trusted person","trick":false},{"id":"d","text":"Notes on the shared family phone","trick":true},{"id":"e","text":"A record only you can reach","trick":false}],"why":"A diary at home and the shared phone can be found or monitored; keep a record out of the abuser's reach.","relearn":"A diary at home or the shared phone is unsafe for a record; keep it out of the abuser's reach."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1229","persona":"any","source":"spot the false belief","hook":"Spot the two false beliefs that stop people reaching help.","scene":[{"id":"a","text":"'It's private, so no help should reach me'","trick":true},{"id":"b","text":"Help is real and reachable for abuse","trick":false},{"id":"c","text":"'I need proof before anyone will believe me'","trick":true},{"id":"d","text":"You don't need proof to be believed","trick":false},{"id":"e","text":"Reaching out is strength, not weakness","trick":false}],"why":"'It's private' and 'I need proof first' are false beliefs that block help; the others are the truths.","relearn":"'It's private' and 'I need proof first' are false; help is reachable and you needn't prove abuse to call."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1230","persona":"any","source":"spot the wrong support move","hook":"Spot the two ways a helper can wrongly take over.","scene":[{"id":"a","text":"Asking the survivor what they need","trick":false},{"id":"b","text":"Filing a complaint without their consent","trick":true},{"id":"c","text":"Respecting their pace and choices","trick":false},{"id":"d","text":"Deciding they must leave today","trick":true},{"id":"e","text":"Keeping the routes to help open","trick":false}],"why":"Acting without consent and ordering them to leave take over; good support asks and respects their pace.","relearn":"Filing for someone or ordering them to leave takes over; ask what they need and respect their pace."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1231","persona":"any","source":"spot the wrong number to dial","hook":"Spot the two claims that send someone to the WRONG help.","scene":[{"id":"a","text":"Women Helpline is 181","trick":false},{"id":"b","text":"For free legal aid, NALSA is 15100","trick":false},{"id":"c","text":"For domestic abuse, dial 1098","trick":true},{"id":"d","text":"In immediate danger, call 112","trick":false},{"id":"e","text":"A woman in distress can reach 100","trick":true}],"why":"1098 is Childline and 100 is police, not the DV routes; for abuse use 181, 1091, or 112 in danger.","relearn":"For domestic abuse use 181 or 1091, and 112 in danger; 1098 is Childline, not the DV route."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1232","persona":"Reshma","source":"spot the exposed move","hook":"Spot the two moves that could be seen by the abuser.","scene":[{"id":"a","text":"Calling 181 quietly when you're alone","trick":false},{"id":"b","text":"Searching for help loudly on the shared phone","trick":true},{"id":"c","text":"A private word with a health worker","trick":false},{"id":"d","text":"Telling the abuser's relatives your plan","trick":true},{"id":"e","text":"A quiet word with a trusted neighbour","trick":false}],"why":"The shared phone and the abuser's relatives can expose you; private, discreet routes keep you safer.","relearn":"The shared phone or the abuser's kin can expose you; reach help privately and discreetly."},
  {"cat":"safety-and-help","type":"spot","id":"rh-1233","persona":"any","source":"spot the leaving myth","hook":"Spot the two myths about leaving and danger.","scene":[{"id":"a","text":"Risk can rise around the time of leaving","trick":false},{"id":"b","text":"'Once you decide to go, the danger is over'","trick":true},{"id":"c","text":"A careful plan helps at the riskiest time","trick":false},{"id":"d","text":"'A survivor should be made to leave at once'","trick":true},{"id":"e","text":"Whether and when to leave is the survivor's choice","trick":false}],"why":"Danger doesn't end at the decision to go, and no one should be forced to leave; the others are true.","relearn":"Risk can rise around leaving and the choice is the survivor's; a careful plan helps at the riskiest time."},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1234","persona":"any","source":"private myth","hook":"\"What happens at home is private, so no one can help.\"","relearn":"Abuse isn't private; 'it's at home' is no shield, and help is real and reachable.","myth":{"un":"What happens at home is private, so no one can help.","re":"Abuse isn't a private matter; help is real and reachable.","why":"'Private' is no shield; routes like 181 and a trusted person exist exactly for harm at home."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1235","persona":"any","source":"physical-only myth","hook":"\"It only counts as abuse if it leaves a mark.\"","relearn":"Emotional, economic and sexual abuse all count, mark or not.","myth":{"un":"It only counts as abuse if it leaves a mark.","re":"Emotional, economic and sexual abuse all count, mark or not.","why":"Abuse takes many forms beyond the physical, and each is real and deserves help."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1236","persona":"any","source":"too-late myth","hook":"\"I've stayed this long, so it's too late to reach out.\"","relearn":"It's never too late to reach for help; staying is never a reason for blame.","myth":{"un":"I've stayed this long, so it's too late to reach out.","re":"It's never too late to reach for help, whatever you've endured.","why":"Staying is never a reason for blame, and routes to help stay open whenever you're ready."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1237","persona":"any","source":"proof myth","hook":"\"No one will help unless I can prove every incident.\"","relearn":"You don't need proof to be believed and helped; helplines believe first.","myth":{"un":"No one will help unless I can prove every incident.","re":"You don't need proof to be believed and helped.","why":"Helplines believe first; from the first call you deserve support, no evidence required."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1238","persona":"any","source":"men-can't myth","hook":"\"Men can't really be abused, so they can't ask for help.\"","relearn":"Anyone of any gender can be abused and can ask for help; the pattern, not the gender, defines abuse.","myth":{"un":"Men can't really be abused, so they can't ask for help.","re":"Anyone of any gender can be abused and can ask for help.","why":"The pattern, not the gender, defines abuse; male and other survivors are believed equally."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1239","persona":"any","source":"leaving-fixes-it myth","hook":"\"Once you decide to leave, the danger is behind you.\"","relearn":"Risk can rise around leaving, so a careful plan matters at the riskiest time.","myth":{"un":"Once you decide to leave, the danger is behind you.","re":"Risk can rise around leaving, so a careful plan matters.","why":"The time of leaving can be the most dangerous; a quiet safety plan helps you through it."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1240","persona":"Reshma","source":"no-money myth","hook":"\"With no money of my own, there's no help I can reach.\"","relearn":"Free, discreet routes (181, a trusted person, NALSA legal aid) reach you whatever your money.","myth":{"un":"With no money of my own, there's no help I can reach.","re":"Free, discreet routes reach you whatever your money.","why":"181, a trusted person and NALSA legal aid cost nothing; help isn't only for those with money."}},
  {"cat":"safety-and-help","type":"strike-rewrite","id":"rh-1241","persona":"Saxena","source":"helper-takeover myth","hook":"\"To really help, you should take charge and fix it for them.\"","relearn":"The best help asks what they need and follows their pace, never taking over.","myth":{"un":"To really help, you should take charge and fix it for them.","re":"The best help asks what they need and follows their pace.","why":"A survivor is the expert on their own danger; taking over removes the control that keeps them safe."}},
  {"id":"rh-1260","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"name calling","relearn":"Names, threats and silent treatment used to wound are emotional abuse.","hook":"\"Words can't be abuse; he never raised a hand.\"","myth":{"un":"Words can't be abuse; only hands can.","re":"Names, threats and the silent treatment used to wound are emotional abuse.","why":"Fear and shame can be inflicted without a single touch."}},
  {"id":"rh-1261","cat":"spot-abuse-control","type":"strike-rewrite","persona":"Reshma","source":"allowance is generous","relearn":"An 'allowance' that you must beg for, with no account of your own, is economic abuse.","hook":"\"He gives me an allowance, so I have nothing to complain about.\"","myth":{"un":"An allowance means he's being generous, not controlling.","re":"An 'allowance' you must beg for, with no account of your own, is economic abuse.","why":"Money handed out to keep you dependent is a leash, not a gift."}},
  {"id":"rh-1262","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"isolation is protective","relearn":"Cutting you off from family and friends is isolation, a core tactic of coercive control.","hook":"\"He keeps me from my friends because he wants me all to himself.\"","myth":{"un":"Wanting you all to himself is romantic, not controlling.","re":"Cutting you off from family and friends is isolation, a tactic of coercive control.","why":"An abuser isolates so no one is left to notice or help."}},
  {"id":"rh-1263","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"one slip isn't a pattern","relearn":"Coercive control is a pattern; many small controlling acts add up to real abuse.","hook":"\"Each thing on its own is small, so none of it can be abuse.\"","myth":{"un":"Each act is small, so together they can't be abuse.","re":"Coercive control is a pattern; small controlling acts add up to real abuse.","why":"It's the steady pattern, not any one act, that traps a person."}},
  {"id":"rh-1264","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"men can't be abused","relearn":"Anyone of any gender can be a victim of abuse; the pattern, not the gender, defines it.","hook":"\"A man can't really be abused by his wife.\"","myth":{"un":"A man can't really be a victim of abuse.","re":"Anyone of any gender can be a victim; the pattern, not the gender, defines abuse.","why":"Control and harm don't check who they happen to."}},
  {"id":"rh-1265","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"provoked it","relearn":"Abuse is the abuser's choice; nothing the other person did causes it.","hook":"\"If I hadn't argued back, he wouldn't have lashed out, so it's partly mine.\"","myth":{"un":"If you provoke them, the abuse is partly your doing.","re":"Abuse is the abuser's choice; nothing you did causes it.","why":"An argument is never a licence to harm someone."}},
  {"id":"rh-1266","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"threats aren't abuse","relearn":"Threats to hurt you, the children, or himself to control you are abuse, not just anger.","hook":"\"He only threatens; he hasn't actually done anything.\"","myth":{"un":"A threat isn't abuse unless he acts on it.","re":"Threats to hurt you, the children, or himself to control you are abuse.","why":"Living under threat is itself a way of being controlled by fear."}},
  {"id":"rh-1267","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"jealousy is care","relearn":"Jealousy used to question, check and restrict you is control, not a measure of love.","hook":"\"His jealousy just shows how much he cares about me.\"","myth":{"un":"Jealousy is a sign of how much he cares.","re":"Jealousy used to question, check and restrict you is control, not love.","why":"Trust expands your world; jealousy shrinks it."}},
  {"id":"rh-1268","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"sex when refused","relearn":"Pressuring or forcing sex when you've said no is sexual abuse, even in a marriage.","hook":"\"Once you're married, refusing sex isn't really a refusal.\"","myth":{"un":"A no in marriage doesn't really count as a no.","re":"Pressuring or forcing sex after you've said no is sexual abuse, even in marriage.","why":"Marriage never turns a no into a yes."}},
  {"id":"rh-1269","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"monitoring is safety","relearn":"Reading your phone and tracking your location without consent is surveillance, a form of abuse.","hook":"\"He checks my phone and location just to keep me safe.\"","myth":{"un":"Checking your phone and location is just keeping you safe.","re":"Reading your phone and tracking your location without consent is surveillance abuse.","why":"Safety doesn't require erasing your privacy."}},
  {"id":"rh-1270","cat":"spot-abuse-control","type":"strike-rewrite","persona":"Razia","source":"it's a family matter","relearn":"Abuse isn't a private family matter; the law and helplines exist precisely for it.","hook":"\"This is a family matter; the law has no place inside a home.\"","myth":{"un":"The law has no place in what happens inside a home.","re":"Abuse isn't a private family matter; the law and helplines exist for it.","why":"A closed door must never become cover for harm."}},
  {"id":"rh-1271","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"walking on eggshells is normal","relearn":"Constantly managing someone's mood to avoid an outburst is a sign of abuse, not a happy home.","hook":"\"Tiptoeing around his moods is just part of married life.\"","myth":{"un":"Walking on eggshells is just normal married life.","re":"Constantly managing someone's mood to avoid an outburst is a sign of abuse.","why":"A safe home doesn't require you to disappear."}},
  {"id":"rh-1272","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"gaslighting","relearn":"Repeatedly twisting events so you doubt your own memory is a real abuse tactic, not your confusion.","hook":"\"Maybe I really am too forgetful and dramatic, like he says.\"","myth":{"un":"If he says you misremember, you're probably just confused.","re":"Repeatedly twisting events so you doubt your own memory is an abuse tactic.","why":"Making you distrust your own mind is a way to control it."}},
  {"id":"rh-1273","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"apology resets it","relearn":"If the cycle of harm and apology keeps repeating, the apology is part of the control, not a cure.","hook":"\"He always says sorry afterwards, so it can't really be abuse.\"","myth":{"un":"A heartfelt sorry afterwards means it isn't abuse.","re":"If harm and apology keep repeating, the apology is part of the control.","why":"Change is shown by it stopping, not by saying sorry again."}},
  {"id":"rh-1274","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"love-bomb is love","relearn":"Sudden gifts and sweetness right after a hurtful spell can be part of a control cycle, not proof of love.","hook":"\"After every bad patch he showers me with love, so deep down he's good.\"","myth":{"un":"Showering you with love after a bad patch proves he's good.","re":"Sudden gifts and sweetness after a hurtful spell can be part of a control cycle.","why":"Warmth that comes and goes on his terms is still control."}},
  {"id":"rh-1275","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"blocking a job","relearn":"Stopping you from working, studying or earning is economic abuse, not him 'providing'.","hook":"\"He won't let me work because a good husband provides everything.\"","myth":{"un":"Stopping you from working just means he provides for you.","re":"Stopping you from working, studying or earning is economic abuse.","why":"Keeping you without your own money keeps you without options."}},
  {"id":"rh-1276","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"strong personality","relearn":"Naming what's happening as control, not a 'strong personality', is the first protection, not disloyalty.","hook":"\"He's not abusive, he just has a strong personality.\"","myth":{"un":"Calling it control is unfair; he just has a strong personality.","re":"Naming it as control, not a 'strong personality', is the first protection.","why":"A strong person lifts you up; control presses you down."}},
  {"id":"rh-1277","cat":"spot-abuse-control","type":"strike-rewrite","persona":"Reshma","source":"kids need a father","relearn":"Living amid control and fear harms children too; their safety counts, and help exists for the whole family.","hook":"\"I should bear anything so the children keep their father.\"","myth":{"un":"You must endure anything to keep the family together for the kids.","re":"Living amid control and fear harms children too; their safety counts.","why":"Children learn safety from a calm home, not a fearful one."}},
  {"id":"rh-1278","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"good days cancel it","relearn":"Kind spells between controlling ones don't undo the abuse; the pattern is what defines it.","hook":"\"He's so loving most days that the bad days don't really count.\"","myth":{"un":"The loving days outnumber the bad ones, so it isn't abuse.","re":"Kind spells between controlling ones don't undo the abuse; the pattern defines it.","why":"An abuser is rarely cruel every hour; that's how the pattern hides."}},
  {"id":"rh-1279","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"permission for everything","relearn":"Needing permission to leave the house, see people or spend a rupee is coercive control.","hook":"\"Asking him before I do anything is just being a respectful wife.\"","myth":{"un":"Asking permission for everything is just being respectful.","re":"Needing permission to leave, see people or spend a rupee is coercive control.","why":"Respect is mutual; permission for everything is a cage."}},
  {"id":"rh-1280","cat":"spot-abuse-control","type":"strike-rewrite","persona":"any","source":"silence means fine","relearn":"A partner going quiet, withdrawn or watchful can be coping with control, not contentment.","hook":"\"She's gone quiet and never goes out now, so she must be settled.\"","myth":{"un":"She's quiet and stays in, so she must be content.","re":"A partner gone quiet, withdrawn or watchful can be coping with control.","why":"Sometimes silence is fear wearing the mask of calm."}},
  {"id":"rh-1281","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two red flags","relearn":"Taking the wages and blocking the account are the red flags; sharing, asking and welcoming aren't.","hook":"Spot the two red flags of economic abuse.","scene":[{"id":"a","text":"Taking your full wages each month","trick":true},{"id":"b","text":"Talking over the budget together","trick":false},{"id":"c","text":"Blocking you from your own bank account","trick":true},{"id":"d","text":"Asking before a big purchase","trick":false},{"id":"e","text":"Being glad you have savings","trick":false}],"why":"Taking the wages and blocking the account are the red flags; sharing, asking and welcoming aren't."},
  {"id":"rh-1282","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two red flags","relearn":"Tracking your location and reading your messages are the red flags; trust and ordinary interest aren't.","hook":"Spot the two red flags of surveillance.","scene":[{"id":"a","text":"Asking how your day went","trick":false},{"id":"b","text":"Tracking your live location all day","trick":true},{"id":"c","text":"Trusting you out with friends","trick":false},{"id":"d","text":"Reading your private messages","trick":true},{"id":"e","text":"Knocking before entering","trick":false}],"why":"Tracking your location and reading your messages are the red flags; trust and ordinary interest aren't."},
  {"id":"rh-1283","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two manipulative lines","relearn":"'Worthless without me' and 'no one else would put up with you' are degrading control; the rest are respect.","hook":"Spot the two lines that degrade and control.","scene":[{"id":"a","text":"\"You're worthless without me\"","trick":true},{"id":"b","text":"\"I value what you think\"","trick":false},{"id":"c","text":"\"No one else would put up with you\"","trick":true},{"id":"d","text":"\"Let's decide this together\"","trick":false},{"id":"e","text":"\"Take the time you need\"","trick":false}],"why":"'Worthless without me' and 'no one else would put up with you' are degrading control; the rest are respect."},
  {"id":"rh-1284","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two red flags","relearn":"Cutting off her family and forbidding outings are isolation; welcoming people and friendships aren't.","hook":"Spot the two red flags of isolation.","scene":[{"id":"a","text":"Welcoming your family to visit","trick":false},{"id":"b","text":"Cutting you off from your parents","trick":true},{"id":"c","text":"Encouraging your friendships","trick":false},{"id":"d","text":"Forbidding you to leave the house","trick":true},{"id":"e","text":"Being happy you have a hobby","trick":false}],"why":"Cutting off her family and forbidding outings are isolation; welcoming people and friendships aren't."},
  {"id":"rh-1285","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two threats","relearn":"Threatening harm to you and to himself to keep you are abuse; honest, calm talk isn't.","hook":"Spot the two lines that control through threat.","scene":[{"id":"a","text":"\"Let's talk when we're both calm\"","trick":false},{"id":"b","text":"\"If you leave, I'll hurt myself\"","trick":true},{"id":"c","text":"\"I hear that you're upset\"","trick":false},{"id":"d","text":"\"Try that and you'll regret it\"","trick":true},{"id":"e","text":"\"Your feelings matter to me\"","trick":false}],"why":"Threatening harm to you and to himself to keep you are abuse; honest, calm talk isn't."},
  {"id":"rh-1286","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two coercive moves","relearn":"Pressuring after a no and 'it's a wife's duty' deny consent; checking in and accepting a no respect it.","hook":"Spot the two lines that ignore consent.","scene":[{"id":"a","text":"\"It's okay, we don't have to tonight\"","trick":false},{"id":"b","text":"\"You're my wife, so it's your duty\"","trick":true},{"id":"c","text":"\"Are you comfortable with this?\"","trick":false},{"id":"d","text":"Pressuring you after you've said no","trick":true},{"id":"e","text":"\"A no is a no, always\"","trick":false}],"why":"Pressuring after a no and 'it's a wife's duty' deny consent; checking in and accepting a no respect it."},
  {"id":"rh-1287","cat":"spot-abuse-control","type":"spot","persona":"Reshma","source":"two red flags","relearn":"Demanding permission to step out and rationing money are coercive control; trust and openness aren't.","hook":"Spot the two red flags of control.","scene":[{"id":"a","text":"Needing his permission to leave home","trick":true},{"id":"b","text":"Both of you knowing the household money","trick":false},{"id":"c","text":"Rationing you a few rupees a day","trick":true},{"id":"d","text":"Trusting you to run errands alone","trick":false},{"id":"e","text":"Talking plans over as equals","trick":false}],"why":"Demanding permission to step out and rationing money are coercive control; trust and openness aren't."},
  {"id":"rh-1288","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two gaslighting moves","relearn":"Denying what you saw and calling you 'too dramatic' make you doubt yourself; owning a mistake doesn't.","hook":"Spot the two lines that make you doubt yourself.","scene":[{"id":"a","text":"\"That never happened, you imagined it\"","trick":true},{"id":"b","text":"\"You're right, I got that wrong\"","trick":false},{"id":"c","text":"\"You're too dramatic to trust\"","trick":true},{"id":"d","text":"\"Let's check what really happened\"","trick":false},{"id":"e","text":"\"I can see why you felt that\"","trick":false}],"why":"Denying what you saw and calling you 'too dramatic' make you doubt yourself; owning a mistake doesn't."},
  {"id":"rh-1289","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two warning signs","relearn":"Punishing you with silence and 'see what you made me do' shift blame and control; honesty doesn't.","hook":"Spot the two warning signs of control.","scene":[{"id":"a","text":"\"I'm sorry, that was on me\"","trick":false},{"id":"b","text":"Days of icy silence to punish you","trick":true},{"id":"c","text":"\"See what you made me do\"","trick":true},{"id":"d","text":"\"Tell me how you really feel\"","trick":false},{"id":"e","text":"Letting an argument cool, then talking","trick":false}],"why":"Punishing you with silence and 'see what you made me do' shift blame and control; honesty doesn't."},
  {"id":"rh-1290","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two controlling moves","relearn":"Dictating clothes and deleting contacts are control; choice and your own circle are freedom.","hook":"Spot the two moves that control your life.","scene":[{"id":"a","text":"Choosing your own clothes","trick":false},{"id":"b","text":"Dictating exactly what you may wear","trick":true},{"id":"c","text":"Keeping your own friends list","trick":false},{"id":"d","text":"Deleting contacts from your phone","trick":true},{"id":"e","text":"Coming and going freely","trick":false}],"why":"Dictating clothes and deleting contacts are control; choice and your own circle are freedom."},
  {"id":"rh-1291","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two false beliefs","relearn":"'Only bruises count' and 'sorry undoes it' are false; harm has many forms and the pattern is what counts.","hook":"Spot the two false beliefs about abuse.","scene":[{"id":"a","text":"Control and humiliation can be abuse","trick":false},{"id":"b","text":"Only visible bruises count as abuse","trick":true},{"id":"c","text":"Fear can be inflicted without a touch","trick":false},{"id":"d","text":"A sorry afterwards undoes the harm","trick":true},{"id":"e","text":"The repeating pattern is what defines it","trick":false}],"why":"'Only bruises count' and 'sorry undoes it' are false; harm has many forms and the pattern is what counts."},
  {"id":"rh-1292","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two red flags","relearn":"Tracking spending to control and 'hand over your salary' are economic abuse; planning and your own account aren't.","hook":"Spot the two red flags about money.","scene":[{"id":"a","text":"Having your own account","trick":false},{"id":"b","text":"\"Hand over your salary to me\"","trick":true},{"id":"c","text":"Planning the month together","trick":false},{"id":"d","text":"Logging every rupee you spend to control you","trick":true},{"id":"e","text":"Saving for your own goals","trick":false}],"why":"Tracking spending to control and 'hand over your salary' are economic abuse; planning and your own account aren't."},
  {"id":"rh-1293","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two red flags","relearn":"Controlling where she goes and a phone she must answer instantly are control; trust and space aren't.","hook":"Spot the two red flags of monitoring.","scene":[{"id":"a","text":"Trusting you to go out alone","trick":false},{"id":"b","text":"Demanding you answer his calls instantly","trick":true},{"id":"c","text":"Giving you quiet space when needed","trick":false},{"id":"d","text":"Deciding everywhere you're allowed to go","trick":true},{"id":"e","text":"Being fine not knowing your every move","trick":false}],"why":"Controlling where she goes and a phone she must answer instantly are control; trust and space aren't."},
  {"id":"rh-1294","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two abusive moves","relearn":"Blaming you for his anger and threatening the children are abuse and control; calm and care aren't.","hook":"Spot the two moves that abuse and control.","scene":[{"id":"a","text":"Owning his own temper","trick":false},{"id":"b","text":"\"You made me this angry\"","trick":true},{"id":"c","text":"Staying calm when you disagree","trick":false},{"id":"d","text":"Threatening to take the children","trick":true},{"id":"e","text":"Caring for the children together","trick":false}],"why":"Blaming you for his anger and threatening the children are abuse and control; calm and care aren't."},
  {"id":"rh-1295","cat":"spot-abuse-control","type":"spot","persona":"any","source":"two warning signs","relearn":"Mocking your goals and forbidding study are control that shrinks you; support and freedom expand you.","hook":"Spot the two warning signs of control.","scene":[{"id":"a","text":"Cheering on your studies","trick":false},{"id":"b","text":"Mocking your goals as silly","trick":true},{"id":"c","text":"Backing your small dreams","trick":false},{"id":"d","text":"Forbidding you to study or train","trick":true},{"id":"e","text":"Letting your world grow","trick":false}],"why":"Mocking your goals and forbidding study are control that shrinks you; support and freedom expand you."},
  {"id":"rh-1296","cat":"spot-abuse-control","type":"sort","persona":"any","source":"abuse or not","relearn":"Insults, withheld money and isolation are abuse; disagreeing, sharing and welcoming friends are healthy.","hook":"Sort: a form of abuse, or healthy?","items":[{"id":"a","text":"Constant insults to wear you down"},{"id":"b","text":"Disagreeing and still being heard"},{"id":"c","text":"Withholding money to control you"},{"id":"d","text":"Sharing decisions as equals"},{"id":"e","text":"Cutting you off from friends"},{"id":"f","text":"Being welcome to see your family"}],"bins":[{"id":"abuse","label":"Abuse","valence":"neg"},{"id":"healthy","label":"Healthy","valence":"pos"}],"key":{"a":"abuse","b":"healthy","c":"abuse","d":"healthy","e":"abuse","f":"healthy"}},
  {"id":"rh-1297","cat":"spot-abuse-control","type":"sort","persona":"any","source":"form of abuse","relearn":"Each maps to its form: insult=emotional, salary grab=economic, forced sex=sexual, tracking=coercive control.","hook":"Sort each act into the form of abuse it is.","items":[{"id":"a","text":"Humiliating you in public"},{"id":"b","text":"Seizing your whole salary"},{"id":"c","text":"Forcing sex after a no"},{"id":"d","text":"Tracking your every move"},{"id":"e","text":"Calling you stupid daily"},{"id":"f","text":"Blocking you from a job"}],"bins":[{"id":"emotional","label":"Emotional","valence":"neg"},{"id":"economic","label":"Economic","valence":"neg"},{"id":"sexual","label":"Sexual","valence":"neg"},{"id":"control","label":"Coercive control","valence":"neg"}],"key":{"a":"emotional","b":"economic","c":"sexual","d":"control","e":"emotional","f":"economic"}},
  {"id":"rh-1298","cat":"spot-abuse-control","type":"sort","persona":"any","source":"care or control","relearn":"Trust, space and welcome are care; checking the phone, dictating clothes and approving friends are control.","hook":"Sort: care, or control dressed as care?","items":[{"id":"a","text":"Trusting you with your own day"},{"id":"b","text":"Checking your phone in secret"},{"id":"c","text":"Giving you space when you need it"},{"id":"d","text":"Dictating what you can wear"},{"id":"e","text":"Welcoming your friends in"},{"id":"f","text":"Approving who you may see"}],"bins":[{"id":"care","label":"Care","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"care","b":"control","c":"care","d":"control","e":"care","f":"control"}},
  {"id":"rh-1299","cat":"spot-abuse-control","type":"sort","persona":"any","source":"warning or healthy","relearn":"Permission demands, secret tracking and isolation are warning signs; trust, privacy and friendships are healthy.","hook":"Sort: a warning sign, or healthy?","items":[{"id":"a","text":"Needing permission to step out"},{"id":"b","text":"Trusting your friendships"},{"id":"c","text":"Tracking you without your knowing"},{"id":"d","text":"Respecting your privacy"},{"id":"e","text":"Keeping you from your family"},{"id":"f","text":"Encouraging your own plans"}],"bins":[{"id":"warning","label":"Warning sign","valence":"uhoh"},{"id":"healthy","label":"Healthy","valence":"pos"}],"key":{"a":"warning","b":"healthy","c":"warning","d":"healthy","e":"warning","f":"healthy"}},
  {"id":"rh-1300","cat":"spot-abuse-control","type":"sort","persona":"Reshma","source":"economic abuse or not","relearn":"Grabbing wages, an 'allowance' and a blocked job are economic abuse; joint planning and your own account aren't.","hook":"Sort: economic abuse, or not?","items":[{"id":"a","text":"Taking your wages each month"},{"id":"b","text":"Planning the budget together"},{"id":"c","text":"Forcing you to beg for an allowance"},{"id":"d","text":"Having your own bank account"},{"id":"e","text":"Stopping you from earning"},{"id":"f","text":"Saving for shared goals openly"}],"bins":[{"id":"abuse","label":"Economic abuse","valence":"neg"},{"id":"ok","label":"Not abuse","valence":"pos"}],"key":{"a":"abuse","b":"ok","c":"abuse","d":"ok","e":"abuse","f":"ok"}},
  {"id":"rh-1301","cat":"spot-abuse-control","type":"sort","persona":"any","source":"say it or stay safe","relearn":"Naming abuse, asking for help and reaching a trusted person are speak-up moves; staying quiet from fear isn't safe.","hook":"Sort: a speak-up step, or staying silent?","items":[{"id":"a","text":"Naming what's happening as abuse"},{"id":"b","text":"Telling yourself it's normal"},{"id":"c","text":"Reaching a trusted person quietly"},{"id":"d","text":"Hiding it so no one worries"},{"id":"e","text":"Asking a helpline what your options are"},{"id":"f","text":"Pretending everything is fine"}],"bins":[{"id":"speak","label":"Speak up","valence":"tell"},{"id":"silent","label":"Staying silent","valence":"uhoh"}],"key":{"a":"speak","b":"silent","c":"speak","d":"silent","e":"speak","f":"silent"}},
  {"id":"rh-1302","cat":"spot-abuse-control","type":"sort","persona":"any","source":"love or control","relearn":"Trust, freedom and support are love; jealousy, monitoring and isolation are control wearing love's name.","hook":"Sort: love, or control calling itself love?","items":[{"id":"a","text":"Trusting you without checking"},{"id":"b","text":"Jealous questioning of everyone"},{"id":"c","text":"Backing your freedom to choose"},{"id":"d","text":"Monitoring your phone and steps"},{"id":"e","text":"Supporting your friendships"},{"id":"f","text":"Isolating you from everyone"}],"bins":[{"id":"love","label":"Love","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"love","b":"control","c":"love","d":"control","e":"love","f":"control"}},
  {"id":"rh-1303","cat":"spot-abuse-control","type":"sort","persona":"any","source":"whose fault","relearn":"Responsibility for abuse always sits with the abuser; what a survivor wore, said or did never causes it.","hook":"Sort: a cause of abuse, or never a cause?","items":[{"id":"a","text":"What the survivor was wearing"},{"id":"b","text":"The abuser choosing to harm"},{"id":"c","text":"An argument the survivor had"},{"id":"d","text":"The abuser's own temper"},{"id":"e","text":"The survivor going out with friends"},{"id":"f","text":"The abuser's decision to control"}],"bins":[{"id":"never","label":"Never a cause","valence":"pos"},{"id":"cause","label":"The abuser's choice","valence":"tell"}],"key":{"a":"never","b":"cause","c":"never","d":"cause","e":"never","f":"cause"}},
  {"id":"rh-1304","cat":"spot-abuse-control","type":"sort","persona":"any","source":"pattern or one-off","relearn":"Repeating control, isolation and monitoring make a coercive pattern; a single rough day, owned and changed, is different.","hook":"Sort: part of a coercive pattern, or a one-off owned and changed?","items":[{"id":"a","text":"Control that repeats week after week"},{"id":"b","text":"One harsh word, then a real change"},{"id":"c","text":"Isolation that keeps growing"},{"id":"d","text":"A rare slip he truly stops"},{"id":"e","text":"Monitoring that never lets up"},{"id":"f","text":"A mistake owned and not repeated"}],"bins":[{"id":"pattern","label":"Coercive pattern","valence":"neg"},{"id":"oneoff","label":"Owned and changed","valence":"neutral"}],"key":{"a":"pattern","b":"oneoff","c":"pattern","d":"oneoff","e":"pattern","f":"oneoff"}},
  {"id":"rh-1305","cat":"spot-abuse-control","type":"branch","persona":"any","source":"name the money control","relearn":"Naming it as economic abuse, not 'his way', is the first step.","hook":"He says the joint account must close and you'll get a weekly allowance from now on.","options":[{"text":"Name it to yourself as economic abuse","consequence":"You see the pattern for what it is.","outcome":"clear","best":true},{"text":"Accept it as how he manages money","consequence":"You hand over control of your only footing.","outcome":"blur"}],"debrief":"Naming a salary grab and a forced allowance as economic abuse is how you see the pattern early."},
  {"id":"rh-1306","cat":"spot-abuse-control","type":"branch","persona":"Reshma","source":"a quiet route to help","relearn":"Reaching a trusted person or 181 quietly is a safe first step.","hook":"The control is wearing you down and you wonder if anyone could even help.","options":[{"text":"Quietly ask a trusted person or 181 about options","consequence":"You open a safe route at your own pace.","outcome":"clear","best":true},{"text":"Decide it's private and tell no one","consequence":"'Private' leaves you alone with it; a quiet route keeps you safe.","outcome":"blur"}],"debrief":"Reaching a trusted person or 181 quietly keeps you safe while you learn your options, no big steps forced."},
  {"id":"rh-1307","cat":"spot-abuse-control","type":"branch","persona":"any","source":"support, not take over","relearn":"Believe her, ask what she needs, don't take over her choices.","hook":"A friend confides that her husband controls her every move and you want to help.","options":[{"text":"Believe her and ask what she needs","consequence":"You support her without overriding her.","outcome":"clear","best":true},{"text":"Tell her exactly what she must do now","consequence":"Taking over her choices can raise her risk and isn't yours to decide.","outcome":"blur"}],"debrief":"Believing her, asking what she needs and not taking over respects her pace and keeps her safe."},
  {"id":"rh-1308","cat":"spot-abuse-control","type":"branch","persona":"any","source":"trust your read","relearn":"Trust your own memory; quietly note what really happened.","hook":"He insists the fight you clearly remember 'never happened' and you start to doubt yourself.","options":[{"text":"Trust your memory and note what happened","consequence":"You hold onto your own reality.","outcome":"clear","best":true},{"text":"Decide you must be misremembering","consequence":"Doubting your own mind is exactly what the tactic is for.","outcome":"blur"}],"debrief":"Trusting your own memory and noting what really happened resists gaslighting, a real control tactic."},
  {"id":"rh-1309","cat":"spot-abuse-control","type":"branch","persona":"any","source":"threat is not love","relearn":"A threat to self-harm used to keep you is control, not your fault.","hook":"He says that if you ever leave, he'll hurt himself, and it makes you feel responsible.","options":[{"text":"See it as control and reach support","consequence":"You set down blame that was never yours.","outcome":"clear","best":true},{"text":"Stay because you feel responsible for him","consequence":"A threat used to hold you is coercion; his choices aren't your fault.","outcome":"blur"}],"debrief":"Seeing the threat as control, not love, lets you reach support instead of carrying blame that isn't yours."},
  {"id":"rh-1310","cat":"spot-abuse-control","type":"branch","persona":"any","source":"help for a man too","relearn":"Anyone of any gender can be a victim; believe him and point to help.","hook":"Your brother hints his wife screams at, belittles and tracks him, but says 'men can't be victims'.","options":[{"text":"Believe him and point him to the same help","consequence":"You let a real victim be heard.","outcome":"clear","best":true},{"text":"Brush it off because he's a man","consequence":"Dismissing him because he's a man leaves a real victim unheard.","outcome":"blur"}],"debrief":"Believing him equally and pointing to the same help reminds him abuse isn't defined by gender."},
  {"id":"rh-1311","cat":"spot-abuse-control","type":"match","persona":"any","source":"form to description","relearn":"Emotional, economic, sexual, coercive control and physical each have a plain description.","hook":"Match each form of abuse to its plain description.","pairs":[{"left":"Emotional abuse","right":"Insults that wear you down"},{"left":"Economic abuse","right":"Controlling all the money"},{"left":"Sexual abuse","right":"Forcing sex after a no"},{"left":"Coercive control","right":"Monitoring and isolating you"},{"left":"Physical abuse","right":"Hurting or restraining your body"}]},
  {"id":"rh-1312","cat":"spot-abuse-control","type":"match","persona":"any","source":"control move to what it limits","relearn":"Each controlling move removes a specific freedom.","hook":"Match each controlling move to the freedom it takes.","pairs":[{"left":"Reading your phone","right":"Your privacy"},{"left":"Taking your wages","right":"Your money"},{"left":"Forbidding outings","right":"Your movement"},{"left":"Cutting off family","right":"Your support"},{"left":"Dictating clothes","right":"Your choices"}]},
  {"id":"rh-1313","cat":"spot-abuse-control","type":"match","persona":"any","source":"need to route","relearn":"Each need maps to a help route: danger, rights, women's help, free legal aid, a trusted person.","hook":"Match each need to the help route that fits.","pairs":[{"left":"Immediate danger now","right":"112"},{"left":"A woman in distress","right":"1091"},{"left":"Women helpline support","right":"181"},{"left":"Free legal aid","right":"15100"},{"left":"Someone safe to confide in","right":"A trusted person"}]},
  {"id":"rh-1314","cat":"spot-abuse-control","type":"match","persona":"any","source":"control vs care line","relearn":"Each controlling line has a caring counterpart that trusts instead of polices.","hook":"Match each controlling line to the caring line that replaces it.","pairs":[{"left":"\"Where are you, answer now\"","right":"\"Hope your day's going well\""},{"left":"\"You can't see them\"","right":"\"Glad you have good friends\""},{"left":"\"Hand over your card\"","right":"\"Let's plan the budget\""},{"left":"\"You'd be nothing without me\"","right":"\"I value who you are\""},{"left":"\"You imagined that\"","right":"\"Let's recall it together\""}]},
  {"id":"rh-1315","cat":"spot-abuse-control","type":"match","persona":"Reshma","source":"economic-abuse sign to footing","relearn":"Each sign of economic abuse has a small step toward financial footing.","hook":"Match each economic-abuse sign to the small footing that answers it.","pairs":[{"left":"No money of your own","right":"A small private saving"},{"left":"Begging for an allowance","right":"Knowing the household money"},{"left":"Blocked from a job","right":"A skill or tiny earning"},{"left":"No bank account","right":"An account in your name"},{"left":"No record of spending","right":"Quietly noting what's spent"}]},
  {"id":"rh-1316","cat":"spot-abuse-control","type":"match","persona":"any","source":"myth to truth","relearn":"Each common myth about abuse has a clear truth that answers it.","hook":"Match each myth about abuse to the truth that answers it.","pairs":[{"left":"Only bruises count","right":"Harm has many forms"},{"left":"Control is love","right":"Trust is love, not control"},{"left":"You provoked it","right":"Abuse is the abuser's choice"},{"left":"It's private","right":"Help and protection exist"},{"left":"Men can't be victims","right":"Anyone can be a victim"}]},
  {"id":"rh-1317","cat":"spot-abuse-control","type":"match","persona":"any","source":"tactic to its aim","relearn":"Each coercive tactic has an aim: doubt, dependence, fear, silence, isolation.","hook":"Match each coercive tactic to what it's meant to do.","pairs":[{"left":"Gaslighting","right":"Make you doubt yourself"},{"left":"Taking the money","right":"Keep you dependent"},{"left":"Threats","right":"Keep you afraid"},{"left":"Silent treatment","right":"Punish and silence you"},{"left":"Isolation","right":"Leave no one to help"}]},
  {"id":"rh-1318","cat":"spot-abuse-control","type":"match","persona":"any","source":"red flag to green flag","relearn":"Each red-flag habit has a green-flag opposite built on trust.","hook":"Match each red-flag habit to its green-flag opposite.","pairs":[{"left":"Jealous checking","right":"Easy trust"},{"left":"Permission for everything","right":"Free movement"},{"left":"Secret tracking","right":"Respected privacy"},{"left":"Shrinking your world","right":"A growing life"},{"left":"Constant put-downs","right":"Genuine respect"}]},
  {"id":"rh-1319","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"name control calmly","relearn":"Naming your need for your own footing, calmly, is the assertive line.","hook":"Say the assertive line.","setup":"He says you don't need your own account; he'll handle all the money from now on.","yourLine":[{"text":"\"I'll keep my own account; we can still plan together.\"","best":true},{"text":"\"Okay, whatever you think is best.\""}]},
  {"id":"rh-1320","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"hold a no","relearn":"Holding your no, kindly and clearly, is the assertive line.","hook":"Say the assertive line.","setup":"After you've said no to sex tonight, he keeps pressing that it's your duty.","yourLine":[{"text":"\"I've said no, and that stands. No isn't a duty thing.\"","best":true},{"text":"\"Fine, I suppose I have no choice.\""}]},
  {"id":"rh-1321","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"refuse the permission rule","relearn":"Declining to live under a permission rule is the assertive line.","hook":"Say the assertive line.","setup":"He tells you that from now on you must ask him before leaving the house.","yourLine":[{"text":"\"I'll let you know my plans, but I don't need permission to go out.\"","best":true},{"text":"\"Alright, I'll ask you first every time.\""}]},
  {"id":"rh-1322","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"trust your memory","relearn":"Standing by your own memory is the assertive line.","hook":"Say the assertive line.","setup":"He insists, again, that the argument you clearly recall simply never happened.","yourLine":[{"text":"\"It did happen, and I trust what I remember.\"","best":true},{"text":"\"Maybe you're right and I imagined it.\""}]},
  {"id":"rh-1323","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"set a phone boundary","relearn":"Keeping your privacy without apology is the assertive line.","hook":"Say the assertive line.","setup":"He demands the password to your phone so he can read your messages anytime.","yourLine":[{"text":"\"My phone stays private. Trust isn't reading my messages.\"","best":true},{"text":"\"Here, check whatever you want, I've nothing to hide.\""}]},
  {"id":"rh-1324","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"support a friend","relearn":"Believing her and asking what she needs is the assertive, helpful line.","hook":"Say the assertive line.","setup":"Your friend whispers that her husband controls and frightens her, and waits for your reaction.","yourLine":[{"text":"\"I believe you. What do you need, and how can I help?\"","best":true},{"text":"\"Are you sure? He always seems so nice.\""}]},
  {"id":"rh-1325","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"refuse to take blame","relearn":"Refusing the blame and placing it where it belongs is the assertive line.","hook":"Say the assertive line.","setup":"He says you only got hurt because you pushed him too far in the argument.","yourLine":[{"text":"\"An argument is never a reason to hurt me. That was your choice.\"","best":true},{"text":"\"You're right, I shouldn't have argued back.\""}]},
  {"id":"rh-1326","cat":"spot-abuse-control","type":"role-play","persona":"any","source":"reach for help","relearn":"Choosing to reach real help anyway is the assertive line.","hook":"Say the assertive line.","setup":"It's getting worse and a relative says it's shameful to involve anyone outside.","yourLine":[{"text":"\"I'm going to reach a trusted person or 181. There's no shame in help.\"","best":true},{"text":"\"You're right, I'll just keep it to myself.\""}]},
  {"id":"rh-1327","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"what control feels like","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: Which of these has felt like control to you?","prompt":"Lensy: Which of these has felt like control to you?","options":["Asking permission for small things","Being watched or checked","Money kept out of reach","None of these right now"],"affirm":"Whatever you noticed, your read counts. Control is real even when it's quiet. You're not alone. Reach a trusted person, 181, 1091 or 112. 💛"},
  {"id":"rh-1328","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"a freedom you value","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: Which freedom would you least want a partner to take?","prompt":"Lensy: Which freedom would you least want a partner to take?","options":["Seeing my family and friends","My own money","Where I can go","My privacy"],"affirm":"Each of these is yours to keep. A partner who respects you guards them with you. 💛"},
  {"id":"rh-1329","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"who you'd tell","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: If something felt unsafe, who might you reach first?","prompt":"Lensy: If something felt unsafe, who might you reach first?","options":["A trusted friend or relative","A helpline like 181","A counsellor","I'm not sure yet"],"affirm":"There's no wrong answer. Naming someone now, even quietly, is a kind of safety. 181, 1091 or 112 are there too. 💛"},
  {"id":"rh-1330","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"a green flag you'd want","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: Which sign of trust matters most to you?","prompt":"Lensy: Which sign of trust matters most to you?","options":["Being believed","Keeping my own choices","Space when I need it","Support for my goals"],"affirm":"Whatever you chose, you deserve it. Trust expands your world; control shrinks it. 💛"},
  {"id":"rh-1331","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"not your fault","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: Sit with this for a moment, whichever fits.","prompt":"Lensy: Sit with this for a moment, whichever fits.","options":["Abuse is never the survivor's fault","Shame belongs to the one who harms","Naming it is strength","All of these"],"affirm":"Every one of these is true. The only person responsible is the one causing harm. You're not alone. 💛"},
  {"id":"rh-1332","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"what respect looks like","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: Which feels most like respect to you?","prompt":"Lensy: Which feels most like respect to you?","options":["My no being honoured","My opinion counting","My money being mine","Being free to come and go"],"affirm":"All of these are respect, and all of them are yours by right. 💛"},
  {"id":"rh-1333","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"noticing a pattern","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: When you think of 'the pattern', what comes to mind?","prompt":"Lensy: When you think of 'the pattern', what comes to mind?","options":["The small things adding up","A cycle of harm then sorry","Walking on eggshells","I'm still working it out"],"affirm":"However you see it, your noticing matters. The pattern is what defines control, not any one day. 💛"},
  {"id":"rh-1334","cat":"spot-abuse-control","type":"reflect","persona":"any","source":"what you'd tell a friend","relearn":"Control is abuse, not love; it's never your fault, and help exists.","hook":"Lensy: If a friend told you this was happening, what would you say?","prompt":"Lensy: If a friend told you this was happening, what would you say?","options":["\"I believe you\"","\"It's not your fault\"","\"What do you need?\"","\"You're not alone\""],"affirm":"Every one of these is the right thing to say, and just as true said to yourself. 💛"},
  {"id":"rh-1350","type":"match","persona":"Razia","source":"need to route","hook":"Match each need to the route that fits it.","pairs":[{"left":"In danger right now","right":"Call 112"},{"left":"Want to talk to someone today","right":"Women Helpline 181"},{"left":"Need a protection or maintenance order","right":"DV Act 2005 + free legal aid"},{"left":"Can't afford a lawyer","right":"NALSA legal aid 15100"},{"left":"Nowhere safe to sleep tonight","right":"A women's shelter"}],"relearn":"Each need has a route: 112 for danger, 181 to talk, the DV Act and 15100 for orders, a shelter for a bed.","cat":"tools-and-help"},
  {"id":"rh-1351","type":"match","persona":"any","source":"abuse form to description","hook":"Match each form of abuse to its plain description.","pairs":[{"left":"Economic abuse","right":"Withholding money so you can't leave"},{"left":"Emotional abuse","right":"Constant put-downs and threats"},{"left":"Sexual abuse","right":"Forcing or coercing sex"},{"left":"Coercive control","right":"Monitoring, isolating, demanding permission"},{"left":"Physical abuse","right":"Hitting, shoving or restraining"}],"relearn":"Economic, emotional, sexual, coercive-control and physical abuse each have a clear plain description.","cat":"tools-and-help"},
  {"id":"rh-1352","type":"match","persona":"Razia","source":"DV Act remedy","hook":"Match each DV Act 2005 remedy to what it does for a survivor.","pairs":[{"left":"Protection order","right":"Stops the abuser from harming or contacting you"},{"left":"Residence order","right":"Lets you stay safely in the shared home"},{"left":"Monetary relief","right":"Covers losses and expenses caused by the abuse"},{"left":"Maintenance","right":"Ongoing financial support"},{"left":"Custody order","right":"Settles where the children stay safely"}],"relearn":"The DV Act 2005 can give protection, residence, monetary relief, maintenance and custody orders.","cat":"tools-and-help"},
  {"id":"rh-1353","type":"match","persona":"any","source":"helpline purpose","hook":"Match each help number to what it's for.","pairs":[{"left":"112","right":"Immediate danger, emergency"},{"left":"181","right":"Women Helpline, support and guidance"},{"left":"1091","right":"Women in distress"},{"left":"15100","right":"Free legal aid"},{"left":"A trusted person","right":"Someone safe who believes you"}],"relearn":"112 for danger, 181 and 1091 for women's support, 15100 for free legal aid, a trusted person to lean on.","cat":"tools-and-help"},
  {"id":"rh-1354","type":"match","persona":"Saxena","source":"support step to why","hook":"Match each survivor-support step to why it helps.","pairs":[{"left":"\"I believe you\"","right":"Removes the fear of not being trusted"},{"left":"\"It isn't your fault\"","right":"Lifts shame that was never theirs"},{"left":"\"What do you need?\"","right":"Keeps the choice with the survivor"},{"left":"Share the routes, don't push","right":"Offers help without taking over"},{"left":"Keep it private and safe","right":"Protects them from extra risk"}],"relearn":"Believe, lift blame, ask what they need, offer routes without pushing, and keep it safe and private.","cat":"tools-and-help"},
  {"id":"rh-1355","type":"match","persona":"any","source":"home truth to protection","hook":"Match each home truth to what it keeps safe.","pairs":[{"left":"Marriage isn't standing consent","right":"Your bodily autonomy"},{"left":"Control isn't love","right":"Your freedom to choose"},{"left":"It's never your fault","right":"Your sense of worth"},{"left":"\"Private\" is no shield","right":"Your right to reach help"},{"left":"An equal voice belongs at home","right":"Your say in your own life"}],"relearn":"Each home truth guards something real: autonomy, freedom, worth, the right to help, and your own voice.","cat":"tools-and-help"},
  {"id":"rh-1356","type":"match","persona":"Razia","source":"who can help","hook":"Match each helper to the kind of help they give.","pairs":[{"left":"Women's-rights worker","right":"Believing you and knowing the routes"},{"left":"Free legal-aid lawyer","right":"Help to file under the DV Act 2005"},{"left":"Counsellor","right":"Space to talk and steady yourself"},{"left":"Shelter","right":"A safe place to stay"},{"left":"Trusted neighbour","right":"A code word and quick help nearby"}],"relearn":"Each helper has a role: belief and routes, legal filing, a space to talk, a safe bed, or quick local help.","cat":"tools-and-help"},
  {"id":"rh-1357","type":"match","persona":"any","source":"safety-plan piece","hook":"Match each safety-plan piece to what it's for.","pairs":[{"left":"A dated record of incidents","right":"Evidence if you ever need it"},{"left":"A code word with a friend","right":"Signalling for help without saying it"},{"left":"Copies of key documents","right":"Not being stuck without your papers"},{"left":"A safe place to go","right":"Somewhere to head if you must leave"},{"left":"A charged phone and small savings","right":"A way to call and a little cushion"}],"relearn":"Safety planning: a dated record, a code word, document copies, a safe place, and a way to call and cope.","cat":"tools-and-help"},
  {"id":"rh-1358","type":"match","persona":"Saxena","source":"myth to truth","hook":"Match each myth to the truth that answers it.","pairs":[{"left":"\"It's only abuse if he hits me\"","right":"Emotional and economic abuse count too"},{"left":"\"What happens at home is private\"","right":"\"Private\" is no shield; help exists"},{"left":"\"He controls the money, he earns it\"","right":"Controlling money to trap you is abuse"},{"left":"\"I must have provoked it\"","right":"Abuse is the abuser's doing, never yours"},{"left":"\"Marriage means I can't say no\"","right":"Consent stays yours inside marriage"}],"relearn":"Each myth has its truth: all forms count, private is no shield, money-control is abuse, consent stays yours.","cat":"tools-and-help"},
  {"id":"rh-1359","type":"match","persona":"any","source":"first step to next","hook":"Match each situation to a calm first step.","pairs":[{"left":"Being hurt right now","right":"Get to safety and call 112"},{"left":"Unsure if it's even abuse","right":"Talk it through on 181"},{"left":"Wanting legal options explained","right":"Ask free legal aid on 15100"},{"left":"Feeling alone with it","right":"Tell one trusted person"},{"left":"Worried about leaving safely","right":"Make a quiet safety plan first"}],"relearn":"There's a calm first step for each spot: 112, 181, 15100, a trusted person, or a quiet safety plan.","cat":"tools-and-help"},
  {"id":"rh-1360","type":"match","persona":"Razia","source":"right not lost","hook":"Match each right to where it still holds.","pairs":[{"left":"Your right to say no","right":"Stays yours inside marriage"},{"left":"Your right to your own money","right":"Marriage doesn't cancel it"},{"left":"Your right to see family","right":"Isolating you from them is abuse"},{"left":"Your right to a safe home","right":"Backed by a residence order"},{"left":"Your right to ask for help","right":"\"Private\" never removes it"}],"relearn":"No, money, family, a safe home and the right to help all stay yours inside a marriage.","cat":"tools-and-help"},
  {"id":"rh-1361","type":"match","persona":"Saxena","source":"do vs avoid","hook":"Match each helping move to its better version.","pairs":[{"left":"Instead of \"just leave him\"","right":"\"What feels safe for you?\""},{"left":"Instead of \"why didn't you go?\"","right":"\"None of this is your fault\""},{"left":"Instead of taking over","right":"\"I'll go at your pace\""},{"left":"Instead of \"are you sure?\"","right":"\"I believe you\""},{"left":"Instead of \"keep it quiet\"","right":"\"Here are the routes when you're ready\""}],"relearn":"Swap pressure and doubt for safety, no blame, the survivor's pace, belief, and routes when they're ready.","cat":"tools-and-help"},
  {"id":"rh-1362","type":"match","persona":"any","source":"abuse form to route","hook":"Match each abuse pattern to a route that fits it.","pairs":[{"left":"He takes my whole wage","right":"Monetary relief under the DV Act 2005"},{"left":"He tracks my every move","right":"Name coercive control; talk to 181"},{"left":"He won't let me stay home","right":"A residence order"},{"left":"He's threatening me now","right":"Call 112"},{"left":"I can't afford to fight it","right":"NALSA legal aid 15100"}],"relearn":"Wage-taking, tracking, eviction, threats and no money each have a route: DV Act, 181, residence order, 112, 15100.","cat":"tools-and-help"},
  {"id":"rh-1363","type":"match","persona":"any","source":"app care","hook":"Match each app promise to what it gives you.","pairs":[{"left":"On-device and private","right":"Your learning stays with you"},{"left":"A quick exit","right":"Leave the screen fast if needed"},{"left":"Calm mode","right":"Gentle pacing, no alarm"},{"left":"\"Get help\" always one tap away","right":"Real routes within reach"},{"left":"No score, no fail","right":"Learn without pressure"}],"relearn":"Private and on-device, a quick exit, calm mode, help one tap away, and no fail: care built into the app.","cat":"tools-and-help"},
  {"id":"rh-1364","type":"match","persona":"Razia","source":"document to use","hook":"Match each thing worth keeping safe to its use.","pairs":[{"left":"ID and address proof","right":"Proving who you are anywhere you go"},{"left":"Bank and ration details","right":"Reaching your own money and rations"},{"left":"Children's papers","right":"School and care without delay"},{"left":"Dated notes of incidents","right":"A record if you seek an order"},{"left":"A spare set of keys","right":"Getting in or out without waiting"}],"relearn":"Keep ID, bank details, children's papers, dated notes and a spare key safe; each has a real use later.","cat":"tools-and-help"},
  {"id":"rh-1365","type":"match","persona":"any","source":"what counts","hook":"Match each line to whether it names abuse or names support.","pairs":[{"left":"\"You can't visit your mother\"","right":"Isolation, a form of control"},{"left":"\"Hand over your salary\"","right":"Economic abuse"},{"left":"\"I believe you\"","right":"Support a survivor needs"},{"left":"\"What do you need from me?\"","right":"Survivor-led help"},{"left":"\"Here's 181 when you're ready\"","right":"A safe, gentle route"}],"relearn":"Cutting off family and seizing pay are abuse; belief, asking, and a gentle route are real support.","cat":"tools-and-help"},
  {"id":"rh-1366","type":"match","persona":"Saxena","source":"feeling to truth","hook":"Match each common feeling to the steadying truth.","pairs":[{"left":"\"It's my shame to carry\"","right":"Shame belongs to the abuser, not you"},{"left":"\"Naming it means I'm weak\"","right":"Naming it is the first brave step"},{"left":"\"No one will believe me\"","right":"You deserve to be believed"},{"left":"\"Men can't be victims\"","right":"Anyone of any gender can be hurt"},{"left":"\"It's too late for help\"","right":"A route still exists today"}],"relearn":"Shame is the abuser's, naming it is brave, you deserve belief, anyone can be hurt, and help is still there.","cat":"tools-and-help"},
  {"id":"rh-1367","type":"sort","persona":"Razia","source":"real route or not","hook":"Sort each one: a real help route, or not?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"Hoping he changes on his own"},{"id":"c","text":"Free legal aid on 15100"},{"id":"d","text":"Telling a trusted person"},{"id":"e","text":"Keeping it all to yourself"},{"id":"f","text":"Calling 112 when in danger"}],"bins":[{"id":"real","label":"Real route","valence":"pos"},{"id":"not","label":"Not a route","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"real","e":"not","f":"real"},"relearn":"181, 15100, a trusted person and 112 are real routes; hoping he changes or staying silent are not.","cat":"tools-and-help"},
  {"id":"rh-1368","type":"sort","persona":"Saxena","source":"helps or harms a survivor","hook":"Sort each response: helps a survivor, or harms?","items":[{"id":"a","text":"\"I believe you\""},{"id":"b","text":"\"What did you do to set him off?\""},{"id":"c","text":"\"It isn't your fault\""},{"id":"d","text":"\"Just keep the peace at home\""},{"id":"e","text":"\"What do you need right now?\""},{"id":"f","text":"\"You must have exaggerated\""}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Belief, no blame and asking what's needed help; blame questions, doubt and 'keep the peace' harm.","cat":"tools-and-help"},
  {"id":"rh-1369","type":"sort","persona":"any","source":"abuse or not","hook":"Sort each one: a form of abuse, or not abuse?","items":[{"id":"a","text":"Taking all her wages by force"},{"id":"b","text":"Disagreeing and talking it out"},{"id":"c","text":"Tracking her phone constantly"},{"id":"d","text":"Sharing chores fairly"},{"id":"e","text":"Cutting her off from family"},{"id":"f","text":"Asking before, and hearing no"}],"bins":[{"id":"abuse","label":"Abuse","valence":"neg"},{"id":"ok","label":"Not abuse","valence":"pos"}],"key":{"a":"abuse","b":"ok","c":"abuse","d":"ok","e":"abuse","f":"ok"},"relearn":"Seizing wages, constant tracking and isolation are abuse; talking it out, fair chores and asking are not.","cat":"tools-and-help"},
  {"id":"rh-1370","type":"sort","persona":"Razia","source":"emergency or not-yet","hook":"Sort each: dial 112 now, or a calmer route first?","items":[{"id":"a","text":"He's hurting you this minute"},{"id":"b","text":"You want to understand your options"},{"id":"c","text":"He has a weapon and is threatening you"},{"id":"d","text":"You'd like to talk things through"},{"id":"e","text":"You fear he'll harm you tonight"},{"id":"f","text":"You want the law explained calmly"}],"bins":[{"id":"now","label":"112 now","valence":"uhoh"},{"id":"calm","label":"Calmer route","valence":"tell"}],"key":{"a":"now","b":"calm","c":"now","d":"calm","e":"now","f":"calm"},"relearn":"Immediate harm or threat means call 112; understanding options or the law can start with 181 or 15100.","cat":"tools-and-help"},
  {"id":"rh-1371","type":"sort","persona":"Saxena","source":"survivor-led or taking over","hook":"Sort each helping move: survivor-led, or taking over?","items":[{"id":"a","text":"\"I'll go at your pace\""},{"id":"b","text":"Calling the police without asking"},{"id":"c","text":"\"What feels safe to you?\""},{"id":"d","text":"Deciding she must leave today"},{"id":"e","text":"Sharing routes when she's ready"},{"id":"f","text":"Telling everyone her secret"}],"bins":[{"id":"led","label":"Survivor-led","valence":"pos"},{"id":"over","label":"Taking over","valence":"neg"}],"key":{"a":"led","b":"over","c":"led","d":"over","e":"led","f":"over"},"relearn":"Going at her pace, asking what's safe and offering routes is survivor-led; deciding or exposing her isn't.","cat":"tools-and-help"},
  {"id":"rh-1372","type":"sort","persona":"Razia","source":"DV Act covers","hook":"Sort each: the DV Act 2005 can address it, or not its job?","items":[{"id":"a","text":"A protection order against harm"},{"id":"b","text":"Choosing your wedding menu"},{"id":"c","text":"The right to stay in your home"},{"id":"d","text":"Maintenance and monetary relief"},{"id":"e","text":"Which film to watch tonight"},{"id":"f","text":"Protection from economic abuse"}],"bins":[{"id":"yes","label":"DV Act can help","valence":"pos"},{"id":"no","label":"Not its job","valence":"neutral"}],"key":{"a":"yes","b":"no","c":"yes","d":"yes","e":"no","f":"yes"},"relearn":"The DV Act 2005 covers protection, residence, maintenance and economic abuse, not everyday choices.","cat":"tools-and-help"},
  {"id":"rh-1373","type":"sort","persona":"any","source":"safety plan piece or not","hook":"Sort each: belongs in a safety plan, or not really?","items":[{"id":"a","text":"A code word with a trusted friend"},{"id":"b","text":"A dated record of incidents"},{"id":"c","text":"Confronting him in anger"},{"id":"d","text":"Copies of your key documents"},{"id":"e","text":"A safe place you can go"},{"id":"f","text":"Waiting and hoping it stops"}],"bins":[{"id":"plan","label":"In the plan","valence":"pos"},{"id":"no","label":"Not the plan","valence":"neg"}],"key":{"a":"plan","b":"plan","c":"no","d":"plan","e":"plan","f":"no"},"relearn":"A code word, dated record, document copies and a safe place belong in a plan; confronting or just waiting don't.","cat":"tools-and-help"},
  {"id":"rh-1374","type":"sort","persona":"any","source":"truth to carry or myth to drop","hook":"Sort each line: a truth to carry, or a myth to drop?","items":[{"id":"a","text":"Consent stays yours inside marriage"},{"id":"b","text":"\"It's only abuse if it's physical\""},{"id":"c","text":"Control is abuse, not love"},{"id":"d","text":"\"What happens at home is private\""},{"id":"e","text":"Help exists for every need here"},{"id":"f","text":"\"If he hurt me, I provoked it\""}],"bins":[{"id":"keep","label":"Truth to carry","valence":"tell"},{"id":"drop","label":"Myth to drop","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"Keep: consent stays yours, control isn't love, help exists. Drop: only-physical, it's-private, I-provoked-it.","cat":"tools-and-help"},
  {"id":"rh-1375","type":"reflect","persona":"any","source":"keep the number","hook":"Lensy: knowing one number, 112, can change a frightening night. Worth keeping close?","prompt":"What do you think?","options":["Yes","I'll remember it","Good to know"],"affirm":"112 reaches help in real danger; keeping it close means one less thing to find when it's hard to think.","relearn":"112 is the emergency route in immediate danger; it's worth keeping close.","cat":"tools-and-help"},
  {"id":"rh-1376","type":"reflect","persona":"any","source":"asking is strength","hook":"Lensy: reaching out for help is strength, not weakness. Does that land?","prompt":"What do you think?","options":["Yes","It's strength","I'm rethinking that"],"affirm":"Naming what's happening and asking for help takes courage; there's a route for every need you might name.","relearn":"Reaching out is strength, and a route exists for every need.","cat":"tools-and-help"},
  {"id":"rh-1377","type":"reflect","persona":"any","source":"education not legal advice","hook":"Lensy: this app explains your routes and the law plainly, but it isn't legal advice. Clear?","prompt":"What do you think?","options":["Clear","Where do I get advice?","Got it"],"affirm":"For a real case, free legal aid on 15100 or a trusted lawyer gives advice; this just helps you find the door.","relearn":"This is educational signposting, not legal advice; 15100 or a lawyer gives real advice.","cat":"tools-and-help"},
  {"id":"rh-1378","type":"reflect","persona":"Reshma","source":"a little footing","hook":"Lensy: even a small bit of your own money or a known number is footing. Want to start small?","prompt":"What feels possible?","options":["A few rupees saved","One trusted number","Knowing routes exist"],"affirm":"Small footing counts: a little saved, one safe number, knowing help exists. Each quiet step is yours.","relearn":"Small steps, savings, a trusted number, knowing routes, build real footing over time.","cat":"tools-and-help"},
  {"id":"rh-1379","type":"reflect","persona":"any","source":"believe first","hook":"Lensy: if someone trusts you with this, believing them first matters most. Agree?","prompt":"What do you think?","options":["Yes","I'll lead with belief","Hadn't thought of it"],"affirm":"Belief is what survivors most fear losing; leading with 'I believe you' opens the door to everything else.","relearn":"Believe a survivor first; it's what they most fear losing.","cat":"tools-and-help"},
  {"id":"rh-1380","type":"reflect","persona":"any","source":"their pace","hook":"Lensy: whether and when to act is the survivor's choice, never ours to push. Sit right with you?","prompt":"What do you think?","options":["Yes","Their choice","I'd want to fix it fast"],"affirm":"Wanting to fix it fast is love, but the survivor knows their own danger best; offer routes, let them lead.","relearn":"Whether and when to act is the survivor's choice; offer routes, don't push.","cat":"tools-and-help"},
  {"id":"rh-1381","type":"reflect","persona":"any","source":"any gender","hook":"Lensy: anyone of any gender can be hurt this way, and deserves the same help. Fit your picture?","prompt":"What do you think?","options":["Yes","Widening my picture","Already believed it"],"affirm":"The pattern, not the gender, defines abuse; men and others silenced by stigma are believed equally here.","relearn":"Anyone of any gender can be a victim and deserves equal belief and help.","cat":"tools-and-help"},
  {"id":"rh-1382","type":"reflect","persona":"any","source":"private is no shield","hook":"Lensy: \"it's private\" is often used to keep abuse hidden, not to protect a family. See it?","prompt":"What do you think?","options":["I see it","Still feels private","Worth questioning"],"affirm":"Privacy protects love and trust, not harm; 'private' is no shield for abuse, and help still reaches in.","relearn":"'Private' is no shield for abuse; help still exists.","cat":"tools-and-help"},
  {"id":"rh-1383","type":"reflect","persona":"any","source":"shame is the abusers","hook":"Lensy: the shame after abuse belongs to the one who caused it, not the one hurt. Set it down?","prompt":"What do you think?","options":["I'll try","It's hard","Yes"],"affirm":"Shame is heavy and rarely yours to carry; it belongs to the abuser. Setting it down is part of healing.","relearn":"Shame belongs to the abuser, not the person harmed.","cat":"tools-and-help"},
  {"id":"rh-1384","type":"reflect","persona":"Razia","source":"the law as a tool","hook":"Lensy: the DV Act 2005 is a tool you can reach for, not a cliff you must jump off. Reassuring?","prompt":"What do you think?","options":["Yes","Good to know","I was scared of it"],"affirm":"You decide whether and when to use it; protection, residence and maintenance orders are options, not orders to you.","relearn":"The DV Act 2005 offers options you choose to use; it doesn't force anything on you.","cat":"tools-and-help"},
  {"id":"rh-1385","type":"reflect","persona":"any","source":"naming it","hook":"Lensy: just naming what's happening, to yourself, is the first real step. Ready to name it?","prompt":"What do you think?","options":["I think so","Not yet","I named it"],"affirm":"There's no rush. Whenever you're ready, naming it is the start; recognition is strength, never weakness.","relearn":"Naming abuse is the first step; recognition is strength.","cat":"tools-and-help"},
  {"id":"rh-1386","type":"reflect","persona":"any","source":"one trusted person","hook":"Lensy: one trusted person who believes you can change everything. Got someone in mind?","prompt":"What comes up?","options":["Yes, one person","I'm not sure","I'll think on it"],"affirm":"It only takes one: a friend, relative or neighbour who believes you and could share a code word.","relearn":"One trusted person who believes you is a real route to safety.","cat":"tools-and-help"},
  {"id":"rh-1387","type":"reflect","persona":"any","source":"control is not love","hook":"Lensy: jealousy and constant checking are control, not proof of love. Does naming it help?","prompt":"What do you think?","options":["It helps","Still confusing","Yes"],"affirm":"Love trusts and frees; control monitors and confines. Naming control for what it is loosens its grip.","relearn":"Control is not love; naming it for what it is helps.","cat":"tools-and-help"},
  {"id":"rh-1388","type":"reflect","persona":"any","source":"routes for every need","hook":"Lensy: for every need we've named, danger, money, the law, a bed, there's a route. Steadying?","prompt":"What do you think?","options":["Yes","Good to remember","I feel less stuck"],"affirm":"112 for danger, 181 to talk, the DV Act 2005 and 15100 for the law, a shelter for a bed: a route each.","relearn":"There's a route for every need: 112, 181, the DV Act 2005, 15100, a shelter.","cat":"tools-and-help"},
  {"id":"rh-1389","type":"reflect","persona":"any","source":"on-device and private","hook":"Lensy: what you do here stays on your device, with a quick exit if you need it. Helpful to know?","prompt":"What do you think?","options":["Yes","That's reassuring","Good"],"affirm":"Your learning stays with you, no score, no fail, calm mode, and a quick exit whenever you need one.","relearn":"This app is private, on-device, with calm mode and a quick exit.","cat":"tools-and-help"},
  {"id":"rh-1390","type":"reflect","persona":"any","source":"not alone","hook":"Lensy: whatever is happening at home, you are not the only one, and you are not alone. Hold onto that?","prompt":"What do you think?","options":["I'll try","Yes","I needed that"],"affirm":"So many have walked this and found help; reaching a trusted person, 181, 1091 or 112 is never weakness.","relearn":"You're not alone; help is real, through a trusted person, 181, 1091 or 112.","cat":"tools-and-help"},
  {"id":"rh-1391","type":"reflect","persona":"Reshma","source":"safe and quiet","hook":"Lensy: you can learn all this quietly, on your own terms, without anyone needing to know. Okay?","prompt":"What feels right?","options":["Quietly is good","I'll go slow","Yes"],"affirm":"No one needs to know you're here. Learn at your pace; the quick exit and calm mode keep it yours.","relearn":"You can learn this quietly and safely, at your own pace.","cat":"tools-and-help"},
  {"id":"rh-1392","type":"branch","persona":"any","source":"unsure if it's abuse","hook":"You're not sure if what's happening counts as abuse. What do you do?","options":[{"text":"Call 181 and talk it through with someone trained","consequence":"You get a calm, informed read on what's happening.","outcome":"clarity","best":true},{"text":"Decide it's probably normal and say nothing","consequence":"181 can tell you what's normal and what isn't, so doubt won't trap you."},{"text":"Wait until it gets much worse","consequence":"Naming it early is safer; 181 can help you understand it now."}],"debrief":"Unsure is reason enough to ask; 181 decides nothing.","relearn":"Unsure it's abuse? 181 can help you understand it, no commitment needed.","cat":"tools-and-help"},
  {"id":"rh-1393","type":"branch","persona":"Razia","source":"wants the law explained","hook":"A woman wants to understand her legal options but fears the cost. What's the route?","options":[{"text":"Point her to NALSA free legal aid on 15100","consequence":"She learns her options, no fee in the way.","outcome":"access","best":true},{"text":"Tell her lawyers are too expensive, drop it","consequence":"Free legal aid on 15100 exists so cost doesn't block her."},{"text":"Give her your own legal opinion as fact","consequence":"Better to route her to 15100; trained aid gives advice."}],"debrief":"Cost shouldn't decide who knows their rights; 15100 is free.","relearn":"Free legal aid on 15100 means cost needn't block anyone from their options.","cat":"tools-and-help"},
  {"id":"rh-1394","type":"branch","persona":"any","source":"friend discloses","hook":"A friend quietly tells you her husband hurts her. What's your first move?","options":[{"text":"Say \"I believe you, it's not your fault, I'm here\"","consequence":"She feels safe enough to keep talking.","outcome":"believed","best":true},{"text":"Ask what she did to upset him","consequence":"Belief, not blame, comes first; 'what did you do' shuts the door."},{"text":"Tell her to leave him tonight","consequence":"Whether and when to leave is hers; start with belief, don't command."}],"debrief":"Believe and remove blame first, then ask what she needs.","relearn":"When someone discloses, lead with belief and no blame, not questions or commands.","cat":"tools-and-help"},
  {"id":"rh-1395","type":"branch","persona":"Reshma","source":"no money of her own","hook":"You have no money of your own and feel trapped. Where to start, quietly?","options":[{"text":"Call 181 to learn about routes and small footing","consequence":"You find options you didn't know existed, privately.","outcome":"options","best":true},{"text":"Decide nothing can change and stop here","consequence":"Even with no money now, 181 can explain maintenance options."},{"text":"Confront him to demand money","consequence":"That can raise risk; a quiet call to 181 is safer first."}],"debrief":"No money of your own is control, not a dead end; 181 can help.","relearn":"With no money of your own, 181 can explain maintenance and quiet first steps.","cat":"tools-and-help"},
  {"id":"rh-1396","type":"branch","persona":"any","source":"immediate danger","hook":"Things have turned dangerous and you fear you'll be hurt now. What do you do?","options":[{"text":"Get to a safer spot and call 112","consequence":"Emergency help is on the way fast.","outcome":"safe","best":true},{"text":"Try to reason with him in the moment","consequence":"In immediate danger, safety and 112 come first; reasoning can wait until you're safe."},{"text":"Wait to see if it passes","consequence":"When harm feels imminent, don't wait; move to safety and call 112."}],"debrief":"In immediate danger, your safety comes first: get to a safer spot and call 112.","relearn":"In immediate danger, get to safety and call 112.","cat":"tools-and-help"},
  {"id":"rh-1397","type":"branch","persona":"Saxena","source":"supporting without taking over","hook":"You want to help a survivor but worry about taking over. How do you help well?","options":[{"text":"Ask \"what do you need?\" and follow their lead","consequence":"They stay in charge of their own choices.","outcome":"survivor-led","best":true},{"text":"Make the calls and decisions for them","consequence":"Taking over removes the little control they have; ask, don't decide."},{"text":"Push your own plan as the only sensible one","consequence":"Your plan may not fit their danger; they're the expert on their safety."}],"debrief":"Good help asks and follows the survivor's lead.","relearn":"Support a survivor by asking what they need and following their lead.","cat":"tools-and-help"},
  {"id":"rh-1398","type":"branch","persona":"any","source":"male survivor","hook":"A man hints he's controlled at home but says \"men don't get hurt\". What do you say?","options":[{"text":"\"Anyone can be hurt this way; I believe you\"","consequence":"He feels he can finally speak.","outcome":"believed","best":true},{"text":"Laugh it off so he doesn't feel embarrassed","consequence":"Making light of it silences him; belief, not jokes, lets him speak."},{"text":"Tell him to just toughen up","consequence":"Abuse isn't about toughness; the same routes apply to him."}],"debrief":"The pattern, not gender, defines abuse; believe him.","relearn":"Anyone of any gender can be hurt; a male survivor deserves equal belief and routes.","cat":"tools-and-help"},
  {"id":"rh-1399","type":"branch","persona":"Reshma","source":"quiet safety planning","hook":"You're thinking ahead in case things worsen, without alerting him. What's a wise quiet step?","options":[{"text":"Keep copies of key papers and one safe number","consequence":"You're a little readier, quietly.","outcome":"prepared","best":true},{"text":"Announce loudly that you know your rights","consequence":"That can raise risk; quiet preparation is safer for you."},{"text":"Do nothing until a crisis forces it","consequence":"A few quiet steps now make a hard moment less overwhelming."}],"debrief":"Quiet planning builds readiness without raising risk.","relearn":"Quiet safety planning, document copies and a trusted number, builds readiness safely.","cat":"tools-and-help"},
  {"id":"rh-1400","type":"spot","persona":"any","source":"catch the blaming lines","hook":"A friend just disclosed abuse. Spot the two responses that BLAME her.","scene":[{"id":"a","text":"\"I believe you\"","trick":false},{"id":"b","text":"\"What did you do to provoke him?\"","trick":true},{"id":"c","text":"\"It's not your fault\"","trick":false},{"id":"d","text":"\"You must have pushed him too far\"","trick":true},{"id":"e","text":"\"What do you need right now?\"","trick":false}],"why":"'What did you do' and 'you pushed him too far' blame the survivor; abuse is always the abuser's doing.","relearn":"Blaming questions put fault on the survivor; belief and 'it's not your fault' are the support that helps.","cat":"tools-and-help"},
  {"id":"rh-1401","type":"spot","persona":"any","source":"catch the wrong help claims","hook":"Spot the two WRONG statements about getting help.","scene":[{"id":"a","text":"112 is for an emergency","trick":false},{"id":"b","text":"181 reaches the Women Helpline","trick":false},{"id":"c","text":"You can only get help if you're physically hurt","trick":true},{"id":"d","text":"15100 reaches free legal aid","trick":false},{"id":"e","text":"Helplines will tell your husband you called","trick":true}],"why":"Help isn't only for physical harm, and helplines won't report back to him; both lines are false.","relearn":"Help is for any form of abuse, and reaching out is confidential; 112, 181, 1091 and 15100 are real routes.","cat":"tools-and-help"},
  {"id":"rh-1402","type":"spot","persona":"any","source":"catch the not-abuse-myths","hook":"Spot the two lines that wrongly shrink what abuse is.","scene":[{"id":"a","text":"Economic abuse counts","trick":false},{"id":"b","text":"\"It's only abuse if he hits me\"","trick":true},{"id":"c","text":"Coercive control counts","trick":false},{"id":"d","text":"\"Words can't be abuse\"","trick":true},{"id":"e","text":"Sexual coercion counts","trick":false}],"why":"'Only if he hits me' and 'words can't be abuse' shrink it; emotional, economic and sexual abuse all count.","relearn":"Abuse is more than physical; emotional, economic, sexual and coercive control all count.","cat":"tools-and-help"},
  {"id":"rh-1403","type":"spot","persona":"Saxena","source":"catch the taking-over moves","hook":"Helping a survivor, spot the two moves that take over her choices.","scene":[{"id":"a","text":"\"What do you need from me?\"","trick":false},{"id":"b","text":"Calling the police without asking her","trick":true},{"id":"c","text":"\"I'll go at your pace\"","trick":false},{"id":"d","text":"Deciding she must leave today","trick":true},{"id":"e","text":"\"I believe you\"","trick":false}],"why":"Calling police unasked and deciding she must leave take over; survivor-led help asks and follows her lead.","relearn":"Taking over removes a survivor's control; ask what she needs and respect her pace and choices.","cat":"tools-and-help"},
  {"id":"rh-1404","type":"spot","persona":"any","source":"catch the control-as-love lines","hook":"Spot the two lines that dress up control as love.","scene":[{"id":"a","text":"\"I trust you with your own friends\"","trick":false},{"id":"b","text":"\"I check your phone because I love you\"","trick":true},{"id":"c","text":"\"Your money is yours to decide\"","trick":false},{"id":"d","text":"\"You can't see your family, it's for us\"","trick":true},{"id":"e","text":"\"Let's decide big things together\"","trick":false}],"why":"Phone-checking and cutting off family aren't love; they're monitoring and isolation, forms of control.","relearn":"Monitoring and isolation are control, not love; trust and an equal say are the real thing.","cat":"tools-and-help"},
  {"id":"rh-1405","type":"spot","persona":"Razia","source":"catch the wrong DV Act claims","hook":"Spot the two WRONG claims about the DV Act 2005.","scene":[{"id":"a","text":"It can give a protection order","trick":false},{"id":"b","text":"It only covers physical violence","trick":true},{"id":"c","text":"It can secure a residence order","trick":false},{"id":"d","text":"It only protects married women","trick":true},{"id":"e","text":"It can grant maintenance","trick":false}],"why":"It covers emotional, sexual and economic abuse too, and shared-household relationships, not only married women.","relearn":"The DV Act 2005 covers many forms of abuse and shared-household relationships, with protection and relief orders.","cat":"tools-and-help"},
  {"id":"rh-1406","type":"spot","persona":"any","source":"catch the private-shield lines","hook":"Spot the two lines that use \"private\" to hide harm.","scene":[{"id":"a","text":"\"Help exists even for things at home\"","trick":false},{"id":"b","text":"\"What happens at home is no one's business\"","trick":true},{"id":"c","text":"\"You're allowed to reach out\"","trick":false},{"id":"d","text":"\"It's our marriage, so no one can help\"","trick":true},{"id":"e","text":"\"A trusted person can be a lifeline\"","trick":false}],"why":"'No one's business' and 'no one can help' use privacy as a shield; abuse isn't private, and help reaches in.","relearn":"'Private' is no shield for abuse; reaching out is allowed, and help exists for things at home.","cat":"tools-and-help"},
  {"id":"rh-1407","type":"role-play","persona":"any","source":"asking 181 for help","hook":"You've decided to call the Women Helpline 181 for the first time.","setup":"What do you say?","yourLine":[{"text":"\"Hi, I need to talk about what's happening at home. Can you help me understand my options?\"","best":true},{"text":"\"Sorry to bother you, it's probably nothing, never mind.\""},{"text":"\"I shouldn't have called.\""}],"relearn":"On 181 you can simply say you need to talk and ask about your options; you're not bothering anyone.","cat":"tools-and-help"},
  {"id":"rh-1408","type":"role-play","persona":"any","source":"supporting a friend","hook":"A friend has just told you she's being hurt at home.","setup":"What do you say first?","yourLine":[{"text":"\"I believe you. None of this is your fault, and I'm here.\"","best":true},{"text":"\"Are you sure you're not exaggerating a bit?\""},{"text":"\"What did you do to make him so angry?\""}],"relearn":"Lead with belief and no blame: 'I believe you, it's not your fault, I'm here.'","cat":"tools-and-help"},
  {"id":"rh-1409","type":"role-play","persona":"Reshma","source":"naming economic abuse","hook":"You want to tell a counsellor that you have no money of your own.","setup":"How do you put it?","yourLine":[{"text":"\"He takes my whole income and gives me nothing. I want to understand my options.\"","best":true},{"text":"\"It's fine, he just handles the money because he earns it.\""},{"text":"\"Maybe I just spend too much, it's my fault.\""}],"relearn":"Naming it plainly, 'he controls all the money and leaves me none', is naming economic abuse.","cat":"tools-and-help"},
  {"id":"rh-1410","type":"role-play","persona":"any","source":"asking for legal aid","hook":"You can't afford a lawyer but want your options explained.","setup":"What do you say to free legal aid?","yourLine":[{"text":"\"I can't afford a lawyer. Can free legal aid explain my options under the DV Act 2005?\"","best":true},{"text":"\"I have no money, so there's no point asking, right?\""},{"text":"\"Forget it, I'll just manage somehow.\""}],"relearn":"Free legal aid on 15100 is for exactly this; ask it to explain your options under the DV Act 2005.","cat":"tools-and-help"},
  {"id":"rh-1411","type":"role-play","persona":"Saxena","source":"offering routes not orders","hook":"A survivor isn't ready to act yet.","setup":"How do you offer help without pushing?","yourLine":[{"text":"\"Whenever you're ready, here are the routes. I'll go at your pace.\"","best":true},{"text":"\"You have to leave him today or I can't help you.\""},{"text":"\"If you don't act now, that's on you.\""}],"relearn":"Offer routes at the survivor's pace, never an ultimatum: 'whenever you're ready, here are the routes.'","cat":"tools-and-help"},
  {"id":"rh-1412","type":"role-play","persona":"any","source":"setting a code word","hook":"You want to agree a code word with a trusted friend for quick help if ever needed.","setup":"What do you say?","yourLine":[{"text":"\"If I ever text you 'send the recipe', please call for help.\"","best":true},{"text":"\"Never mind, I don't want to worry you with this.\""},{"text":"\"It's silly, forget I said anything.\""}],"relearn":"A code word with a trusted person lets you signal for help quickly, without saying it aloud.","cat":"tools-and-help"},
  {"id":"rh-1413","type":"role-play","persona":"any","source":"male survivor speaking up","hook":"You're a man being controlled and belittled at home, talking to someone you trust.","setup":"What do you say?","yourLine":[{"text":"\"This is hard to say, but I'm being controlled at home and I need help.\"","best":true},{"text":"\"It's nothing, men don't really get hurt like that.\""},{"text":"\"I should just handle it myself.\""}],"relearn":"Anyone of any gender can be hurt; saying 'I'm being controlled and I need help' is strength, not weakness.","cat":"tools-and-help"},
  {"id":"rh-1414","type":"role-play","persona":"any","source":"declining to take over","hook":"A survivor you're helping says she's not ready for police.","setup":"How do you respond?","yourLine":[{"text":"\"That's your call. Tell me what would feel safe, and we'll start there.\"","best":true},{"text":"\"I'm calling them anyway, it's for your own good.\""},{"text":"\"Then I can't do anything for you.\""}],"relearn":"Respect the survivor's choice; ask what feels safe instead of overriding them.","cat":"tools-and-help"},
  {"id":"rh-1415","type":"strike-rewrite","persona":"any","source":"only physical","hook":"Strike the myth, write the truth.","myth":{"un":"\"It's only abuse if there are bruises.\"","re":"Abuse can be emotional, economic, sexual or coercive control, not only physical.","why":"India's DV Act 2005 recognises emotional, sexual and economic abuse, not just physical harm."},"relearn":"Abuse is more than physical; emotional, economic, sexual and coercive control all count.","cat":"tools-and-help"},
  {"id":"rh-1416","type":"strike-rewrite","persona":"Reshma","source":"he earns it","hook":"Strike the myth, write the truth.","myth":{"un":"\"He controls all the money because he earns it, that's just practical.\"","re":"Withholding money to deny your independence is economic abuse, not practicality.","why":"Cutting off your access to money to trap or control you is a recognised form of abuse."},"relearn":"Controlling money to deny your independence is economic abuse, not 'just practical'.","cat":"tools-and-help"},
  {"id":"rh-1417","type":"strike-rewrite","persona":"any","source":"private no help","hook":"Strike the myth, write the truth.","myth":{"un":"\"What happens between a couple is private, so no one can help.\"","re":"'Private' is no shield for abuse; real help and protection exist.","why":"Abuse isn't a private family matter; routes like 181, 112 and the DV Act 2005 exist to reach in."},"relearn":"'Private' is no shield; help and protection exist for abuse at home.","cat":"tools-and-help"},
  {"id":"rh-1418","type":"strike-rewrite","persona":"any","source":"reaching out makes it worse","hook":"Strike the myth, write the truth.","myth":{"un":"\"If I call a helpline, it'll only make things more dangerous for me.\"","re":"Helplines plan safety with you; you choose each step at your own pace.","why":"Lines like 181 and 1091 are confidential and survivor-led; they help you build a safety plan, not force any action."},"relearn":"A helpline plans safety on your terms; reaching out is a step you control.","cat":"tools-and-help"},
  {"id":"rh-1419","type":"strike-rewrite","persona":"any","source":"jealousy is love","hook":"Strike the myth, write the truth.","myth":{"un":"\"His jealousy and checking my phone just show how much he loves me.\"","re":"Monitoring and jealous control are abuse, not signs of love.","why":"Love trusts and frees; surveillance and control confine, and they are coercive control."},"relearn":"Jealousy, monitoring and control are not love; they're coercive control.","cat":"tools-and-help"},
  {"id":"rh-1420","type":"strike-rewrite","persona":"any","source":"marriage means yes","hook":"Strike the myth, write the truth.","myth":{"un":"\"Once you're married, sex is always owed, you can't say no.\"","re":"Consent stays yours inside marriage; you can say no at any time.","why":"Marriage is not standing consent; your body remains your own and a past yes isn't a permanent yes."},"relearn":"Marriage is not standing consent; you can say no any time and your body stays yours.","cat":"tools-and-help"},
  {"id":"rh-1421","type":"strike-rewrite","persona":"any","source":"men cant be victims","hook":"Strike the myth, write the truth.","myth":{"un":"\"Men can't really be victims of abuse at home.\"","re":"Anyone of any gender can be a victim and deserves equal support.","why":"The pattern of control and harm, not the gender, defines abuse; silenced survivors are believed equally."},"relearn":"Anyone of any gender can be a victim; the pattern, not the gender, defines abuse.","cat":"tools-and-help"},
  {"id":"rh-1422","type":"strike-rewrite","persona":"any","source":"too late for help","hook":"Strike the myth, write the truth.","myth":{"un":"\"I've stayed this long, so it's too late to get any help.\"","re":"Staying is never a reason for blame, and a route still exists today.","why":"Survivors stay for many safe and complex reasons; help, through 181, 1091, 112 or a trusted person, remains."},"relearn":"Staying is never a reason for blame; help still exists, whenever you reach for it.","cat":"tools-and-help"},
];

